import Cocoa

// MARK: - Progress bar

final class ProgressBar: NSView {
    var progress: CGFloat = 0 { didSet { if progress != oldValue { needsDisplay = true } } }
    var reached = false { didSet { if reached != oldValue { needsDisplay = true } } }

    override func draw(_ dirtyRect: NSRect) {
        NSColor.quaternaryLabelColor.setFill()
        bounds.fill()
        (reached ? NSColor.systemGreen : NSColor.controlAccentColor).setFill()
        NSRect(x: 0, y: 0, width: bounds.width * min(1, max(0, progress)), height: bounds.height).fill()
    }
}

// MARK: - App

final class AppDelegate: NSObject, NSApplicationDelegate, NSTextViewDelegate, NSWindowDelegate {
    let defaults = UserDefaults.standard
    let columnWidth: CGFloat = 680
    let statusHeight: CGFloat = 30

    var window: NSWindow!
    var scroll: NSScrollView!
    var textView: NSTextView!
    var label: NSTextField!
    var bar: ProgressBar!

    var fileURL: URL?
    var dirty = false { didSet { updateTitle() } }
    var goal: Int { get { defaults.integer(forKey: "goal") } set { defaults.set(newValue, forKey: "goal") } }
    var countTimer: Timer?
    var saveTimer: Timer?

    // MARK: Launch

    func applicationDidFinishLaunching(_ notification: Notification) {
        if defaults.object(forKey: "goal") == nil { goal = 1000 }
        buildMenu()
        buildWindow()

        if let path = defaults.string(forKey: "lastFile"),
           let text = try? String(contentsOfFile: path, encoding: .utf8) {
            fileURL = URL(fileURLWithPath: path)
            textView.string = text
            textView.setSelectedRange(NSRange(location: (text as NSString).length, length: 0))
            textView.scrollRangeToVisible(textView.selectedRange())
        }
        dirty = false
        updateCount()
        window.makeKeyAndOrderFront(nil)
        window.makeFirstResponder(textView)
        NSApp.activate(ignoringOtherApps: true)
    }

    func applicationShouldTerminateAfterLastWindowClosed(_ sender: NSApplication) -> Bool { true }

    func applicationShouldTerminate(_ sender: NSApplication) -> NSApplication.TerminateReply {
        confirmDiscard() ? .terminateNow : .terminateCancel
    }

    func windowShouldClose(_ sender: NSWindow) -> Bool { confirmDiscard() }

    func windowDidResize(_ notification: Notification) { updateInsets() }

    // MARK: UI

    func buildWindow() {
        let frame = NSRect(x: 0, y: 0, width: 960, height: 720)
        window = NSWindow(contentRect: frame,
                          styleMask: [.titled, .closable, .miniaturizable, .resizable, .fullSizeContentView],
                          backing: .buffered, defer: false)
        window.delegate = self
        window.center()
        window.setFrameAutosaveName("MainWindow")
        window.titlebarAppearsTransparent = true
        window.isReleasedWhenClosed = false
        window.collectionBehavior = [.fullScreenPrimary]

        let content = NSView(frame: frame)
        content.autoresizingMask = [.width, .height]
        window.contentView = content

        scroll = NSTextView.scrollableTextView()
        textView = scroll.documentView as? NSTextView
        scroll.frame = NSRect(x: 0, y: statusHeight, width: frame.width, height: frame.height - statusHeight)
        scroll.autoresizingMask = [.width, .height]
        scroll.hasVerticalScroller = true
        scroll.autohidesScrollers = true
        scroll.scrollerStyle = .overlay
        scroll.drawsBackground = false
        content.addSubview(scroll)

        let font = NSFont(name: "Georgia", size: 19) ?? NSFont.systemFont(ofSize: 19)
        let para = NSMutableParagraphStyle()
        para.lineSpacing = 7
        para.paragraphSpacing = 10
        textView.delegate = self
        textView.isRichText = false
        textView.allowsUndo = true
        textView.usesFindBar = true
        textView.isIncrementalSearchingEnabled = true
        textView.font = font
        textView.defaultParagraphStyle = para
        textView.typingAttributes = [.font: font, .paragraphStyle: para, .foregroundColor: NSColor.textColor]
        textView.textColor = .textColor
        textView.drawsBackground = false
        textView.insertionPointColor = .controlAccentColor
        textView.isAutomaticQuoteSubstitutionEnabled = true
        textView.isAutomaticDashSubstitutionEnabled = true
        textView.isAutomaticSpellingCorrectionEnabled = false
        window.backgroundColor = .textBackgroundColor

        let status = NSView(frame: NSRect(x: 0, y: 0, width: frame.width, height: statusHeight))
        status.autoresizingMask = [.width]
        content.addSubview(status)

        bar = ProgressBar(frame: NSRect(x: 0, y: statusHeight - 2, width: frame.width, height: 2))
        bar.autoresizingMask = [.width, .minYMargin]
        status.addSubview(bar)

        label = NSTextField(labelWithString: "")
        label.font = NSFont.monospacedDigitSystemFont(ofSize: 12, weight: .regular)
        label.textColor = .secondaryLabelColor
        label.alignment = .center
        label.frame = NSRect(x: 0, y: 4, width: frame.width, height: 18)
        label.autoresizingMask = [.width]
        status.addSubview(label)

        updateInsets()
    }

    func updateInsets() {
        let w = scroll.contentSize.width
        textView.textContainerInset = NSSize(width: max(24, (w - columnWidth) / 2), height: 48)
    }

    func updateTitle() {
        window?.title = (fileURL?.lastPathComponent ?? "Untitled")
        window?.isDocumentEdited = dirty
    }

    // MARK: Word count

    func textDidChange(_ notification: Notification) {
        dirty = true
        countTimer?.invalidate()
        countTimer = Timer.scheduledTimer(withTimeInterval: 0.15, repeats: false) { [weak self] _ in self?.updateCount() }
        if fileURL != nil {
            saveTimer?.invalidate()
            saveTimer = Timer.scheduledTimer(withTimeInterval: 3, repeats: false) { [weak self] _ in
                guard let self = sel

