import Cocoa

// MARK: - Model

struct Note: Codable {
    var id = UUID()
    var text = ""
    var x: Double
    var y: Double
    var w: Double = 260
    var h: Double = 260
    var color = 0
}

let noteColors: [(name: String, color: NSColor)] = [
    ("Yellow", NSColor(calibratedRed: 1.00, green: 0.96, blue: 0.62, alpha: 1)),
    ("Pink",   NSColor(calibratedRed: 1.00, green: 0.80, blue: 0.86, alpha: 1)),
    ("Blue",   NSColor(calibratedRed: 0.76, green: 0.89, blue: 1.00, alpha: 1)),
    ("Green",  NSColor(calibratedRed: 0.79, green: 0.95, blue: 0.78, alpha: 1)),
]

// MARK: - Persistence

final class Store {
    private let url: URL
    private var pending: DispatchWorkItem?
    var notes: [Note] = []

    init() {
        let dir = FileManager.default.urls(for: .applicationSupportDirectory, in: .userDomainMask)[0]
            .appendingPathComponent("StickyNotes", isDirectory: true)
        try? FileManager.default.createDirectory(at: dir, withIntermediateDirectories: true)
        url = dir.appendingPathComponent("notes.json")
        if let data = try? Data(contentsOf: url),
           let decoded = try? JSONDecoder().decode([Note].self, from: data) {
            notes = decoded
        }
    }

    func index(of id: UUID) -> Int? { notes.firstIndex { $0.id == id } }

    func scheduleSave() {
        pending?.cancel()
        let item = DispatchWorkItem { [weak self] in self?.saveNow() }
        pending = item
        DispatchQueue.main.asyncAfter(deadline: .now() + 0.5, execute: item)
    }

    func saveNow() {
        pending?.cancel()
        pending = nil
        guard let data = try? JSONEncoder().encode(notes) else { return }
        try? data.write(to: url, options: .atomic)
    }
}

// MARK: - Window

final class NoteWindow: NSPanel {
    let noteID: UUID
    let textView: NSTextView

    init(note: Note) {
        noteID = note.id
        let scroll = NSTextView.scrollableTextView()
        textView = scroll.documentView as! NSTextView
        super.init(
            contentRect: NSRect(x: note.x, y: note.y, width: note.w, height: note.h),
            styleMask: [.titled, .closable, .resizable, .fullSizeContentView, .utilityWindow],
            backing: .buffered, defer: false)

        isFloatingPanel = true
        level = .floating
        hidesOnDeactivate = false
        isReleasedWhenClosed = false
        collectionBehavior = [.canJoinAllSpaces, .fullScreenAuxiliary]
        titleVisibility = .hidden
        titlebarAppearsTransparent = true
        isMovableByWindowBackground = true
        appearance = NSAppearance(named: .aqua)
        minSize = NSSize(width: 140, height: 100)

        textView.string = note.text
        textView.font = .systemFont(ofSize: 14)
        textView.textColor = .black
        textView.insertionPointColor = .black
        textView.drawsBackground = false
        textView.isRichText = false
        textView.allowsUndo = true
        textView.textContainerInset = NSSize(width: 6, height: 6)
        scroll.drawsBackground = false
        scroll.hasVerticalScroller = true
        scroll.autohidesScrollers = true
        contentView = scroll
        applyColor(note.color)
    }

    func applyColor(_ index: Int) {
        backgroundColor = noteColors[index % noteColors.count].color
    }

    override var canBecomeKey: Bool { true }
}

// MARK: - App

final class AppDelegate: NSObject, NSApplicationDelegate, NSWindowDelegate, NSTextViewDelegate {
    let store = Store()
    var windows: [UUID: NoteWindow] = [:]

    func applicationDidFinishLaunching(_ notification: Notification) {
        buildMenu()
        if store.notes.isEmpty { newNote() }
        else { store.notes.forEach(show) }
        NSApp.activate(ignoringOtherApps: true)
    }

    func applicationShouldTerminateAfterLastWindowClosed(_ sender: NSApplication) -> Bool { false }

    func applicationShouldHandleReopen(_ sender: NSApplication, hasVisibleWindows flag: Bool) -> Bool {
        if windows.isEmpty { newNote() }
        return true
    }

    func applicationWillTerminate(_ notification: Notification) { sync(); store.saveNow() }

    // Notes

    func show(_ note: Note) {
        let w = NoteWindow(note: note)
        w.delegate = self
        w.textView.delegate = self
        windows[note.id] = w
        w.makeKeyAndOrderFront(nil)
    }

    @objc func newNote() {
        let screen = NSScreen.main?.visibleFrame ?? NSRect(x: 0, y: 0, width: 800, height: 600)
        let offset = Double(windows.count % 8) * 28
        let note = Note(x: Double(screen.minX) + 80 + offset,
                        y: Double(screen.maxY) - 340 - offset,
                        color: store.notes.count % noteColors.count)
        store.notes.append(note)
        show(note)
        store.scheduleSave()
    }

    func sync() {
        for (id, w) in windows {
            guard let i = store.index(of: id) else { continue }
            store.notes[i].text = w.textView.string
            store.notes[i].x = Double(w.frame.origin.x)
            store.notes[i].y = Double(w.frame.origin.y)
            store.notes[i].w = Double(w.frame.size.width)
            store.notes[i].h = Double(w.frame.size.height)
        }
    }

    func changed() { sync(); store.scheduleSave() }

    func textDidChange(_ notification: Notification) { changed() }
    func windowDidMove(_ notification: Notification) { changed() }
    func windowDidResize(_ notification: Notification) { changed() }

    func windowShouldClose(_ sender: NSWindow) -> Bool {
        guard let w = sender as? NoteWindow else { return true }
        if !w.textView.string.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
            let alert = NSAlert()
            alert.messageText = "Delete this note?"
            alert.informativeText = "This cannot be undone."
            alert.addButton(withTitle: "Delete")
            alert.addButton(withTitle: "Cancel")
            alert.beginSheetModal(for: w) { [weak self] response in

