"""SM-2 style spaced repetition scheduling. Pure functions, no I/O."""
from datetime import date, timedelta

AGAIN, HARD, GOOD, EASY = range(4)
MIN_EASE = 1.3
START_EASE = 2.5


def review(ease, interval, reps, lapses, grade, today=None):
    """Return (ease, interval_days, reps, lapses, due_date) after a review."""
    today = today or date.today()
    if grade == AGAIN:
        ease = max(MIN_EASE, ease - 0.2)
        return ease, 0, 0, lapses + 1, today

    if reps == 0:
        new = {HARD: 1, GOOD: 1, EASY: 4}[grade]
    elif reps == 1:
        new = {HARD: 3, GOOD: 6, EASY: 8}[grade]
    else:
        factor = {HARD: 1.2, GOOD: ease, EASY: ease * 1.3}[grade]
        new = max(interval + 1, round(interval * factor))

    if grade == HARD:
        ease = max(MIN_EASE, ease - 0.15)
    elif grade == EASY:
        ease += 0.15
    return ease, new, reps + 1, lapses, today + timedelta(days=new)


def preview(ease, interval, reps, lapses, today=None):
    """Interval in days each grade would produce, indexed by grade."""
    return [review(ease, interval, reps, lapses, g, today)[1] for g in range(4)]


def fmt_interval(days):
    if days <= 0:
        return "<1d"
    if days < 30:
        return f"{days}d"
    if days < 365:
        return f"{days / 30:.1f}mo"
    return f"{days / 365:.1f}y"

