private let SQLITE_TRANSIENT = unsafeBitCast(-1, to: sqlite3_destructor_type.self)

enum Kind: Int32 { case text = 0, image = 1 }

/// Lightweight row for the list; full payloads are loaded only when an item is chosen.
struct Row {
    let id: Int64
    let kind: Kind
    let preview: String
    let imagePath: String?
    let width: Int
    let height: Int
}

final class Store {
    static let maxItems = 1000
    static let maxTextBytes = 1_000_000

    private var db: OpaquePointer?
    private let dir: URL
    private let imageDir: URL

    init() {
        let base = FileManager.default.urls(for: .applicationSupportDirectory, in: .userDomainMask)[0]
        dir = base.appendingPathComponent("Clipo", isDirectory: true)
        imageDir = dir.appendingPathComponent("images", isDirectory: true)
        try? FileManager.default.createDirectory(at: imageDir, withIntermediateDirectories: true)
        sqlite3_open(dir.appendingPathComponent("history.sqlite").path, &db)
        exec("PRAGMA journal_mode=WAL")
        exec("PRAGMA synchronous=NORMAL")
        exec("""
            CREATE TABLE IF NOT EXISTS items(
                id INTEGER PRIMARY KEY,
                kind INTEGER NOT NULL,
                text TEXT,
                image_path TEXT,
                w INTEGER, h INTEGER,
                hash TEXT NOT NULL UNIQUE,
                created REAL NOT NULL
            )
            """)
        exec("CREATE INDEX IF NOT EXISTS items_created ON items(created)")
    }

    private func exec(_ sql: String) {
        sqlite3_exec(db, sql, nil, nil, nil)
    }

    private func hex(_ data: Data) -> String {
        SHA256.hash(data: data).map { String(format: "%02x", $0) }.joined()
    }

    /// Bumps an existing entry to the top. Returns true if one existed.
    private func touch(hash: String) -> Bool {
        var st: OpaquePointer?
        sqlite3_prepare_v2(db, "UPDATE items SET created=? WHERE hash=?", -1, &st, nil)
        defer { sqlite3_finalize(st) }
        sqlite3_bind_double(st, 1, Date().timeIntervalSince1970)
        sqlite3_bind_text(st, 2, hash, -1, SQLITE_TRANSIENT)
        sqlite3_step(st)
        return sqlite3_changes(db) > 0
    }

    func addText(_ text: String) {
        guard text.utf8.count <= Store.maxTextBytes,
              !text.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty else { return }
        let h = hex(Data(text.utf8))
        if touch(hash: h) { return }
        var st: OpaquePointer?
        sqlite3_prepare_v2(db, "INSERT INTO items(kind,text,hash,created) VALUES(0,?,?,?)", -1, &st, nil)
        defer { sqlite3_finalize(st) }
        sqlite3_bind_text(st, 1, text, -1, SQLITE_TRANSIENT)
        sqlite3_bind_text(st, 2, h, -1, SQLITE_TRANSIENT)
        sqlite3_bind_double(st, 3, Date().timeIntervalSince1970)
        sqlite3_step(st)
        prune()
    }

    func addImage(png: Data, width: Int, height: Int) {
        let h = hex(png)
        if touch(hash: h) { return }
        let name = h + ".png"
        guard (try? png.write(to: imageDir.appendingPathComponent(name))) != nil else { return }
        var st: OpaquePointer?
        sqlite3_prepare_v2(db, "INSERT INTO items(kind,image_path,w,h,hash,created) VALUES(1,?,?,?,?,?)", -1, &st, nil)
        defer { sqlite3_finalize(st) }
        sqlite3_bind_text(st, 1, name, -1, SQLITE_TRANSIENT)
        sqlite3_bind_int(st, 2, Int32(width))
        sqlite3_bind_int(st, 3, Int32(height))
        sqlite3_bind_text(st, 4, h, -1, SQLITE_TRANSIENT)
        sqlite3_bind_double(st, 5, Date().timeIntervalSince1970)
        sqlite3_step(st)
        prune()
    }

    private func prune() {
        let old = "SELECT id FROM items ORDER BY created DESC LIMIT -1 OFFSET \(Store.maxItems)"
        var st: OpaquePointer?
        sqlite3_prepare_v2(db, "SELECT image_path FROM items WHERE image_path IS NOT NULL AND id IN (\(old))", -1, &st, nil)
        while sqlite3_step(st) == SQLITE_ROW {
            if let c = sqlite3_column_text(st, 0) {
                try? FileManager.default.removeItem(at: imageDir.appendingPathComponent(String(cString: c)))
            }
        }
        sqlite3_finalize(st)
        exec("DELETE FROM items WHERE id IN (\(old))")
    }

    func clear() {
        exec("DELETE FROM items")
        try? FileManager.default.removeItem(at: imageDir)
        try? FileManager.default.createDirectory(at: imageDir, withIntermediateDirectories: true)
    }

    func search(_ query: String, limit: Int = 200) -> [Row] {
        var sql = "SELECT id,kind,substr(text,1,200),image_path,w,h FROM items"
        let q = query.trimmingCharacters(in: .whitespacesAndNewlines)
        if !q.isEmpty { sql += " WHERE text LIKE ? ESCAPE '\\'" }
        sql += " ORDER BY created DESC LIMIT \(limit)"
        var st: OpaquePointer?
        sqlite3_prepare_v2(db, sql, -1, &st, nil)
        defer { sqlite3_finalize(st) }
        if !q.isEmpty {
            let esc = q.replacingOccurrences(of: "\\", with: "\\\\")
                .replacingOccurrences(of: "%", with: "\\%")
                .replacingOccurrences(of: "_", with: "\\_")
            sqlite3_bind_text(st, 1, "%\(esc)%", -1, SQLITE_TRANSIENT)
        }
        var rows: [Row] = []
