            let kind = Kind(rawValue: sqlite3_column_int(st, 1)) ?? .text
            let text = sqlite3_column_text(st, 2).map { String(cString: $0) } ?? ""
            let path = sqlite3_column_text(st, 3).map { String(cString: $0) }
