/// Polls NSPasteboard.changeCount (the only cheap option; macOS has no change notification).
final class Monitor {
    private let store: Store
    private var lastCount = NSPasteboard.general.changeCount
    private var timer: Timer?

    private static let skipTypes: Set<String> = [
        "org.nspasteboard.ConcealedType", "org.nspasteboard.TransientType",
        "org.nspasteboard.AutoGeneratedType", "com.agilebits.onepassword",
    ]

    init(store: Store) { self.store = store }

    func start() {
        let t = Timer(timeInterval: 0.5, repeats: true) { [weak self] _ in self?.poll() }
        t.tolerance = 0.25
        RunLoop.main.add(t, forMode: .common)
        timer = t
    }

    /// Call after writing to the pasteboard ourselves so it isn't recorded again.
    func ignoreCurrent() { lastCount = NSPasteboard.general.changeCount }

    private func poll() {
        let pb = NSPasteboard.general
        guard pb.changeCount != lastCount else { return }
        lastCount = pb.changeCount
        let types = Set((pb.types ?? []).map { $0.rawValue })
        if !types.isDisjoint(with: Monitor.skipTypes) { return }

        autoreleasepool {
            if let s = pb.string(forType: .string) {
                store.addText(s)
            } else if let data = pb.data(forType: .png) ?? pb.data(forType: .tiff),
                      let rep = NSBitmapImageRep(data: data),
                      let png = rep.representation(using: .png, properties: [:]) {
                store.addImage(png: png, width: rep.pixelsWide, height: rep.pixelsHigh)
            }
        }
    }
}

