import AppKit

// MARK: - Date helpers
// Days are stored as integers (days since 1970-01-01, local calendar date),
// which keeps the data compact and makes streak math trivial.

func daysFromCivil(_ y: Int, _ m: Int, _ d: Int) -> Int {
    let y = m <= 2 ? y - 1 : y
    let era = (y >= 0 ? y : y - 399) / 400
    let yoe = y - era * 400
    let doy = (153 * (m + (m > 2 ? -3 : 9)) + 2) / 5 + d - 1
    let doe = yoe * 365 + yoe / 4 - yoe / 100 + doy
    return era * 146097 + doe - 719468
}

func civilFromDays(_ z: Int) -> (y: Int, m: Int, d: Int) {
    let z = z + 719468
    let era = (z >= 0 ? z : z - 146096) / 146097
    let doe = z - era * 146097
    let yoe = (doe - doe / 1460 + doe / 36524 - doe / 146096) / 365
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100)
    let mp = (5 * doy + 2) / 153
    let d = doy - (153 * mp + 2) / 5 + 1
    let m = mp < 10 ? mp + 3 : mp - 9
    return (yoe + era * 400 + (m <= 2 ? 1 : 0), m, d)
}

/// Monday = 0 ... Sunday = 6
func weekday(_ day: Int) -> Int { ((day + 3) % 7 + 7) % 7 }

func todayNumber() -> Int {
    let c = Calendar.current.dateComponents([.year, .month, .day], from: Date())
    return daysFromCivil(c.year!, c.month!, c.day!)
}

// MARK: - Model

struct Habit: Codable {
    var id = UUID()
    var name: String
    var days = Set<Int>()

    func currentStreak(today: Int) -> Int {
        var d = days.contains(today) ? today : today - 1
        var n = 0
        while days.contains(d) { n += 1; d -= 1 }
        return n
    }

    var longestStreak: Int {
        var best = 0, run = 0, prev = Int.min
        for d in days.sorted() {
            run = (d == prev + 1) ? run + 1 : 1
            best = max(best, run)
            prev = d
        }
        return best
    }
}

final class Store {
    var habits: [Habit] = []
    private let url: URL

    init() {
        let dir = FileManager.default.urls(for: .applicationSupportDirectory, in: .userDomainMask)[0]
            .appendingPathComponent("HabitTracker", isDirectory: true)
        try? FileManager.default.createDirectory(at: dir, withIntermediateDirectories: true)
        url = dir.appendingPathComponent("habits.json")
        if let data = try? Data(contentsOf: url),
           let decoded = try? JSONDecoder().decode([Habit].self, from: data) {
            habits = decoded
        }
    }

    func save() {
        guard let data = try? JSONEncoder().encode(habits) else { return }
        try? data.write(to: url, options: .atomic)
    }
}

// MARK: - Heatmap

final class HeatmapView: NSView {
    var days = Set<Int>() { didSet { needsDisplay = true } }
    var year = 2026 { didSet { needsDisplay = true } }
    var onToggle: ((Int) -> Void)?

    private let cell: CGFloat = 13
    private let gap: CGFloat = 3
    private let left: CGFloat = 34
    private let top: CGFloat = 22
    private var step: CGFloat { cell + gap }

    override var isFlipped: Bool { true }
    override var intrinsicContentSize: NSSize {
        NSSize(width: left + 54 * step, height: top + 7 * step)
    }

    private var firstDay: Int { daysFromCivil(year, 1, 1) }
    private var dayCount: Int { daysFromCivil(year + 1, 1, 1) - firstDay }

    override func draw(_ dirtyRect: NSRect) {
        let today = todayNumber()
        let d0 = firstDay
        let offset = weekday(d0)
        let attrs: [NSAttributedString.Key: Any] = [
            .font: NSFont.systemFont(ofSize: 10),
            .foregroundColor: NSColor.secondaryLabelColor,
        ]

        let months = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"]
        for m in 1...12 {
            let col = (offset + daysFromCivil(year, m, 1) - d0) / 7
            months[m - 1].draw(at: NSPoint(x: left + CGFloat(col) * step, y: 3), withAttributes: attrs)
        }
        for (row, name) in [(0, "Mon"), (2, "Wed"), (4, "Fri")] {
            name.draw(at: NSPoint(x: 2, y: top + CGFloat(row) * step), withAttributes: attrs)
        }

        let empty = NSColor.quaternaryLabelColor
        let future = NSColor.quaternaryLabelColor.withAlphaComponent(0.08)
        let done = NSColor.systemGreen
        for i in 0..<dayCount {
            let idx = offset + i
            let r = NSRect(x: left + CGFloat(idx / 7) * step, y: top + CGFloat(idx % 7) * step,
                           width: cell, height: cell)
            guard r.intersects(dirtyRect) else { continue }
            let day = d0 + i
            (days.contains(day) ? done : (day > today ? future : empty)).setFill()
            let path = NSBezierPath(roundedRect: r, xRadius: 2.5, yRadius: 2.5)
            path.fill()
            if day == today {
                NSColor.labelColor.setStroke()
                path.lineWidth = 1.5
                path.stroke()
            }
        }
    }

    private func day(at p: NSPoint) -> Int? {
        let x = p.x - left, y = p.y - top
        guard x >= 0, y >= 0 else { return nil }
        // Ignore clicks in the gaps between cells.
        guard x.truncatingRemainder(dividingBy: step) < cell,
              y.truncatingRemainder(dividingBy: step) < cell else { return nil }
        let row = Int(y / step), col = Int(x / step)
        guard row < 7 else { return nil }
        let i = col * 7 + row - weekday(firstDay)
        return (0..<dayCount).contains(i) ? firstDay + i : nil
    }

    override func mouseDown(with event: NSEvent) {
        guard let d = day(at: convert(event.locationInWindow, from: nil)),
              d <= todayNumber() else { return }
        onToggle?(d)
    }

    override func updateTrackingAreas() {
        super.updateTrackingAreas()
    }
}

