struct AppItem {
    let name: String
    let lower: String
    let url: URL
}

func scanApps() -> [AppItem] {
    let fm = FileManager.default
    let dirs = [
        "/Applications",
        "/System/Applications",
        "/System/Library/CoreServices/Applications",
        NSHomeDirectory() + "/Applications",
    ]
    var seen = Set<String>()
    var items = [AppItem]()
    for dir in dirs {
        guard let en = fm.enumerator(
            at: URL(fileURLWithPath: dir),
            includingPropertiesForKeys: nil,
            options: [.skipsHiddenFiles, .skipsPackageDescendants]) else { continue }
        for case let url as URL in en where url.pathExtension == "app" {
            guard seen.insert(url.path).inserted else { continue }
            let name = url.deletingPathExtension().lastPathComponent
            items.append(AppItem(name: name, lower: name.lowercased(), url: url))
        }
    }
    return items.sorted { $0.lower < $1.lower }
}

/// Lower score = better match. nil = no match.
func score(_ item: AppItem, query: String) -> Int? {
    if item.lower.hasPrefix(query) { return 0 }
    if item.lower.contains(" " + query) { return 1 }
    if item.lower.contains(query) { return 2 }
    var idx = item.lower.startIndex
    for ch in query {
        guard let found = item.lower[idx...].firstIndex(of: ch) else { return nil }
        idx = item.lower.index(after: found)
    }
    return 3
}

