// MARK: - Index

struct AppEntry {
    let name: String
    let lower: String
    let path: String
}

final class Index {
    private(set) var apps: [AppEntry] = []
    private var lastScan = Date.distantPast
    private var scanning = false

    private let roots = [
        "/Applications",
        "/System/Applications",
        "/System/Applications/Utilities",
        "/Applications/Utilities",
        NSHomeDirectory() + "/Applications",
    ]

    /// Rescans in the background; throttled so showing the panel stays cheap.
    func refresh(force: Bool = false, done: (() -> Void)? = nil) {
        if scanning || (!force && Date().timeIntervalSince(lastScan) < 30) { return }
        scanning = true
        DispatchQueue.global(qos: .utility).async { [roots] in
            let fm = FileManager.default
            var seen = Set<String>()
            var out: [AppEntry] = []

            func add(_ dir: String, _ item: String) {
                let path = dir + "/" + item
                let name = String(item.dropLast(4))
                if seen.insert(path).inserted {
                    out.append(AppEntry(name: name, lower: name.lowercased(), path: path))
                }
            }

            for root in roots {
                guard let items = try? fm.contentsOfDirectory(atPath: root) else { continue }
                for item in items {
                    if item.hasSuffix(".app") {
                        add(root, item)
                    } else if !item.hasPrefix("."),
                              let sub = try? fm.contentsOfDirectory(atPath: root + "/" + item) {
                        // One level of vendor folders, e.g. /Applications/Adobe
                        for s in sub where s.hasSuffix(".app") { add(root + "/" + item, s) }
                    }
                }
            }
            out.sort { $0.lower < $1.lower }
            DispatchQueue.main.async {
                self.apps = out
                self.lastScan = Date()
                self.scanning = false
                done?()
            }
        }
    }
}

// MARK: - Usage ranking

enum Usage {
    private static let key = "launchCounts"
    static var counts: [String: Int] = UserDefaults.standard.dictionary(forKey: key) as? [String: Int] ?? [:]
    static func bump(_ path: String) {
        counts[path, default: 0] += 1
        UserDefaults.standard.set(counts, forKey: key)
    }
}

// MARK: - Search

func search(_ query: String, in apps: [AppEntry]) -> [AppEntry] {
    let q = query.lowercased().trimmingCharacters(in: .whitespaces)
    if q.isEmpty {
        return Array(apps.sorted { (Usage.counts[$0.path] ?? 0) > (Usage.counts[$1.path] ?? 0) }
            .prefix(maxResults))
    }
    let qChars = Array(q)
    var scored: [(Int, AppEntry)] = []
    for app in apps {
        var score: Int
        if app.lower.hasPrefix(q) {
            score = 0
        } else if app.lower.contains(" " + q) || app.lower.contains("-" + q) {
            score = 1
        } else if app.lower.contains(q) {
            score = 2
        } else {
            // subsequence match
            var i = 0
            for c in app.lower where i < qChars.count && c == qChars[i] { i += 1 }
            if i < qChars.count { continue }
            score = 3
        }
        score = score * 1000 + app.lower.count - min(Usage.counts[app.path] ?? 0, 50) * 5
        scored.append((score, app))
    }
    scored.sort { $0.0 < $1.0 }
    return scored.prefix(maxResults).map { $0.1 }
}

