// MARK: - Model

final class TimerItem: Codable {
    var id = UUID()
    var name: String
    var duration: TimeInterval?      // nil = stopwatch, otherwise countdown length
    var accumulated: TimeInterval = 0
    var startedAt: Date?

    init(name: String, duration: TimeInterval?) {
        self.name = name
        self.duration = duration
    }

    var isRunning: Bool { startedAt != nil }

    var elapsed: TimeInterval {
        accumulated + (startedAt.map { Date().timeIntervalSince($0) } ?? 0)
    }

    var remaining: TimeInterval? { duration.map { max(0, $0 - elapsed) } }
    var isFinished: Bool { remaining == 0 }

    func start() {
        guard !isRunning, !isFinished else { return }
        startedAt = Date()
    }

    func pause() {
        guard let s = startedAt else { return }
        accumulated += Date().timeIntervalSince(s)
        startedAt = nil
    }

    func reset() {
        accumulated = 0
        startedAt = nil
    }

    /// Stops a countdown that has run out. Returns true if it just finished.
    func checkFinished() -> Bool {
        guard isRunning, isFinished, let d = duration else { return false }
        startedAt = nil
        accumulated = d
        return true
    }

    var display: String {
        if let r = remaining {
            return TimerItem.format(r.rounded(.up), tenths: false)
        }
        return TimerItem.format(elapsed, tenths: true)
    }

    static func format(_ t: TimeInterval, tenths: Bool) -> String {
        let total = Int(t)
        let h = total / 3600, m = (total / 60) % 60, s = total % 60
        var out = h > 0 ? String(format: "%d:%02d:%02d", h, m, s) : String(format: "%02d:%02d", m, s)
        if tenths { out += String(format: ".%d", Int((t - Double(total)) * 10)) }
        return out
    }
}

/// Accepts "90", "5:00" or "1:30:00" (a lone number means minutes).
func parseDuration(_ text: String) -> TimeInterval? {
    let parts = text.trimmingCharacters(in: .whitespaces).split(separator: ":", omittingEmptySubsequences: false)
    guard !parts.isEmpty, parts.count <= 3 else { return nil }
    let nums = parts.map { Int($0.trimmingCharacters(in: .whitespaces)) }
    guard !nums.contains(where: { $0 == nil || $0! < 0 }) else { return nil }
    let v = nums.map { $0! }
    let secs: Int
    switch v.count {
    case 1: secs = v[0] * 60
    case 2: secs = v[0] * 60 + v[1]
    default: secs = v[0] * 3600 + v[1] * 60 + v[2]
    }
    return secs > 0 ? TimeInterval(secs) : nil
}

