#!/usr/bin/env python3
"""Duplicate file finder: compares files by content.

Stdlib only, for fast startup and low memory. Pipeline per candidate set:
  1. group by size (free, from scandir)
  2. group by hash of the first 64 KiB
  3. group by full-content hash (streamed in 1 MiB chunks)
Only files that still collide after each stage are read further.
"""
import hashlib
import os
import queue
import threading
import tkinter as tk
from tkinter import filedialog, messagebox, ttk

HEAD = 64 * 1024
CHUNK = 1024 * 1024


def hash_file(path, limit=None):
    h = hashlib.blake2b(digest_size=16)
    with open(path, "rb", buffering=0) as f:
        if limit:
            h.update(f.read(limit))
        else:
            while chunk := f.read(CHUNK):
                h.update(chunk)
    return h.digest()


def fmt_size(n):
    for unit in ("B", "KB", "MB", "GB"):
        if n < 1024 or unit == "GB":
            return f"{n:.0f} {unit}" if unit == "B" else f"{n:.1f} {unit}"
        n /= 1024


def scan(root, min_size, q, cancel):
    """Runs in a worker thread; reports via q: ('status', str) / ('group', size, [paths]) / ('done', n)."""
    by_size = {}
    seen_inodes = set()
    count = 0
    stack = [root]
    while stack:
        if cancel.is_set():
            return q.put(("done", None))
        try:
            with os.scandir(stack.pop()) as it:
                for e in it:
                    try:
                        if e.is_symlink():
                            continue
                        if e.is_dir(follow_symlinks=False):
                            stack.append(e.path)
                        elif e.is_file(follow_symlinks=False):
                            st = e.stat(follow_symlinks=False)
                            if st.st_size < max(min_size, 1):
                                continue
                            key = (st.st_dev, st.st_ino)
                            if key in seen_inodes:  # hard link to a file already seen
                                continue
                            seen_inodes.add(key)
                            by_size.setdefault(st.st_size, []).append(e.path)
                            count += 1
                            if count % 2000 == 0:
                                q.put(("status", f"Scanning… {count} files"))
                    except OSError:
                        pass
        except OSError:
            pass
    seen_inodes.clear()

    candidates = [(s, p) for s, p in by_size.items() if len(p) > 1]
    del by_size
    found = 0
    for i, (size, paths) in enumerate(candidates):
        if cancel.is_set():
            return q.put(("done", None))
        if i % 50 == 0:
            q.put(("status", f"Comparing… {i}/{len(candidates)} size groups"))
        stage = paths
        for limit in (HEAD if size > HEAD else None, None):
            buckets = {}
            for p in stage:
                try:
                    buckets.setdefault(hash_file(p, limit), []).append(p)
                except OSError:
                    pass
            stage = [p for b in buckets.values() if len(b) > 1 for p in b]
            if limit is None:
                for b in buckets.values():
                    if len(b) > 1:
                        found += 1
                        q.put(("group", size, sorted(b)))
            else:
                # Narrow within each partial-hash bucket separately.
                final = {}
                for b in buckets.values():
                    if len(b) > 1:
                        for p in b:
                            try:
                                final.setdefault((id(b), hash_file(p)), []).append(p)
                            except OSError:
                                pass
                for b in final.values():
                    if len(b) > 1:
                        found += 1
                        q.put(("group", size, sorted(b)))
                break
    q.put(("done", found))


class App(tk.Tk):
    def __init__(self):
        super().__init__()
        self.title("Duplicate Finder")
        self.geometry("820x520")
        self.q = queue.Queue()
        self.cancel = threading.Event()
        self.worker = None
        self.groups = 0
        self.wasted = 0

        top = ttk.Frame(self, padding=8)
        top.pack(fill="x")
        self.folder = tk.StringVar(value=os.path.expanduser("~"))
        ttk.Entry(top, textvariable=self.folder).pack(side="left", fill="x", expand=True)
        ttk.Button(top, text="Browse…", command=self.browse).pack(side="left", padx=4)
        ttk.Label(top, text="Min KB:").pack(side="left")
        self.min_kb = tk.StringVar(value="1")
        ttk.Entry(top, textvariable=self.min_kb, width=6).pack(side="left", padx=4)
        self.go = ttk.Button(top, text="Scan", command=self.start)
        self.go.pack(side="left")

        self.tree = ttk.Treeview(self, columns=("size",), selectmode="extended")
        self.tree.heading("#0", text="File")
        self.tree.heading("size", text="Size")
        self.tree.column("size", width=90, anchor="e", stretch=False)
        sb = ttk.Scrollbar(self, command=self.tree.yview)
        self.tree.configure(yscrollcommand=sb.set)
        sb.pack(side="right", fill="y")
        self.tree.pack(fill="both", expand=True)

        bar = ttk.Frame(self, padding=8)
        bar.pack(fill="x", side="bottom")
        self.status = tk.StringVar(value="Choose a folder and press Scan.")
        ttk.Label(bar, textvariable=self.status).pack(side="left")
        ttk.Button(bar, text="Delete selected", command=self.delete).pack(side="right")
        ttk.Button(bar, text="Show in folder", command=self.reveal).pack(side="right", padx=4)

    def browse(self):
        d = filedialog.askdirectory(initialdir=self.folder.get())
        if d:
            self.folder.set(d)

    def start(self):
        if self.worker and self.worker.is_alive():
            self.cancel.set()
            return
        root = self.folder.ge

#!/usr/bin/env python3
"""Duplicate file finder.

Finds files with identical content (names and dates are ignored) inside a
folder and everything under it. It only REPORTS duplicates. It never deletes,
moves, or changes any file.

Usage:
    python3 find_duplicates.py                 (it will ask for a folder)
    python3 find_duplicates.py /path/to/folder
"""

import hashlib
import os
import sys
from collections import defaultdict

CHUNK = 1024 * 1024  # read files 1 MB at a time


def file_hash(path):
    h = hashlib.sha256()
    with open(path, "rb") as f:
        while True:
            block = f.read(CHUNK)
            if not block:
                break
            h.update(block)
    return h.hexdigest()


def human(n):
    for unit in ("bytes", "KB", "MB", "GB"):
        if n < 1024 or unit == "GB":
            return f"{n:.0f} {unit}" if unit == "bytes" else f"{n:.1f} {unit}"
        n /= 1024


def main():
    if len(sys.argv) > 1:
        folder = sys.argv[1]
    else:
        folder = input("Folder to scan (you can drag it into this window): ")
    folder = os.path.expanduser(folder.strip().strip("'\""))
    if not os.path.isdir(folder):
        print(f"Not a folder: {folder}")
        sys.exit(1)

    print("Scanning...")
    by_size = defaultdict(list)
    count = 0
    for root, _dirs, names in os.walk(folder):
        for name in names:
            path = os.path.join(root, name)
            if os.path.islink(path):
                continue
            try:
                size = os.path.getsize(path)
            except OSError:
                continue
            if size == 0:
                continue
            by_size[size].append(path)
            count += 1
    print(f"Found {count} files. Comparing contents...")

    # Only files with the same size can be identical, so hash just those.
    groups = []
    skipped = []
    for size, paths in by_size.items():
        if len(paths) < 2:
            continue
        by_hash = defaultdict(list)
        for path in paths:
            try:
                by_hash[file_hash(path)].append(path)
            except OSError:
                skipped.append(path)
        for same in by_hash.values():
            if len(same) > 1:
                groups.append((size, sorted(same)))

    groups.sort(key=lambda g: g[0] * (len(g[1]) - 1), reverse=True)

    if not groups:
        print("No duplicates found.")
    else:
        wasted = 0
        for i, (size, paths) in enumerate(groups, 1):
            wasted += size * (len(paths) - 1)
            print(f"\nGroup {i}: {len(paths)} identical files, {human(size)} each")
            for p in paths:
                print(f"   {p}")
        print(f"\n{len(groups)} groups of duplicates.")
        print(f"Space you could free by removing extra copies: {human(wasted)}")
        print("Nothing was deleted or changed.")

    if skipped:
        print(f"\nCould not read {len(skipped)} file(s) (permissions?):")
        for p in skipped:
            print(f"   {p}")


if __name__ == "__main__":
    try:
        main()
    except KeyboardInterrupt:
        print("\nStopped.")

#!/usr/bin/env python3
"""Batch File Renamer: a tkinter desktop app with a live preview of new names.

Run:  python3 renamer.py
No third-party dependencies (needs Python 3.8+ with tkinter).
"""
import os
import re
import tkinter as tk
from dataclasses import dataclass
from tkinter import filedialog, messagebox, ttk

INVALID_CHARS = set('/\0')


# ---------------------------------------------------------------- logic

@dataclass
class Rules:
    find: str = ""
    replace: str = ""
    use_regex: bool = False
    ignore_case: bool = False
    case: str = "Unchanged"        # Unchanged / lowercase / UPPERCASE / Title Case
    prefix: str = ""
    suffix: str = ""
    number_mode: str = "None"      # None / Append / Prepend / Replace name
    number_start: int = 1
    number_step: int = 1
    number_pad: int = 2
    number_sep: str = "_"
    ext_mode: str = "Unchanged"    # Unchanged / lowercase / Custom
    ext_custom: str = ""


def apply_case(text, mode):
    if mode == "lowercase":
        return text.lower()
    if mode == "UPPERCASE":
        return text.upper()
    if mode == "Title Case":
        return re.sub(r"[A-Za-z0-9']+", lambda m: m.group(0).capitalize(), text)
    return text


def new_name(filename, index, rules):
    """Return the new file name for `filename` (the index-th item). Raises re.error on bad regex."""
    stem, ext = os.path.splitext(filename)
    if filename.startswith(".") and not ext:   # dotfile like ".bashrc": no extension
        stem, ext = filename, ""

    if rules.find:
        pattern = rules.find if rules.use_regex else re.escape(rules.find)
        repl = rules.replace if rules.use_regex else rules.replace.replace("\\", "\\\\")
        stem = re.sub(pattern, repl, stem, flags=re.I if rules.ignore_case else 0)

    stem = apply_case(stem, rules.case)
    stem = rules.prefix + stem + rules.suffix

    if rules.number_mode != "None":
        n = str(rules.number_start + index * rules.number_step).zfill(rules.number_pad)
        if rules.number_mode == "Append":
            stem = stem + rules.number_sep + n
        elif rules.number_mode == "Prepend":
            stem = n + rules.number_sep + stem
        else:
            stem = n

    if rules.ext_mode == "lowercase":
        ext = ext.lower()
    elif rules.ext_mode == "Custom":
        c = rules.ext_custom.strip().lstrip(".")
        ext = "." + c if c else ""
    return stem + ext


def build_plan(paths, rules):
    """Return a list of (path, new_name, status). status is '' when OK, 'same' when unchanged,
    otherwise an error message."""
    plan = []
    for i, p in enumerate(paths):
        try:
            plan.append([p, new_name(os.path.basename(p), i, rules), ""])
        except re.error as e:
            plan.append([p, os.path.basename(p), f"Bad regex: {e}"])

    old_keys = {os.path.normcase(os.path.abspath(p)).lower() for p in paths}
    seen = {}
    for item in plan:
        p, name, status = item
        if status:
            continue
        if name == os.path.basename(p):
            item[2] = "same"
            continue
        if not name.strip(" .") or any(c in INVALID_CHARS for c in name):
            item[2] = "Invalid name"
            continue
        target = os.path.join(os.path.dirname(p), name)
        key = os.path.abspath(target).lower()
        seen.setdefault(key, []).append(item)
        if os.path.lexists(target) and key not in old_keys:
            item[2] = "Already exists"
    for items in seen.values():
        if len(items) > 1:
            for item in items:
                if not item[2]:
                    item[2] = "Duplicate name"
    return [tuple(x) for x in plan]


def apply_plan(plan):
    """Rename in two phases (via temp names) so swaps/chains work. Returns list of (src, dst) done."""
    jobs = [(p, os.path.join(os.path.dirname(p), n)) for p, n, s in plan if s == ""]
    temps = []
    try:
        for k, (src, dst) in enumerate(jobs):
            tmp = os.path.join(os.path.dirname(src), f".renamer_tmp_{os.getpid()}_{k}")
            os.rename(src, tmp)
            temps.append((tmp, src, dst))
    except OSError:
        for tmp, src, _ in reversed(temps):
            os.rename(tmp, src)
        raise
    done = []
    try:
        for tmp, src, dst in temps:
            os.rename(tmp, dst)
            done.append((src, dst))
    except OSError:
        # roll back everything
        finished = {s for s, _ in done}
        for tmp, src, dst in temps:
            if src in finished:
                os.rename(dst, src)
            else:
                os.rename(tmp, src)
        raise
    return done


# ------------------------------------------------------------------ UI

class App(ttk.Frame):
    def __init__(self, root):
        super().__init__(root, padding=8)
        self.root = root
        self.paths = []
        self.plan = []
        self.last_undo = []
        self.vars = {}
        self.pack(fill="both", expand=True)
        self._build()
