                          ("Remove selected", self.remove_selected), ("Clear", self.clear)]:
            ttk.Button(bar, text=text, command=cmd).pack(side="left", padx=(0, 4))

        rules = ttk.LabelFrame(self, text="Rules (applied top to bottom)", padding=6)
        rules.pack(fill="x", pady=6)
        rules.columnconfigure((1, 3, 5), weight=1)

        def label(r, c, t):
