"""Rename logic, independent of any UI."""
import os
import re
import uuid
from dataclasses import dataclass

INVALID_CHARS = re.compile(r'[<>:"/\\|?*\x00-\x1f]')
WINDOWS_RESERVED = {
    "CON", "PRN", "AUX", "NUL",
    *(f"COM{i}" for i in range(1, 10)),
    *(f"LPT{i}" for i in range(1, 10)),
}

OK, UNCHANGED, INVALID, CONFLICT = "ok", "unchanged", "invalid", "conflict"


@dataclass
class Options:
    find: str = ""
    replace: str = ""
    use_regex: bool = False
    case_sensitive: bool = True
    case_mode: str = "keep"  # keep | lower | upper | title
    prefix: str = ""
    suffix: str = ""
    numbering: bool = False
    start: int = 1
    step: int = 1
    padding: int = 2
    number_position: str = "suffix"  # prefix | suffix
    separator: str = "_"
    lower_extension: bool = False


@dataclass
class Item:
    src: str
    new_name: str
    status: str
    message: str = ""

    @property
    def dst(self):
        return os.path.join(os.path.dirname(self.src), self.new_name)


def compile_pattern(opts: Options):
    """Return a compiled regex or None if there is nothing to find. May raise re.error."""
    if not opts.find:
        return None
    pattern = opts.find if opts.use_regex else re.escape(opts.find)
    return re.compile(pattern, 0 if opts.case_sensitive else re.IGNORECASE)


def new_name_for(name: str, index: int, opts: Options, pattern=None) -> str:
    stem, ext = os.path.splitext(name)
    if pattern is not None:
        repl = opts.replace if opts.use_regex else opts.replace.replace("\\", "\\\\")
        stem = pattern.sub(repl, stem)
    if opts.case_mode == "lower":
        stem = stem.lower()
    elif opts.case_mode == "upper":
        stem = stem.upper()
    elif opts.case_mode == "title":
        stem = stem.title()
    stem = f"{opts.prefix}{stem}{opts.suffix}"
    if opts.numbering:
        num = str(opts.start + index * opts.step).zfill(opts.padding)
        if opts.number_position == "prefix":
            stem = f"{num}{opts.separator}{stem}"
        else:
            stem = f"{stem}{opts.separator}{num}"
    if opts.lower_extension:
        ext = ext.lower()
    return stem + ext


def _validate(name: str):
    if not name or name in (".", ".."):
        return "Empty name"
    if INVALID_CHARS.search(name):
        return "Invalid character"
    if name.endswith((" ", ".")):
        return "Ends with space or dot"
    if os.path.splitext(name)[0].upper() in WINDOWS_RESERVED:
        return "Reserved name"
    if len(name.encode("utf-8")) > 255:
        return "Name too long"
    return ""


def build_plan(paths, opts: Options):
    """Compute the rename plan. Raises re.error for a bad regex."""
    pattern = compile_pattern(opts)
    items = []
    for i, src in enumerate(paths):
        old = os.path.basename(src)
        try:
            new = new_name_for(old, i, opts, pattern)
        except (re.error, IndexError) as e:  # bad group reference in replacement
            raise re.error(str(e))
        if new == old:
            items.append(Item(src, new, UNCHANGED))
            continue
        err = _validate(new)
        items.append(Item(src, new, INVALID if err else OK, err))

    # Conflicts: same target twice, or target already exists and isn't being moved away.
    sources = {os.path.normcase(os.path.abspath(it.src)) for it in items}
    seen = {}
    for it in items:
        if it.status != OK:
            continue
        key = os.path.normcase(os.path.abspath(it.dst))
        seen.setdefault(key, []).append(it)
    for key, group in seen.items():
        if len(group) > 1:
            for it in group:
                it.status, it.message = CONFLICT, "Duplicate target name"
        elif key not in sources and os.path.lexists(group[0].dst):
            group[0].status, group[0].message = CONFLICT, "File already exists"
    # Case-only renames on case-insensitive filesystems are handled by the two-phase apply.
    return items


def apply_plan(items):
    """Rename all OK items in two phases (so swaps/cycles work).

    Returns list of (old_path, new_path) for undo. On failure rolls back and raises OSError.
    """
    todo = [it for it in items if it.status == OK]
    if any(it.status in (INVALID, CONFLICT) for it in items):
        raise ValueError("Resolve invalid or conflicting names first")
    token = uuid.uuid4().hex[:8]
    staged = []  # (original, temp, final)
    done = []
    try:
        for n, it in enumerate(todo):
            tmp = os.path.join(os.path.dirname(it.src), f".rename-{token}-{n}.tmp")
            os.rename(it.src, tmp)
            staged.append((it.src, tmp, it.dst))
        for orig, tmp, final in staged:
            os.rename(tmp, final)
            done.append((orig, final))
            staged_done = (orig, tmp, final)
            staged_done  # noqa
    except OSError:
        finished = {o for o, _ in done}
        for orig, final in reversed(done):
            try:
                os.rename(final, orig)
            except OSError:
                pass
        for orig, tmp, _ in staged:
            if orig not in finished and os.path.lexists(tmp):
                try:
                    os.rename(tmp, orig)
                except OSError:
                    pass
        raise
    return done


def undo(done):
    """Reverse a previous apply_plan result."""
    items = [Item(new, os.path.basename(old), OK) for old, new in done]
    # Same directory per pair, so the basename is enough to build the destination.
    return apply_plan(items)

