#!/usr/bin/env python3
"""Disk usage analyzer: scans a folder and opens a treemap in your web browser.

Usage:
    python3 disk_treemap.py              # scans your home folder
    python3 disk_treemap.py /some/folder # scans that folder

Only uses Python's standard library. Nothing is uploaded; the result is a
local HTML file.
"""
import json
import os
import sys
import tempfile
import webbrowser

sys.setrecursionlimit(10000)

MIN_FRACTION = 0.002  # items smaller than 0.2% of the total are grouped together


def scan(path):
    """Return a dict tree: {name, size, children?}. Size is real disk usage."""
    name = os.path.basename(path) or path
    try:
        st = os.lstat(path)
    except OSError:
        return {"name": name, "size": 0}
    size = getattr(st, "st_blocks", 0) * 512 or st.st_size
    node = {"name": name, "size": size}
    if os.path.islink(path) or not os.path.isdir(path):
        return node
    children = []
    try:
        with os.scandir(path) as it:
            for entry in it:
                children.append(scan(entry.path))
    except OSError:
        pass  # no permission, skip
    node["children"] = children
    node["size"] = size + sum(c["size"] for c in children)
    return node


def prune(node, cutoff):
    """Group tiny children into one '(small items)' entry to keep the page fast."""
    kids = node.get("children")
    if not kids:
        node.pop("children", None)
        return
    big = [k for k in kids if k["size"] >= cutoff]
    small = [k for k in kids if k["size"] < cutoff]
    small_total = sum(k["size"] for k in small)
    own = node["size"] - sum(k["size"] for k in kids)  # the folder entry itself
    small_total += max(own, 0)
    for k in big:
        prune(k, cutoff)
    if small_total > 0:
        big.append({"name": "(small items: %d)" % len(small), "size": small_total, "small": True})
    node["children"] = big


