def validate(src: Path, dst: Path) -> None:
    if not src.is_dir():
        raise SyncError(f"Source is not a directory: {src}")
    s, d = src.resolve(), dst.resolve()
    if s == d:
        raise SyncError("Source and destination are the same folder.")
    if s in d.parents:
        raise SyncError("Destination is inside the source folder.")
    if d in s.parents:
        raise SyncError("Source is inside the destination folder; mirroring would delete it.")
    if d == Path(d.anchor):
        raise SyncError("Refusing to use a filesystem root as destination.")


def _file_hash(p: Path) -> str:
    h = hashlib.sha256()
    with open(p, "rb") as f:
        for chunk in iter(lambda: f.read(1 << 20), b""):
            h.update(chunk)
    return h.hexdigest()


def _differs(s: Path, d: Path, use_hash: bool) -> bool:
    ss, ds = s.stat(), d.stat()
    if ss.st_size != ds.st_size:
        return True
    if use_hash:
        return _file_hash(s) != _file_hash(d)
    return abs(ss.st_mtime - ds.st_mtime) > MTIME_TOLERANCE


def _is_link(p: Path) -> bool:
    return p.is_symlink()


