         excludes: Optional[List[str]] = None) -> List[Action]:
    """Compute the actions needed to make dst mirror src."""
    import fnmatch
    validate(src, dst)
    excludes = excludes or []

    def excluded(name: str) -> bool:
        return any(fnmatch.fnmatch(name, pat) for pat in excludes)

    actions: List[Action] = []

    def walk(rel: Path) -> None:
        s_dir, d_dir = src / rel, dst / rel
        s_entries = {e.name: e for e in os.scandir(s_dir) if not excluded(e.name)}
        d_entries = {}
        if d_dir.is_dir() and not d_dir.is_symlink():
            d_entries = {e.name: e for e in os.scandir(d_dir)}

        for name in sorted(s_entries):
            e = s_entries[name]
            r = rel / name
