                if name in d_entries and not d_entries[name].is_dir(follow_symlinks=False):
                    actions.append(Action("delete_file", str(r)))
                    d_entries.pop(name)
                if name not in d_entries:
                    actions.append(Action("mkdir", str(r)))
                walk(r)
            else:
                if name in d_entries:
                    de = d_entries[name]
                    if de.is_dir(follow_symlinks=False):
                        actions.append(Action("delete_dir", str(r)))
                        actions.append(Action("copy", str(r)))
                    elif e.is_symlink() or de.is_symlink() or _differs(Path(e.path), d, use_hash):
                        actions.append(Action("update", str(r)))
