"""Sync engine: plans and executes a one-way mirror of a source dir onto a destination dir."""
import fnmatch
import os
import shutil
import threading
from dataclasses import dataclass, field
from typing import Callable, Optional

MTIME_TOLERANCE = 2.0  # seconds; FAT and some network filesystems round mtimes


class SyncError(Exception):
    pass


@dataclass
class Action:
    kind: str  # "mkdir", "copy", "update", "delete_file", "delete_dir"
    rel: str
    size: int = 0

    def __str__(self):
        return f"{self.kind:<11} {self.rel}"


@dataclass
class Plan:
    actions: list = field(default_factory=list)

    def count(self, kind):
        return sum(1 for a in self.actions if a.kind == kind)

    @property
    def bytes_to_copy(self):
        return sum(a.size for a in self.actions if a.kind in ("copy", "update"))

    def summary(self):
        return (
            f"{self.count('copy')} new, {self.count('update')} updated, "
            f"{self.count('delete_file') + self.count('delete_dir')} deleted, "
            f"{self.count('mkdir')} folders created"
        )


def validate(src, dst):
    src, dst = os.path.realpath(src), os.path.realpath(dst)
    if not os.path.isdir(src):
        raise SyncError("Source folder does not exist.")
    if src == dst:
        raise SyncError("Source and destination are the same folder.")
    if dst.startswith(src + os.sep):
        raise SyncError("Destination is inside the source folder.")
    if src.startswith(dst + os.sep):
        raise SyncError("Source is inside the destination folder; mirroring would delete it.")
    if dst == os.path.dirname(dst):
        raise SyncError("Refusing to use a filesystem root as destination.")
    return src, dst


def _excluded(rel, patterns):
    name = os.path.basename(rel)
    return any(fnmatch.fnmatch(name, p) or fnmatch.fnmatch(rel, p) for p in patterns)


def _walk(root, patterns):
    """Return {rel: (is_dir, size, mtime)} for everything under root, skipping excluded paths."""
    out = {}
    for dirpath, dirnames, filenames in os.walk(root):
        rel_dir = os.path.relpath(dirpath, root)
        rel_dir = "" if rel_dir == "." else rel_dir
        keep = []
        for d in dirnames:
            rel = os.path.join(rel_dir, d)
            if _excluded(rel, patterns):
                continue
            full = os.path.join(dirpath, d)
            if os.path.islink(full):  # treat symlinks to dirs as files so we never recurse through them
                filenames.append(d)
                continue
            keep.append(d)
            out[rel] = (True, 0, 0.0)
        dirnames[:] = keep
        for f in filenames:
            rel = os.path.join(rel_dir, f)
            if _excluded(rel, patterns):
                continue
            try:
                st = os.lstat(os.path.join(dirpath, f))
            except OSError:
                continue
            out[rel] = (False, st.st_size, st.st_mtime)
    return out


def build_plan(src, dst, delete_extra=True, exclude=()):
    src, dst = validate(src, dst)
    exclude = [p for p in exclude if p]
    s = _walk(src, exclude)
    d = _walk(dst, []) if os.path.isdir(dst) else {}
    plan = Plan()

    for rel in sorted(s):
        is_dir, size, mtime = s[rel]
        cur = d.get(rel)
        if is_dir:
            if cur is None:
                plan.actions.append(Action("mkdir", rel))
            elif not cur[0]:  # file where a dir should be
                plan.actions.append(Action("delete_file", rel))
                plan.actions.append(Action("mkdir", rel))
            continue
        if cur is None:
            plan.actions.append(Action("copy", rel, size))
        elif cur[0]:  # dir where a file should be
            plan.actions.append(Action("delete_dir", rel))
            plan.actions.append(Action("copy", rel, size))
        elif cur[1] != size or abs(cur[2] - mtime) > MTIME_TOLERANCE:
            plan.actions.append(Action("update", rel, size))

    if delete_extra:
        extras = [r for r in d if r not in s and not _excluded(r, exclude)]
        # Deepest first so children go before parents.
        for rel in sorted(extras, key=lambda r: r.count(os.sep), reverse=True):
            plan.actions.append(Action("delete_dir" if d[rel][0] else "delete_file", rel))
    return plan


def execute(src, dst, plan, progress: Optional[Callable] = None, cancel: Optional[threading.Event] = None):
    """Apply a plan. Returns (done, errors) where errors is a list of (Action, message)."""
    src, dst = validate(src, dst)
    os.makedirs(dst, exist_ok=True)
    errors, done = [], 0
    total = len(plan.actions)
    # Directory creation/type-conflict deletes first, then copies, then deletions.
    order = {"delete_file": 0, "delete_dir": 0, "mkdir": 1, "copy": 2, "update": 2}
    ordered = sorted(plan.actions, key=lambda a: order[a.kind]) if False else plan.actions
    for i, a in enumerate(ordered):
        if cancel is not None and cancel.is_set():
            break
        s_path, d_path = os.path.join(src, a.rel), os.path.join(dst, a.rel)
        try:
            if a.kind == "mkdir":
                os.makedirs(d_path, exist_ok=True)
            elif a.kind in ("copy", "update"):
                if os.path.islink(s_path):
                    if os.path.lexists(d_path):
                        os.remove(d_path)
                    os.symlink(os.readlink(s_path), d_path)
                else:
                    tmp = d_path + ".foldersync-tmp"
                    shutil.copy2(s_path, tmp)
                    os.replace(tmp, d_path)
            elif a.kind == "delete_file":
                os.remove(d_path)
            elif a.kind == "delete_dir":
                if os.path.islink(d_path):
                    os.remove(d_path)
                else:
                    shutil.rmtree(d_path)
            done += 1
        except OSError as e:
            errors.append((a, str(e)))
        if progress:
            progress(i + 1, total, a, err

