"""Backup engine and config storage. Standard library only.

Destination layout, per source folder:

    <dest>/<source name>/current/             mirror of the source
    <dest>/<source name>/versions/<stamp>/    files replaced or deleted since the previous run

Only new or changed files are copied (size + mtime comparison). Replaced and
deleted files are moved into a timestamped versions folder instead of being
destroyed. No hard links or symlinks are used, so this works on FAT/exFAT/NTFS
external drives.
"""
import fnmatch
import json
import os
import shutil
import sys
import threading
import time
from dataclasses import dataclass, field, asdict
from datetime import datetime
from pathlib import Path
from typing import Callable, Optional

MTIME_TOLERANCE = 2.0  # FAT stores mtimes with 2 second granularity
UNIT_SECONDS = {"minutes": 60, "hours": 3600, "days": 86400}


# ---------- config ----------

def config_dir() -> Path:
    if sys.platform == "win32":
        base = Path(os.environ.get("APPDATA", Path.home() / "AppData" / "Roaming"))
    elif sys.platform == "darwin":
        base = Path.home() / "Library" / "Application Support"
    else:
        base = Path(os.environ.get("XDG_CONFIG_HOME", Path.home() / ".config"))
    return base / "IncrementalBackup"


@dataclass
class Config:
    sources: list = field(default_factory=list)
    destination: str = ""
    exclude: list = field(default_factory=lambda: [".DS_Store", "Thumbs.db", "*.tmp", "node_modules", ".cache"])
    interval_value: int = 1
    interval_unit: str = "hours"
    keep_versions: int = 10
    schedule_enabled: bool = False
    last_run: float = 0.0

    @property
    def interval_seconds(self) -> int:
        return max(1, self.interval_value) * UNIT_SECONDS.get(self.interval_unit, 3600)

    def is_due(self, now: Optional[float] = None) -> bool:
        now = time.time() if now is None else now
        return self.schedule_enabled and now - self.last_run >= self.interval_seconds

    @classmethod
    def load(cls, path: Optional[Path] = None) -> "Config":
        path = path or config_dir() / "config.json"
        try:
            data = json.loads(path.read_text(encoding="utf-8"))
        except (OSError, ValueError):
            return cls()
        known = {k: v for k, v in data.items() if k in cls.__dataclass_fields__}
        return cls(**known)

    def save(self, path: Optional[Path] = None) -> None:
        path = path or config_dir() / "config.json"
        path.parent.mkdir(parents=True, exist_ok=True)
        tmp = path.with_suffix(".tmp")
        tmp.write_text(json.dumps(asdict(self), indent=2), encoding="utf-8")
        os.replace(tmp, path)


# ---------- engine ----------

@dataclass
class Stats:
    copied: int = 0
    skipped: int = 0
    archived: int = 0   # replaced/deleted files moved to versions
    bytes_copied: int = 0
    errors: list = field(default_factory=list)
    cancelled: bool = False

    def summary(self) -> str:
        s = (f"{self.copied} copied ({self.bytes_copied / 1e6:.1f} MB), "
             f"{self.skipped} unchanged, {self.archived} archived, {len(self.errors)} errors")
        return s + (" - cancelled" if self.cancelled else "")


class BackupError(Exception):
    pass


def _excluded(name: str, patterns) -> bool:
    return any(fnmatch.fnmatch(name, p) for p in patterns)


def _unchanged(src: os.stat_result, dst: os.stat_result) -> bool:
    return src.st_size == dst.st_size and abs(src.st_mtime - dst.st_mtime) <= MTIME_TOLERANCE


def _is_inside(child: Path, parent: Path) -> bool:
    try:
        child.resolve().relative_to(parent.resolve())
        return True
    except ValueError:
        return False


def _archive(path: Path, rel: Path, version_dir: Path) -> None:
    target = version_dir / rel
    target.parent.mkdir(parents=True, exist_ok=True)
    shutil.move(str(path), str(target))


