#!/usr/bin/env python3
"""Archive Manager: open, browse, extract and create zip and tar archives.

Uses only the Python standard library (tkinter, zipfile, tarfile).
Run with: python3 archive_manager.py [archive]
"""
import os
import shutil
import sys
import tarfile
import tempfile
import time
import tkinter as tk
import zipfile
from dataclasses import dataclass
from tkinter import filedialog, messagebox, ttk

TAR_SUFFIXES = {
    ".tar": "w",
    ".tar.gz": "w:gz",
    ".tgz": "w:gz",
    ".tar.bz2": "w:bz2",
    ".tbz2": "w:bz2",
    ".tar.xz": "w:xz",
    ".txz": "w:xz",
}


@dataclass
class Entry:
    name: str
    size: int
    mtime: float
    is_dir: bool


def kind_of(path):
    """Return ('zip', None) or ('tar', write_mode) based on file extension."""
    lower = path.lower()
    if lower.endswith(".zip"):
        return "zip", None
    for suffix, mode in TAR_SUFFIXES.items():
        if lower.endswith(suffix):
            return "tar", mode
    return None, None


def human_size(n):
    for unit in ("B", "KB", "MB", "GB"):
        if n < 1024 or unit == "GB":
            return f"{n} B" if unit == "B" else f"{n:.1f} {unit}"
        n /= 1024


def is_within(base, target):
    base = os.path.realpath(base)
    target = os.path.realpath(target)
    return target == base or target.startswith(base + os.sep)


def selected(name, wanted):
    """True if name is in wanted or lives under a wanted directory."""
    if wanted is None:
        return True
    n = name.rstrip("/")
    return any(n == w.rstrip("/") or n.startswith(w.rstrip("/") + "/") for w in wanted)


class Archive:
    def __init__(self, path):
        self.path = path
        self.kind, self.write_mode = kind_of(path)
        if self.kind is None:
            if zipfile.is_zipfile(path):
                self.kind = "zip"
            elif tarfile.is_tarfile(path):
                self.kind = "tar"
            else:
                raise ValueError("Unsupported or corrupt archive.")

    def entries(self):
        out = []
        if self.kind == "zip":
            with zipfile.ZipFile(self.path) as zf:
                for i in zf.infolist():
                    mt = time.mktime(i.date_time + (0, 0, -1))
                    out.append(Entry(i.filename, i.file_size, mt, i.is_dir()))
        else:
            with tarfile.open(self.path, "r:*") as tf:
                for m in tf.getmembers():
                    out.append(Entry(m.name, m.size, m.mtime, m.isdir()))
        return out

    def extract(self, dest, wanted=None):
        """Extract (optionally only `wanted` names) into dest. Returns count."""
        count = 0
        if self.kind == "zip":
            with zipfile.ZipFile(self.path) as zf:
                for info in zf.infolist():
                    if not selected(info.filename, wanted):
                        continue
                    if not is_within(dest, os.path.join(dest, info.filename)):
                        raise ValueError(f"Unsafe path in archive: {info.filename}")
                    zf.extract(info, dest)
                    count += 1
        else:
            with tarfile.open(self.path, "r:*") as tf:
                for m in tf.getmembers():
                    if not selected(m.name, wanted):
                        continue
                    if not is_within(dest, os.path.join(dest, m.name)):
                        raise ValueError(f"Unsafe path in archive: {m.name}")
                    if hasattr(tarfile, "data_filter"):
                        tf.extract(m, dest, filter="data")
                    elif m.isfile() or m.isdir():
                        tf.extract(m, dest)
                    else:
                        continue  # skip links/devices on old Pythons
                    count += 1
