    def create_empty(self):
        if self.kind == "zip":
            with zipfile.ZipFile(self.path, "w"):
                pass
        else:
            with tarfile.open(self.path, self.write_mode):
                pass

    def add(self, paths):
        """Add files/folders (top-level names kept). Returns count added."""
        items = []
        for p in paths:
            p = os.path.abspath(p)
            base = os.path.dirname(p)
            if os.path.isdir(p):
                items.append((p, os.path.relpath(p, base)))
                for root, dirs, files in os.walk(p):
                    for n in dirs + files:
                        full = os.path.join(root, n)
                        items.append((full, os.path.relpath(full, base)))
            else:
                items.append((p, os.path.relpath(p, base)))

        if self.kind == "zip":
            with zipfile.ZipFile(self.path, "a", zipfile.ZIP_DEFLATED) as zf:
                for full, arc in items:
                    zf.write(full, arc)
            return len(items)

        # tar: rewrite the archive with the new members appended
        mode = self.write_mode or "w"
        fd, tmp = tempfile.mkstemp(dir=os.path.dirname(self.path) or ".")
        os.close(fd)
        try:
            with tarfile.open(self.path, "r:*") as old, tarfile.open(tmp, mode) as new:
                for m in old.getmembers():
                    new.addfile(m, old.extractfile(m) if m.isfile() else None)
                for full, arc in items:
                    new.add(full, arc, recursive=False)
            shutil.move(tmp, self.path)
        finally:
            if os.path.exists(tmp):
                os.remove(tmp)
        return len(items)


