"""Incremental snapshot engine.

Each run creates a new dated folder under <dest>/BackupTool/. Files unchanged
since the previous snapshot (same size and mtime) are hard-linked to it, so
they cost no extra space; new or changed files are copied. If the drive's
filesystem can't hard-link (e.g. exFAT/FAT32), files are copied in full.
"""
import fnmatch
import os
import re
import shutil
import threading
from dataclasses import dataclass, field
from datetime import datetime

ROOT_NAME = "BackupTool"
SNAP_RE = re.compile(r"^\d{4}-\d{2}-\d{2}_\d{6}$")
MTIME_TOLERANCE = 2.0  # seconds; FAT-family filesystems store 2s resolution


class BackupError(Exception):
    pass


class Cancelled(Exception):
    pass


@dataclass
class BackupResult:
    snapshot: str = ""
    copied: int = 0
    linked: int = 0
    bytes_copied: int = 0
    errors: list = field(default_factory=list)
    hardlinks_supported: bool = True


def backup_root(dest):
    return os.path.join(dest, ROOT_NAME)


def list_snapshots(dest):
    """Completed snapshot names, oldest first."""
    root = backup_root(dest)
    if not os.path.isdir(root):
        return []
    return sorted(n for n in os.listdir(root)
                  if SNAP_RE.match(n) and os.path.isdir(os.path.join(root, n)))


def _is_excluded(rel_path, name, patterns):
    return any(fnmatch.fnmatch(name, p) or fnmatch.fnmatch(rel_path, p)
               for p in patterns)


def _unique_names(sources):
    """Map each source to a distinct folder name inside the snapshot."""
    used, names = set(), {}
    for src in sources:
        base = os.path.basename(os.path.normpath(src)) or "root"
        name, i = base, 2
        while name in used:
            name, i = f"{base}-{i}", i + 1
        used.add(name)
        names[src] = name
    return names


def _unchanged(prev_path, st):
    try:
        pst = os.lstat(prev_path)
    except OSError:
        return False
    return (os.path.isfile(prev_path) and not os.path.islink(prev_path)
            and pst.st_size == st.st_size
            and abs(pst.st_mtime - st.st_mtime) <= MTIME_TOLERANCE)


def run_backup(sources, dest, excludes=(), keep=10, progress=None, cancel=None):
    """Create one snapshot. Returns a BackupResult; raises BackupError/Cancelled."""
    cancel = cancel or threading.Event()
    progress = progress or (lambda msg: None)

    if not sources:
        raise BackupError("No source folders selected.")
    if not dest or not os.path.isdir(dest):
        raise BackupError(f"Destination not available: {dest or '(none)'}")
    dest_real = os.path.realpath(dest)
    for src in sources:
        if not os.path.isdir(src):
            raise BackupError(f"Source folder missing: {src}")
        src_real = os.path.realpath(src)
        if dest_real == src_real or dest_real.startswith(src_real + os.sep):
            raise BackupError(f"Destination is inside source folder: {src}")

    root = backup_root(dest)
    os.makedirs(root, exist_ok=True)
    for n in os.listdir(root):  # leftovers from an interrupted run
        if n.startswith(".inprogress-"):
            shutil.rmtree(os.path.join(root, n), ignore_errors=True)

    previous = list_snapshots(dest)
    prev_dir = os.path.join(root, previous[-1]) if previous else None

    snap_name = datetime.now().strftime("%Y-%m-%d_%H%M%S")
    tmp_dir = os.path.join(root, ".inprogress-" + snap_name)
    os.makedirs(tmp_dir)
    result = BackupResult(snapshot=snap_name)
    names = _unique_names(sources)

    try:
        for src in sources:
            _backup_source(src, names[src], tmp_dir, prev_dir, excludes,
                           result, progress, cancel)
        final = os.path.join(root, snap_name)
        os.rename(tmp_dir, final)
    except BaseException:
        shutil.rmtree(tmp_dir, ignore_errors=True)
        raise

    _apply_retention(dest, keep, progress)
    return result


def _backup_source(src, name, tmp_dir, prev_dir, excludes, result, progress, cancel):
    out_base = os.path.join(tmp_dir, name)
    prev_base = os.path.join(prev_dir, name) if prev_dir else None
    os.makedirs(out_base, exist_ok=True)
    progress(f"Scanning {src}")

    for cur, dirs, files in os.walk(src, followlinks=False):
        if cancel.is_set():
            raise Cancelled()
