        rel_dir = "" if rel_dir == "." else rel_dir
        dirs[:] = [d for d in dirs
                   if not _is_excluded(os.path.join(rel_dir, d), d, excludes)]
        out_dir = os.path.join(out_base, rel_dir)
        os.makedirs(out_dir, exist_ok=True)
        try:
            shutil.copystat(cur, out_dir)
        except OSError:
            pass

