                             result)
            except OSError as e:
                result.errors.append(f"{s_path}: {e}")
            total = result.copied + result.linked
            if total % 200 == 0:
                progress(f"{total} files processed")


def _backup_file(s_path, d_path, prev_path, result):
    if os.path.islink(s_path):
        os.symlink(os.readlink(s_path), d_path)
        return
    st = os.stat(s_path)
    if prev_path and result.hardlinks_supported and _unchanged(prev_path, st):
        try:
            os.link(prev_path, d_path)
            result.linked += 1
            return
        except OSError:
            result.hardlinks_supported = False
    elif prev_path and not result.hardlinks_supported:
        pass
    shutil.copy2(s_path, d_path)
    result.copied += 1
    result.bytes_copied += st.st_size


