"""Pure scheduling logic (no GUI, easy to test)."""
from datetime import datetime, timedelta


def is_due(schedule, last_run, now=None):
    """schedule: {"mode": "interval", "minutes": N} or {"mode": "daily", "time": "HH:MM"}.

    last_run is a datetime or None. A missed run is due as soon as we check.
    """
    now = now or datetime.now()
    if last_run is None:
        return True
    if schedule.get("mode") == "daily":
        hh, mm = _parse_time(schedule.get("time", "02:00"))
        slot = now.replace(hour=hh, minute=mm, second=0, microsecond=0)
        if slot > now:
            slot -= timedelta(days=1)
        return last_run < slot
    minutes = max(1, int(schedule.get("minutes", 60)))
    return now - last_run >= timedelta(minutes=minutes)


def _parse_time(text):
    try:
        hh, mm = text.split(":")
        hh, mm = int(hh), int(mm)
        if 0 <= hh < 24 and 0 <= mm < 60:
            return hh, mm
    except ValueError:
        pass
    return 2, 0

import json
