"""Archive Manager: open, browse, extract and create zip and tar archives.

Pure standard library (Python 3.8+ with Tkinter), so it runs unchanged on
Windows, macOS and Linux.
"""
import os
import sys
import tarfile
import threading
import time
import tkinter as tk
import zipfile
from dataclasses import dataclass
from tkinter import filedialog, messagebox, ttk

APP_NAME = "Archive Manager"

# extension -> (kind, tar write mode)
FORMATS = {
    ".zip": ("zip", None),
    ".tar": ("tar", "w"),
    ".tar.gz": ("tar", "w:gz"),
    ".tgz": ("tar", "w:gz"),
    ".tar.bz2": ("tar", "w:bz2"),
    ".tbz2": ("tar", "w:bz2"),
    ".tar.xz": ("tar", "w:xz"),
    ".txz": ("tar", "w:xz"),
}
SAVE_TYPES = [
    ("Zip archive", "*.zip"),
    ("Tar archive", "*.tar"),
    ("Tar + gzip", "*.tar.gz"),
    ("Tar + bzip2", "*.tar.bz2"),
    ("Tar + xz", "*.tar.xz"),
]
OPEN_TYPES = [
    ("Archives", "*.zip *.tar *.tar.gz *.tgz *.tar.bz2 *.tbz2 *.tar.xz *.txz"),
    ("All files", "*.*"),
]


@dataclass
class Entry:
    name: str
    size: int
    mtime: float
    is_dir: bool


def format_for(path):
    lower = path.lower()
    for ext in sorted(FORMATS, key=len, reverse=True):
        if lower.endswith(ext):
            return FORMATS[ext]
    return None


def format_size(n):
    for unit in ("B", "KB", "MB", "GB"):
        if n < 1024 or unit == "GB":
            return f"{n} B" if unit == "B" else f"{n:.1f} {unit}"
        n /= 1024


