def list_entries(path):
    if zipfile.is_zipfile(path):
        with zipfile.ZipFile(path) as zf:
            return [
                Entry(i.filename, i.file_size,
                      time.mktime(i.date_time + (0, 0, -1)), i.is_dir())
                for i in zf.infolist()
            ]
    if tarfile.is_tarfile(path):
        with tarfile.open(path, "r:*") as tf:
            return [Entry(m.name, m.size, m.mtime, m.isdir())
                    for m in tf.getmembers()]
    raise ValueError("Not a recognised zip or tar archive.")


def _inside(dest, name):
    root = os.path.realpath(dest)
    target = os.path.realpath(os.path.join(root, name))
    return target == root or target.startswith(root + os.sep)


def extract(path, dest, names=None, progress=None):
    """Extract `names` (or everything) into `dest`, refusing unsafe paths."""
    os.makedirs(dest, exist_ok=True)
    wanted = None if names is None else set(names)

    def selected(n):
        if wanted is None:
            return True
        n = n.rstrip("/")
        return any(n == w.rstrip("/") or n.startswith(w.rstrip("/") + "/")
                   for w in wanted)

    if zipfile.is_zipfile(path):
        with zipfile.ZipFile(path) as zf:
            infos = [i for i in zf.infolist() if selected(i.filename)]
            for k, info in enumerate(infos, 1):
                if not _inside(dest, info.filename):
                    raise ValueError(f"Unsafe path in archive: {info.filename}")
                zf.extract(info, dest)
                if progress:
                    progress(k, len(infos))
        return
    with tarfile.open(path, "r:*") as tf:
        members = [m for m in tf.getmembers() if selected(m.name)]
        for k, m in enumerate(members, 1):
            if not _inside(dest, m.name):
                raise ValueError(f"Unsafe path in archive: {m.name}")
            if hasattr(tarfile, "data_filter"):
                tf.extract(m, dest, filter="data")
            elif m.isfile() or m.isdir():
                tf.extract(m, dest)
            # without the filter, links/devices are skipped for safety
            if progress:
                progress(k, len(members))


def create(path, sources, progress=None):
    """Create an archive at `path` (format from extension) from files/dirs."""
    fmt = format_for(path)
    if fmt is None:
        raise ValueError("Use one of: " + ", ".join(FORMATS))
    kind, mode = fmt

    items = []
    for src in sources:
        src = os.path.abspath(src)
        base = os.path.dirname(src)
        if os.path.isdir(src):
            items.append((src, os.path.relpath(src, base)))
            for root, dirs, files in os.walk(src):
                for n in dirs + files:
                    full = os.path.join(root, n)
                    items.append((full, os.path.relpath(full, base)))
        else:
            items.append((src, os.path.relpath(src, base)))

    out = os.path.abspath(path)
    items = [(f, a) for f, a in items if os.path.abspath(f) != out]

    if kind == "zip":
        with zipfile.ZipFile(path, "w", zipfile.ZIP_DEFLATED) as zf:
            for k, (full, arc) in enumerate(items, 1):
                zf.write(full, arc)
                if progress:
                    progress(k, len(items))
    else:
        with tarfile.open(path, mode) as tf:
            for k, (full, arc) in enumerate(items, 1):
                tf.add(full, arc, recursive=False)
                if progress:
                    progress(k, len(items))


