"""Archive Manager: open, extract and create ZIP and TAR archives.

Uses only Python's standard library, so nothing extra needs to be installed.
Supported: .zip, .tar, .tar.gz / .tgz, .tar.bz2 / .tbz2, .tar.xz / .txz
"""

import os
import tarfile
import time
import tkinter as tk
import zipfile
from tkinter import filedialog, messagebox, ttk

TAR_MODES = {
    ".tar": "w",
    ".tar.gz": "w:gz",
    ".tgz": "w:gz",
    ".tar.bz2": "w:bz2",
    ".tbz2": "w:bz2",
    ".tar.xz": "w:xz",
    ".txz": "w:xz",
}

SAVE_TYPES = [
    ("ZIP archive", "*.zip"),
    ("TAR archive", "*.tar"),
    ("TAR + gzip", "*.tar.gz"),
    ("TAR + bzip2", "*.tar.bz2"),
    ("TAR + xz", "*.tar.xz"),
]


def human_size(n):
    for unit in ("B", "KB", "MB", "GB"):
        if n < 1024 or unit == "GB":
            return f"{n:.0f} {unit}" if unit == "B" else f"{n:.1f} {unit}"
        n /= 1024


def tar_mode_for(path):
    lower = path.lower()
    for ext, mode in TAR_MODES.items():
        if lower.endswith(ext):
            return mode
    return None


def is_inside(base, target):
    base = os.path.realpath(base)
    target = os.path.realpath(target)
    return target == base or target.startswith(base + os.sep)


class Archive:
    """A thin wrapper giving zip and tar files the same interface."""

    def __init__(self, path):
        self.path = path
        if zipfile.is_zipfile(path):
            self.kind = "zip"
            self.obj = zipfile.ZipFile(path)
        elif tarfile.is_tarfile(path):
            self.kind = "tar"
            self.obj = tarfile.open(path, "r:*")
        else:
            raise ValueError("This is not a ZIP or TAR archive.")

    def entries(self):
        """Return a list of (name, size, modified_text, is_dir)."""
        rows = []
        if self.kind == "zip":
            for i in self.obj.infolist():
                when = time.strftime("%Y-%m-%d %H:%M", (*i.date_time, 0, 0, -1))
                rows.append((i.filename, i.file_size, when, i.is_dir()))
        else:
            for m in self.obj.getmembers():
                when = time.strftime("%Y-%m-%d %H:%M", time.localtime(m.mtime))
                rows.append((m.name, m.size, when, m.isdir()))
        return rows

    def extract(self, dest, names=None):
        """Extract everything (names=None) or only the given names."""
        wanted = None if names is None else set(names)
        count = 0
        if self.kind == "zip":
            for info in self.obj.infolist():
                if wanted is not None and info.filename not in wanted:
                    continue
                if not is_inside(dest, os.path.join(dest, info.filename)):
                    continue  # skip unsafe paths like ../../x
                self.obj.extract(info, dest)
                count += 1
        else:
            for m in self.obj.getmembers():
                if wanted is not None and m.name not in wanted:
                    continue
                if not is_inside(dest, os.path.join(dest, m.name)):
                    continue
                if m.issym() or m.islnk() or m.isdev():
                    continue  # skip links/devices for safety
                self.obj.extract(m, dest)
                count += 1
        return count

    def close(self):
        self.obj.close()


def create_archive(out_path, sources):
    """Create an archive at out_path from a list of files/folders."""
    out_abs = os.path.abspath(out_path)

    def walk(src):
        """Yield (disk_path, name_in_archive) for src and everything in it."""
        src = os.path.abspath(src)
        base = os.path.dirname(src)
        yield src, os.path.basename(src)
        if os.path.isdir(src) and not os.path.islink(src):
            for root, dirs, files in os.walk(src):
                for n in dirs + files:
                    full = os.path.join(root, n)
                    yield full, os.path.relpath(full, base)

    items = [it for s in sources for it in walk(s) if os.path.abspath(it[0]) != out_abs]

    if out_path.lower().endswith(".zip"):
        with zipfile.ZipFile(out_path, "w", zipfile.ZIP_DEFLATED) as z:
            for full, name in items:
                z.write(full, name)
    else:
        mode = tar_mode_for(out_path)
        if mode is None:
            raise ValueError("Use a name ending in .zip, .tar, .tar.gz, .tar.bz2 or .tar.xz")
        with tarfile.open(out_path, mode) as t:
            for full, name in items:
                t.add(full, arcname=name, recursive=False)
    return len(items)


