        with zipfile.ZipFile(path) as zf:
            for i in zf.infolist():
                m = time.strftime("%Y-%m-%d %H:%M", time.struct_time(i.date_time + (0, 0, -1)))
                out.append(Entry(i.filename, i.file_size, m, i.is_dir()))
        return "zip", out
    import tarfile
    out = []
    with tarfile.open(path, "r:*") as tf:
        for m in tf:  # streamed; avoids getmembers() holding everything twice
            ts = time.strftime("%Y-%m-%d %H:%M", time.localtime(m.mtime))
            out.append(Entry(m.name, m.size, ts, m.isdir()))
    return "tar", out


def safe_target(root, name):
    """Resolve name under root, or return None if it would escape."""
    root = os.path.realpath(root)
    target = os.path.realpath(os.path.join(root, name))
    if target != root and not target.startswith(root + os.sep):
        return None
    return target


def wanted(name, selection):
    if selection is None:
        return True
    n = name.rstrip("/")
    return any(n == s or n.startswith(s + "/") for s in selection)


def copy_stream(src, dst_path):
    os.makedirs(os.path.dirname(dst_path), exist_ok=True)
    with open(dst_path, "wb") as dst:
        while True:
            buf = src.read(CHUNK)
            if not buf:
                break
            dst.write(buf)


def extract(path, dest, selection=None):
    """Extract (optionally only selected names). Returns (count, skipped)."""
    sel = None if selection is None else {s.rstrip("/") for s in selection}
    count = skipped = 0
    if is_zip(path):
        import zipfile
        with zipfile.ZipFile(path) as zf:
            for i in zf.infolist():
                if not wanted(i.filename, sel):
                    continue
                t = safe_target(dest, i.filename)
                if t is None:
                    skipped += 1
                elif i.is_dir():
                    os.makedirs(t, exist_ok=True)
                else:
                    with zf.open(i) as src:
                        copy_stream(src, t)
                    count += 1
        return count, skipped
    import tarfile
    with tarfile.open(path, "r:*") as tf:
        for m in tf:
            if not wanted(m.name, sel):
                continue
            t = safe_target(dest, m.name)
            if t is None or not (m.isfile() or m.isdir()):
                skipped += 1  # unsafe path, link, device, etc.
            elif m.isdir():
                os.makedirs(t, exist_ok=True)
            else:
                src = tf.extractfile(m)
                copy_stream(src, t)
                src.close()
                count += 1
    return count, skipped


def create(out_path, sources):
    """Create an archive from files/folders; format chosen by extension."""
    low = out_path.lower()
    items = []  # (disk path, archive name)
    for s in sources:
        s = os.path.abspath(s)
        base = os.path.dirname(s)
        if os.path.isdir(s):
            items.append((s, os.path.relpath(s, base)))
            for r, dirs, files in os.walk(s):
                for n in dirs + files:
                    p = os.path.join(r, n)
                    items.append((p, os.path.relpath(p, base)))
        else:
            items.append((s, os.path.basename(s)))
    if low.endswith(".zip"):
        import zipfile
        with zipfile.ZipFile(out_path, "w", zipfile.ZIP_DEFLATED) as zf:
            for p, n in items:
                if os.path.islink(p):
                    continue
                zf.write(p, n)  # streams from disk; directories get entries
    else:
        mode = next((m for ext, m in TAR_MODES.items() if low.endswith(ext)), None)
        if mode is None:
            raise ValueError("Unsupported extension. Use .zip, .tar, .tar.gz, .tar.bz2 or .tar.xz")
        import tarfile
        with tarfile.open(out_path, mode) as tf:
            for p, n in items:
                tf.add(p, n, recursive=False)
    return len(items)


def human(n):
    for u in ("B", "KB", "MB", "GB"):
        if n < 1024:
            return f"{n:.0f} {u}" if u == "B" else f"{n:.1f} {u}"
        n /= 1024
    return f"{n:.1f} TB"


