// MARK: - Subtitles

struct Cue { let start: Double; let end: Double; let text: String }

enum SRT {
    static func parse(_ url: URL) -> [Cue] {
        guard let data = try? Data(contentsOf: url) else { return [] }
        let raw = String(data: data, encoding: .utf8)
            ?? String(data: data, encoding: .windowsCP1251)
            ?? String(data: data, encoding: .isoLatin1) ?? ""
        let text = raw.replacingOccurrences(of: "\u{FEFF}", with: "")
            .replacingOccurrences(of: "\r\n", with: "\n")
            .replacingOccurrences(of: "\r", with: "\n")
        var cues: [Cue] = []
        for block in text.components(separatedBy: "\n\n") {
            let lines = block.split(separator: "\n", omittingEmptySubsequences: true).map(String.init)
            guard let i = lines.firstIndex(where: { $0.contains("-->") }) else { continue }
            let times = lines[i].components(separatedBy: "-->")
            guard times.count == 2, let s = seconds(times[0]), let e = seconds(times[1]) else { continue }
            let body = lines[(i + 1)...].joined(separator: "\n")
                .replacingOccurrences(of: "<[^>]+>|\\{\\\\[^}]*\\}", with: "", options: .regularExpression)
            if !body.isEmpty { cues.append(Cue(start: s, end: e, text: body)) }
        }
        return cues.sorted { $0.start < $1.start }
    }

    // Accepts "00:01:02,345", "00:01:02.345" and "01:02.345"; ignores trailing cue settings.
    private static func seconds(_ s: String) -> Double? {
        let token = s.trimmingCharacters(in: .whitespaces).split(separator: " ").first.map(String.init) ?? ""
        let parts = token.replacingOccurrences(of: ",", with: ".").split(separator: ":").compactMap { Double($0) }
        guard parts.count >= 2, parts.count <= 3 else { return nil }
        return parts.reduce(0) { $0 * 60 + $1 }
    }
}

