use image::imageops::FilterType;
use image::{ImageDecoder, ImageReader};
use minifb::{Key, KeyRepeat, MouseButton, MouseMode, Window, WindowOptions};
use std::collections::{HashMap, HashSet};
use std::path::{Path, PathBuf};
use std::sync::mpsc;
use std::thread;
use std::time::Duration;

const BG: u32 = 0x00_1e_1e_1e;
/// Longest side kept in memory; larger images are downscaled on load.
const MAX_SIDE: u32 = 4096;
const EXTS: &[&str] = &["jpg", "jpeg", "png", "gif", "bmp", "webp"];

struct Img {
    w: usize,
    h: usize,
    px: Vec<u32>,
}

fn decode(path: &Path) -> Result<Img, String> {
    let mut decoder = ImageReader::open(path)
        .map_err(|e| e.to_string())?
        .with_guessed_format()
        .map_err(|e| e.to_string())?
        .into_decoder()
        .map_err(|e| e.to_string())?;
    let orientation = decoder.orientation().ok();
    let mut img = image::DynamicImage::from_decoder(decoder).map_err(|e| e.to_string())?;
    if let Some(o) = orientation {
        img.apply_orientation(o);
    }
    if img.width().max(img.height()) > MAX_SIDE {
        img = img.resize(MAX_SIDE, MAX_SIDE, FilterType::Triangle);
    }
    let rgba = img.to_rgba8();
    let (w, h) = (rgba.width() as usize, rgba.height() as usize);
    let bg = [(BG >> 16) & 0xff, (BG >> 8) & 0xff, BG & 0xff];
    let px = rgba
        .pixels()
        .map(|p| {
            let a = p[3] as u32;
            let c = |i: usize| (p[i] as u32 * a + bg[i] * (255 - a)) / 255;
            (c(0) << 16) | (c(1) << 8) | c(2)
        })
        .collect();
    Ok(Img { w, h, px })
}

fn list_images(dir: &Path) -> Vec<PathBuf> {
    let mut v: Vec<PathBuf> = std::fs::read_dir(dir)
        .into_iter()
        .flatten()
        .flatten()
        .map(|e| e.path())
        .filter(|p| {
            p.extension()
                .and_then(|e| e.to_str())
                .is_some_and(|e| EXTS.contains(&e.to_ascii_lowercase().as_str()))
        })
        .collect();
    v.sort_by_key(|p| p.file_name().map(|n| n.to_ascii_lowercase_lossy()));
    v
}

trait Lower {
    fn to_ascii_lowercase_lossy(&self) -> String;
}
impl Lower for std::ffi::OsStr {
    fn to_ascii_lowercase_lossy(&self) -> String {
        self.to_string_lossy().to_lowercase()
    }
}

/// Map a point in the rotated image to the source image (rot = clockwise quarter turns).
fn to_src(rot: u8, iw: f32, ih: f32, rx: f32, ry: f32) -> (f32, f32) {
    match rot {
        0 => (rx, ry),
        1 => (ry, ih - rx),
        2 => (iw - rx, ih - ry),
        _ => (iw - ry, rx),
    }
}

fn render(buf: &mut [u32], w: usize, h: usize, img: &Img, rot: u8, z: f32, cx: f32, cy: f32) {
    let (iw, ih) = (img.w as f32, img.h as f32);
    let smooth = z < 1.0;
    let px = |x: i32, y: i32| -> u32 {
        let x = x.clamp(0, img.w as i32 - 1) as usize;
        let y = y.clamp(0, img.h as i32 - 1) as usize;
        img.px[y * img.w + x]
    };
    for sy in 0..h {
        let ry = (sy as f32 + 0.5 - h as f32 / 2.0) / z + cy;
        let row = &mut buf[sy * w..(sy + 1) * w];
        for (sx, out) in row.iter_mut().enumerate() {
            let rx = (sx as f32 + 0.5 - w as f32 / 2.0) / z + cx;
            let (x, y) = to_src(rot, iw, ih, rx, ry);
            if x < 0.0 || y < 0.0 || x >= iw || y >= ih {
                *out = BG;
            } else if !smooth {
                *out = px(x as i32, y as i32);
            } else {
                let (fx, fy) = (x - 0.5, y - 0.5);
                let (x0, y0) = (fx.floor(), fy.floor());
                let (tx, ty) = (fx - x0, fy - y0);
                let (x0, y0) = (x0 as i32, y0 as i32);
                let s = [px(x0, y0), px(x0 + 1, y0), px(x0, y0 + 1), px(x0 + 1, y0 + 1)];
                let wt = [
                    (1.0 - tx) * (1.0 - ty),
                    tx * (1.0 - ty),
                    (1.0 - tx) * ty,
                    tx * ty,
                ];
                let ch = |sh: u32| -> u32 {
                    let v: f32 = (0..4).map(|i| ((s[i] >> sh) & 0xff) as f32 * wt[i]).sum();
                    v as u32
                };
                *out = (ch(16) << 16) | (ch(8) << 8) | ch(0);
            }
        }
    }
}

struct View {
    rot: u8,
    zoom: f32,
    cx: f32,
    cy: f32,
}

impl View {
    fn dims(&self, img: &Img) -> (f32, f32) {
        if self.rot % 2 == 1 {
            (img.h as f32, img.w as f32)
        } else {
            (img.w as f32, img.h as f32)
        }
    }
    fn fit(&mut self, img: &Img, w: usize, h: usize) {
        let (rw, rh) = self.dims(img);
        self.zoom = (w as f32 / rw).min(h as f32 / rh).min(1.0);
        self.cx = rw / 2.0;
        self.cy = rh / 2.0;
    }
}

fn main() {
    let arg = std::env::args().nth(1).map(PathBuf::from);
    let (dir, first) = match arg {
        Some(p) if p.is_file() => (
            p.parent()
                .map(|d| if d.as_os_str().is_empty() { Path::new(".") } else { d })
                .unwrap_or(Path::new("."))
                .to_path_buf(),
            Some(p),
        ),
        Some(p) => (p, None),
        None => (PathBuf::from("."), None),
    };
    let files = list_images(&dir);
    if files.is_empty() {
        eprintln!("usage: quickview [image-or-folder]\nNo images found in {}", dir.display());
        std::process::exit(1);
    }
    let n = files.len();
    let mut want = first
        .and_then(|f| {
            let f = f.canonicalize().ok()?;
            files.iter().position(|p| p.canonicalize().ok().as_ref() == Some(&f))
        })
        .unwrap_or(0);

    let (req_tx, req_rx) = mpsc::channel::<(usize, PathBuf)>();
    let (res_tx, res_rx) = mpsc::channel::<(usize, Result<Img, String>)>();
    thread::spawn(move || {
        while let Ok((i, p)) = req_rx.recv() {
            if res_tx.send((i, decode(&p))).is_err() {
                break;
            }
        }
    });

    let (mut w, mut h) = (1024usize, 768usize);
    let mut window = Window::new(
        "quickview",
        w,
        h,

    v.sort_by_key(|p| p.file_name().map(|n| n.to_string_lossy().to_lowercase()));
    v
}

