#!/usr/bin/env python3
"""Photo Organizer: groups photos by date and lets you add tags.

Run:  python3 photo_organizer.py
It opens in your web browser. Nothing leaves your computer, and your
photos are never moved, renamed or changed. Tags are saved in a small file
called .photo_tags.json inside the photo folder.
"""
import datetime
import json
import os
import struct
import subprocess
import threading
import webbrowser
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from urllib.parse import urlparse, parse_qs

PORT = 8765
IMAGE_EXTS = {".jpg", ".jpeg", ".png", ".gif", ".webp", ".heic", ".bmp", ".tif", ".tiff"}
SETTINGS = os.path.join(os.path.expanduser("~"), ".photo_organizer_settings.json")
TAGS_NAME = ".photo_tags.json"

state = {"folder": None}
lock = threading.Lock()


# ---------- settings and tags ----------

def load_json(path, default):
    try:
        with open(path, encoding="utf-8") as f:
            return json.load(f)
    except (OSError, ValueError):
        return default


def save_json(path, data):
    tmp = path + ".tmp"
    with open(tmp, "w", encoding="utf-8") as f:
        json.dump(data, f, indent=2, ensure_ascii=False)
    os.replace(tmp, path)


def init_folder():
    folder = load_json(SETTINGS, {}).get("folder")
    if not folder or not os.path.isdir(folder):
        folder = os.path.join(os.path.expanduser("~"), "Pictures")
    state["folder"] = folder if os.path.isdir(folder) else os.path.expanduser("~")


def set_folder(folder):
    folder = os.path.abspath(os.path.expanduser(folder))
    if not os.path.isdir(folder):
        return False
    state["folder"] = folder
    save_json(SETTINGS, {"folder": folder})
    return True


# ---------- finding the date a photo was taken ----------

def exif_date(path):
    """Read the 'date taken' from a JPEG's EXIF data. Returns a datetime or None."""
    try:
        with open(path, "rb") as f:
            if f.read(2) != b"\xff\xd8":
                return None
            while True:
                head = f.read(4)
                if len(head) < 4 or head[0] != 0xFF:
                    return None
                marker, length = head[1], struct.unpack(">H", head[2:4])[0]
                if marker == 0xDA:
                    return None
                if marker == 0xE1:
                    data = f.read(length - 2)
                    if data[:6] == b"Exif\x00\x00":
                        return parse_tiff_date(data[6:])
                else:
                    f.seek(length - 2, 1)
    except (OSError, struct.error, ValueError):
        return None


def parse_tiff_date(t):
    e = "<" if t[:2] == b"II" else ">"

    def entries(offset):
        n = struct.unpack(e + "H", t[offset:offset + 2])[0]
        for i in range(n):
            tag, typ, count, val = struct.unpack(e + "HHII", t[offset + 2 + i * 12: offset + 14 + i * 12])
            yield tag, val

    def text_at(off):
        return t[off:off + 19].decode("ascii", "ignore")

    ifd0 = struct.unpack(e + "I", t[4:8])[0]
    found = None
    for tag, val in entries(ifd0):
        if tag == 0x8769:  # pointer to the Exif sub-section
            for tag2, val2 in entries(val):
                if tag2 == 0x9003:  # DateTimeOriginal
                    return datetime.datetime.strptime(text_at(val2), "%Y:%m:%d %H:%M:%S")
        elif tag == 0x0132:  # DateTime (fallback)
            found = val
    if found:
        return datetime.datetime.strptime(text_at(found), "%Y:%m:%d %H:%M:%S")
    return None


def photo_date(path):
    d = exif_date(path)
    if d is None:
        d = datetime.datetime.fromtimestamp(os.path.getmtime(path))
    return d


# ---------- scanning ----------

def scan(folder):
    tags = load_json(os.path.join(folder, TAGS_NAME), {})
    photos = []
    for root, dirs, files in os.walk(folder):
        dirs[:] = [d for d in dirs if not d.startswith(".")]
        for name in files:
            if name.startswith(".") or os.path.splitext(name)[1].lower() not in IMAGE_EXTS:
                continue
            full = os.path.join(root, name)
            rel = os.path.relpath(full, folder)
            try:
                d = photo_date(full)
            except OSError:
                continue
            photos.append({"path": rel, "date": d.strftime("%Y-%m-%d %H:%M"), "tags": tags.get(rel, [])})
    photos.sort(key=lambda p: p["date"], reverse=True)
    return photos


def choose_folder_dialog():
    script = 'POSIX path of (choose folder with prompt "Choose your photo folder")'
    try:
        out = subprocess.run(["osascript", "-e", script], capture_output=True, text=True, timeout=600)
        return out.stdout.strip() if out.returncode == 0 else None
    except (OSError, subprocess.SubprocessError):
        return None


# ---------- web server ----------

class Handler(BaseHTTPRequestHandler):
    def log_message(self, *args):
        pass

    def send_bytes(self, data, ctype, status=200):
        self.send_response(status)
        self.send_header("Content-Type", ctype)
        self.send_header("Content-Length", str(len(data)))
        self.end_headers()
        self.wfile.write(data)

    def send_obj(self, obj, status=200):
        self.send_bytes(json.dumps(obj).encode("utf-8"), "application/json", status)

    def read_body(self):
        n = int(self.headers.get("Content-Length", 0))
        return json.loads(self.rfile.read(n) or b"{}")

    def local_host_ok(self):
        return self.headers.get("Host", "").split(":")[0] in ("127.0.0.1", "localhost")

    def do_GET(self):
        if not self.local_host_ok():
            return self.send_bytes(b"Forbidden", "text/plain", 403)
        url = urlparse(self.path)
        if url.path == "/":
            return self.send_bytes(PAGE.encode("utf-8"), "text/html; charset=utf-8")
        if url.path == "/api/photos":
            with lock:
                folder = state["folder"]
                return self.send_obj({"folder": folder, "photos": scan(folder)})

"""Image processing core: resize and convert, independent of the GUI."""
from dataclasses import dataclass
from pathlib import Path

from PIL import Image, ImageOps

INPUT_EXTS = {".jpg", ".jpeg", ".png", ".webp", ".bmp", ".gif", ".tif", ".tiff"}

# label -> (Pillow format name, file extension)
FORMATS = {
    "Keep original": (None, None),
    "JPEG": ("JPEG", ".jpg"),
    "PNG": ("PNG", ".png"),
    "WEBP": ("WEBP", ".webp"),
    "BMP": ("BMP", ".bmp"),
    "TIFF": ("TIFF", ".tif"),
    "GIF": ("GIF", ".gif"),
}

MODES = ("Percent", "Fit within box", "Exact width", "Exact height", "No resize")


@dataclass
class Options:
    out_dir: Path
    format_label: str = "Keep original"
    mode: str = "Fit within box"
    percent: float = 50.0
    width: int = 1920
    height: int = 1080
    allow_upscale: bool = False
    quality: int = 85
    suffix: str = "_resized"
    overwrite: bool = False


def target_size(w, h, o):
    """Compute the output size for an input of w x h."""
    if o.mode == "Percent":
        scale = o.percent / 100
    elif o.mode == "Fit within box":
        scale = min(o.width / w, o.height / h)
    elif o.mode == "Exact width":
        scale = o.width / w
    elif o.mode == "Exact height":
        scale = o.height / h
    else:
        scale = 1
    if scale > 1 and not o.allow_upscale:
        scale = 1
    return max(1, round(w * scale)), max(1, round(h * scale))


def unique_path(p: Path) -> Path:
    if not p.exists():
        return p
    n = 1
    while True:
        cand = p.with_name(f"{p.stem}-{n}{p.suffix}")
        if not cand.exists():
            return cand
        n += 1


def process_one(src: Path, o: Options) -> Path:
    """Process a single file and return the path written."""
    with Image.open(src) as im:
        src_format = im.format
        im = ImageOps.exif_transpose(im)  # honour camera rotation
        fmt, ext = FORMATS[o.format_label]
        if fmt is None:
            fmt = src_format if src_format in ("JPEG", "PNG", "WEBP", "BMP", "TIFF", "GIF") else "PNG"
            ext = src.suffix.lower() if src_format else ".png"

        size = target_size(*im.size, o)
        if size != im.size:
            im = im.resize(size, Image.LANCZOS)

        save_kwargs = {}
        if fmt == "JPEG":
            if im.mode != "RGB":
                # flatten transparency onto white
                rgba = im.convert("RGBA")
                bg = Image.new("RGB", rgba.size, "white")
                bg.paste(rgba, mask=rgba.split()[3])
                im = bg
            save_kwargs = {"quality": o.quality, "optimize": True}
        elif fmt == "WEBP":
            save_kwargs = {"quality": o.quality}
        elif fmt == "PNG":
            save_kwargs = {"optimize": True}
            if im.mode not in ("1", "L", "LA", "P", "RGB", "RGBA", "I;16"):
                im = im.convert("RGBA")
        elif fmt in ("BMP", "GIF", "TIFF"):
            if fmt == "BMP" and im.mode not in ("1", "L", "P", "RGB"):
                im = im.convert("RGB")
            if fmt == "GIF" and im.mode not in ("1", "L", "P"):
                im = im.convert("RGBA") if "A" in im.mode else im.convert("RGB")

        o.out_dir.mkdir(parents=True, exist_ok=True)
        dest = o.out_dir / f"{src.stem}{o.suffix}{ext}"
        if not o.overwrite:
            dest = unique_path(dest)
        if dest.resolve() == src.resolve() and not o.overwrite:
            dest = unique_path(dest)
        im.save(dest, format=fmt, **save_kwargs)
        return dest


def collect_images(paths, recursive=True):
    """Expand files and folders into a de-duplicated list of image files."""
    seen, out = set(), []
    for p in map(Path, paths):
        if p.is_dir():
            it = p.rglob("*") if recursive else p.glob("*")
            files = sorted(f for f in it if f.is_file())
        else:
            files = [p]
        for f in files:
            if f.suffix.lower() in INPUT_EXTS and f not in seen:
                seen.add(f)
                out.append(f)
    return out

