#!/usr/bin/env python3
"""A simple personal podcast client.

Run it, and it opens a page in your web browser where you can subscribe to
podcast feeds and download episodes. Everything is saved in the
"my_podcasts" folder next to this file.
"""
import hashlib
import html
import json
import os
import re
import threading
import urllib.parse
import urllib.request
import webbrowser
import xml.etree.ElementTree as ET
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer

PORT = 8765
BASE = os.path.dirname(os.path.abspath(__file__))
DATA = os.path.join(BASE, "my_podcasts")
DOWNLOADS = os.path.join(DATA, "downloads")
DB_PATH = os.path.join(DATA, "subscriptions.json")
USER_AGENT = "Mozilla/5.0 (PersonalPodcastClient)"

lock = threading.Lock()
progress = {}  # (sid, eid) -> percent, or -1 on failure


def short_hash(text):
    return hashlib.sha1(text.encode("utf-8")).hexdigest()[:10]


def safe_name(text):
    text = re.sub(r'[\\/:*?"<>|\x00-\x1f]', "", text).strip(". ")
    return text[:80] or "untitled"


def load_subs():
    if not os.path.exists(DB_PATH):
        return []
    with open(DB_PATH, encoding="utf-8") as f:
        return json.load(f)


def save_subs(subs):
    os.makedirs(DATA, exist_ok=True)
    tmp = DB_PATH + ".tmp"
    with open(tmp, "w", encoding="utf-8") as f:
        json.dump(subs, f, indent=2)
    os.replace(tmp, DB_PATH)


def find_sub(subs, sid):
    return next((s for s in subs if s["id"] == sid), None)


def fetch_feed(url):
    """Download and parse an RSS feed. Returns (title, [episodes])."""
    req = urllib.request.Request(url, headers={"User-Agent": USER_AGENT})
    with urllib.request.urlopen(req, timeout=30) as resp:
        root = ET.fromstring(resp.read())
    channel = root.find("channel")
    if channel is None:
        raise ValueError("That doesn't look like a podcast feed.")
    title = (channel.findtext("title") or url).strip()
    episodes = []
    for item in channel.findall("item"):
        enc = item.find("enclosure")
        if enc is None or not enc.get("url"):
            continue
        audio = enc.get("url")
        ep_title = (item.findtext("title") or "Untitled").strip()
        guid = (item.findtext("guid") or audio).strip()
        episodes.append({
            "id": short_hash(guid),
            "title": ep_title,
            "date": (item.findtext("pubDate") or "")[:16],
            "audio": audio,
            "file": None,
        })
    if not episodes:
        raise ValueError("No episodes found in that feed.")
    return title, episodes


def refresh_sub(sub):
    title, fresh = fetch_feed(sub["url"])
    old = {e["id"]: e for e in sub["episodes"]}
    for e in fresh:
        if e["id"] in old:
            e["file"] = old[e["id"]]["file"]
    # Keep downloaded episodes that have dropped out of the feed.
    seen = {e["id"] for e in fresh}
    fresh += [e for e in old.values() if e["id"] not in seen and e["file"]]
    sub["title"] = title
    sub["episodes"] = fresh


def download_episode(sid, eid):
    key = (sid, eid)
    with lock:
        if key in progress and progress[key] >= 0:
            return  # already downloading
        progress[key] = 0
    try:
        with lock:
            sub = find_sub(load_subs(), sid)
            ep = next(e for e in sub["episodes"] if e["id"] == eid)
            folder = safe_name(sub["title"])
            audio_url, ep_title = ep["audio"], ep["title"]
        ext = os.path.splitext(urllib.parse.urlparse(audio_url).path)[1]
        if not re.fullmatch(r"\.\w{2,4}", ext):
            ext = ".mp3"
        rel = os.path.join(folder, safe_name(ep_title) + "-" + eid + ext)
        full = os.path.join(DOWNLOADS, rel)
        os.makedirs(os.path.dirname(full), exist_ok=True)
        req = urllib.request.Request(audio_url, headers={"User-Agent": USER_AGENT})
        with urllib.request.urlopen(req, timeout=30) as resp, open(full + ".part", "wb") as out:
            total = int(resp.headers.get("Content-Length") or 0)
            done = 0
            while True:
                chunk = resp.read(64 * 1024)
                if not chunk:
                    break
                out.write(chunk)
                done += len(chunk)
                if total:
                    progress[key] = int(done * 100 / total)
        os.replace(full + ".part", full)
        with lock:
            subs = load_subs()
            sub = find_sub(subs, sid)
            for e in sub["episodes"]:
                if e["id"] == eid:
                    e["file"] = rel
            save_subs(subs)
        progress.pop(key, None)
    except Exception:
        progress[key] = -1


def start_download(sid, eid):
    threading.Thread(target=download_episode, args=(sid, eid), daemon=True).start()


