// Snip: capture a screen region, annotate it (arrows, boxes, text), copy or save.
// Pure AppKit, no storyboards or third-party frameworks, to keep launch time and memory low.
import AppKit

enum Tool: Int { case arrow, box, text }

struct Annotation {
    var tool: Tool
    var start: NSPoint
    var end: NSPoint
    var text = ""
    var color: NSColor
}

let textFont = NSFont.boldSystemFont(ofSize: 22)

func normalizedRect(_ a: NSPoint, _ b: NSPoint) -> NSRect {
    NSRect(x: min(a.x, b.x), y: min(a.y, b.y), width: abs(a.x - b.x), height: abs(a.y - b.y))
}

func draw(_ a: Annotation) {
    a.color.setStroke()
    a.color.setFill()
    switch a.tool {
    case .box:
        let p = NSBezierPath(rect: normalizedRect(a.start, a.end))
        p.lineWidth = 3
        p.stroke()
    case .arrow:
        let dx = a.end.x - a.start.x, dy = a.end.y - a.start.y
        guard hypot(dx, dy) > 0 else { return }
        let angle = atan2(dy, dx)
        let head: CGFloat = 18
        let base = NSPoint(x: a.end.x - cos(angle) * head * 0.8, y: a.end.y - sin(angle) * head * 0.8)
        let line = NSBezierPath()
        line.lineWidth = 4
        line.lineCapStyle = .round
        line.move(to: a.start)
        line.line(to: base)
        line.stroke()
        let tri = NSBezierPath()
        tri.move(to: a.end)
        for s in [-0.45, 0.45] {
            tri.line(to: NSPoint(x: a.end.x - cos(angle + s) * head, y: a.end.y - sin(angle + s) * head))
        }
        tri.close()
        tri.fill()
    case .text:
        NSAttributedString(string: a.text, attributes: [.font: textFont, .foregroundColor: a.color])
            .draw(at: a.start)
    }
}

final class Canvas: NSView, NSTextFieldDelegate {
    var image: NSImage { didSet { annotations = []; finishEditing(commit: false); resize() } }
    var annotations: [Annotation] = []
    var tool: Tool = .arrow
    var color: NSColor = .systemRed
    private var current: Annotation?
    private var editor: NSTextField?
    private var editorOrigin = NSPoint.zero
    private var cancelled = false

    init(image: NSImage) {
        self.image = image
        super.init(frame: NSRect(origin: .zero, size: image.size))
    }
    required init?(coder: NSCoder) { fatalError() }

    override var isFlipped: Bool { true }
    override var acceptsFirstResponder: Bool { true }

    private func resize() {
        setFrameSize(image.size)
        needsDisplay = true
    }

    override func draw(_ dirtyRect: NSRect) {
        image.draw(in: bounds, from: .zero, operation: .copy, fraction: 1, respectFlipped: true, hints: nil)
        for a in annotations { Snip.draw(a) }
        if let c = current { Snip.draw(c) }
    }

    // MARK: Mouse

    override func mouseDown(with event: NSEvent) {
        finishEditing(commit: true)
        window?.makeFirstResponder(self)
        let p = convert(event.locationInWindow, from: nil)
        if tool == .text {
            beginEditing(at: p)
        } else {
            current = Annotation(tool: tool, start: p, end: p, color: color)
        }
    }

    override func mouseDragged(with event: NSEvent) {
        guard current != nil else { return }
        current?.end = convert(event.locationInWindow, from: nil)
        needsDisplay = true
    }

    override func mouseUp(with event: NSEvent) {
        guard let c = current else { return }
        current = nil
        if hypot(c.end.x - c.start.x, c.end.y - c.start.y) > 4 { annotations.append(c) }
        needsDisplay = true
    }

    // MARK: Text editing

    private func beginEditing(at p: NSPoint) {
        let f = NSTextField(frame: NSRect(x: p.x, y: p.y, width: 240, height: 30))
        f.isBordered = false
        f.drawsBackground = false
        f.focusRingType = .none
        f.font = textFont
        f.textColor = color
        f.placeholderString = "Text"
        f.delegate = self
        cancelled = false
        editor = f
        editorOrigin = p
        addSubview(f)
        window?.makeFirstResponder(f)
    }

    func finishEditing(commit: Bool) {
        guard let f = editor else { return }
        editor = nil
        let text = f.stringValue
        let col = color
        f.removeFromSuperview()
        if commit && !cancelled && !text.isEmpty {
            // The field has ~2pt of internal inset; compensate so text lands where it was typed.
            let origin = NSPoint(x: editorOrigin.x + 2, y: editorOrigin.y + 3)
            annotations.append(Annotation(tool: .text, start: origin, end: origin, text: text, color: col))
        }
        needsDisplay = true
    }

    func controlTextDidEndEditing(_ obj: Notification) { finishEditing(commit: true) }

    func control(_ control: NSControl, textView: NSTextView, doCommandBy sel: Selector) -> Bool {
        if sel == #selector(NSResponder.cancelOperation(_:)) {
            cancelled = true
            finishEditing(commit: false)
            return true
        }
        return false
    }

    override func keyDown(with event: NSEvent) {
        switch event.charactersIgnoringModifiers {
        case "1": (NSApp.delegate as? App)?.selectTool(.arrow)
        case "2": (NSApp.delegate as? App)?.selectTool(.box)
        case "3": (NSApp.delegate as? App)?.selectTool(.text)
        default: super.keyDown(with: event)
        }
    }

    // MARK: Output

    func undo() {
        guard !annotations.isEmpty else { return }
        annotations.removeLast()
        needsDisplay = true
    }

