#!/usr/bin/env python3
"""Simple drawing app: brushes, colours, undo/redo. Pure standard library (Tkinter)."""
import random
import sys
import tkinter as tk
from tkinter import colorchooser

PALETTE = ["#000000", "#7f7f7f", "#ffffff", "#e53935", "#fb8c00", "#fdd835",
           "#43a047", "#00acc1", "#1e88e5", "#8e24aa", "#d81b60", "#6d4c41"]
BG = "#ffffff"
BRUSHES = ["Pen", "Marker", "Spray", "Eraser"]


class Paint:
    def __init__(self, root):
        self.root = root
        root.title("Paint")
        self.color = "#000000"
        self.brush = tk.StringVar(value="Pen")
        self.size = tk.IntVar(value=4)
        self.undo_stack = []  # each entry: list of canvas item ids (one action)
        self.redo_stack = []
        self.current = None
        self.last = None

        bar = tk.Frame(root, padx=4, pady=4)
        bar.pack(side=tk.TOP, fill=tk.X)

        for b in BRUSHES:
            tk.Radiobutton(bar, text=b, value=b, variable=self.brush,
                           indicatoron=False, padx=8, pady=2).pack(side=tk.LEFT, padx=1)

        tk.Label(bar, text="  Size").pack(side=tk.LEFT)
        tk.Scale(bar, from_=1, to=60, orient=tk.HORIZONTAL, variable=self.size,
                 length=120, showvalue=True).pack(side=tk.LEFT)

        tk.Label(bar, text="  ").pack(side=tk.LEFT)
        for c in PALETTE:
            sw = tk.Frame(bar, bg=c, width=22, height=22, bd=1, relief=tk.RAISED)
            sw.pack(side=tk.LEFT, padx=1)
            sw.bind("<Button-1>", lambda e, c=c: self.set_color(c))
        tk.Button(bar, text="More…", command=self.pick_color).pack(side=tk.LEFT, padx=4)
        self.preview = tk.Frame(bar, bg=self.color, width=28, height=28, bd=2, relief=tk.SUNKEN)
        self.preview.pack(side=tk.LEFT, padx=2)

        tk.Button(bar, text="Clear", command=self.clear).pack(side=tk.RIGHT, padx=1)
        tk.Button(bar, text="Redo", command=self.redo).pack(side=tk.RIGHT, padx=1)
        tk.Button(bar, text="Undo", command=self.undo).pack(side=tk.RIGHT, padx=1)

        self.canvas = tk.Canvas(root, bg=BG, width=900, height=600,
                                highlightthickness=0, cursor="crosshair")
        self.canvas.pack(fill=tk.BOTH, expand=True)
        self.canvas.bind("<ButtonPress-1>", self.start)
        self.canvas.bind("<B1-Motion>", self.move)
        self.canvas.bind("<ButtonRelease-1>", self.end)

        mod = "Command" if sys.platform == "darwin" else "Control"
        root.bind(f"<{mod}-z>", lambda e: self.undo())
        root.bind(f"<{mod}-Z>", lambda e: self.redo())
        root.bind(f"<{mod}-y>", lambda e: self.redo())

        self.spray_job = None

    # --- colour ---
    def set_color(self, c):
        self.color = c
        self.preview.config(bg=c)
        if self.brush.get() == "Eraser":
            self.brush.set("Pen")

    def pick_color(self):
        _, hexc = colorchooser.askcolor(color=self.color, parent=self.root)
        if hexc:
            self.set_color(hexc)

    # --- drawing ---
    def start(self, e):
        self.current = []
        self.last = (e.x, e.y)
        self.pos = (e.x, e.y)
        if self.brush.get() == "Spray":
            self.spray()
        else:
            self.segment(e.x, e.y, e.x, e.y)

    def move(self, e):
        if self.current is None:
            return
        self.pos = (e.x, e.y)
        if self.brush.get() != "Spray":
            self.segment(*self.last, e.x, e.y)
        self.last = (e.x, e.y)

    def end(self, e):
        if self.current is None:
            return
        if self.spray_job:
            self.root.after_cancel(self.spray_job)
            self.spray_job = None
        if self.current:
            self.undo_stack.append(self.current)
            self.discard_redo()
        self.current = None

    def segment(self, x0, y0, x1, y1):
        b, s = self.brush.get(), self.size.get()
        if b == "Eraser":
            col, w, kw = BG, s * 2, {}
        elif b == "Marker":
            col, w, kw = self.color, s * 2, {"stipple": "gray50"}
        else:
            col, w, kw = self.color, s, {}
        i = self.canvas.create_line(x0, y0, x1, y1, fill=col, width=w,
                                    capstyle=tk.ROUND, joinstyle=tk.ROUND, **kw)
        self.current.append(i)

    def spray(self):
        if self.current is None:
            return
        x, y = self.pos
        r = self.size.get() * 2 + 4
        for _ in range(12):
            dx, dy = random.uniform(-r, r), random.uniform(-r, r)
            if dx * dx + dy * dy <= r * r:
                self.current.append(self.canvas.create_rectangle(
                    x + dx, y + dy, x + dx + 1, y + dy + 1,
                    fill=self.color, outline=self.color))
        self.spray_job = self.root.after(20, self.spray)

    # --- history (undo hides items so redo can restore them) ---
    def discard_redo(self):
        for items in self.redo_stack:
            self.canvas.delete(*items)
        self.redo_stack.clear()

    def undo(self):
        if self.undo_stack:
            items = self.undo_stack.pop()
            for i in items:
                self.canvas.itemconfigure(i, state="hidden")
            self.redo_stack.append(items)

    def redo(self):
        if self.redo_stack:
            items = self.redo_stack.pop()
            for i in items:
                self.canvas.itemconfigure(i, state="normal")
            self.undo_stack.append(items)

    def clear(self):
        visible = [i for i in self.canvas.find_all()
                   if self.canvas.itemcget(i, "state") != "hidden"]
        if visible:
            for i in visible:
                self.canvas.itemconfigure(i, state="hidden")
            self.undo_stack.append(visible)
            self.discard_redo()


if __name__ == "__main__":
    root = tk.Tk()
    Paint(root)
    root.mainloop()

