import Cocoa

// Font browser: native AppKit, no dependencies.
// Only family names are loaded at launch; NSFont objects are created lazily
// for the handful of rows on screen (the table reuses cells), so startup and
// memory stay flat no matter how many fonts are installed.

let defaultSample = "The quick brown fox jumps over the lazy dog 0123456789"

final class FontCell: NSTableCellView {
    static let id = NSUserInterfaceItemIdentifier("FontCell")
    let nameLabel = NSTextField(labelWithString: "")
    let sampleLabel = NSTextField(labelWithString: "")

    override init(frame: NSRect) {
        super.init(frame: frame)
        nameLabel.font = .systemFont(ofSize: 11)
        nameLabel.textColor = .secondaryLabelColor
        for l in [nameLabel, sampleLabel] {
            l.lineBreakMode = .byTruncatingTail
            l.usesSingleLineMode = true
            addSubview(l)
        }
    }

    required init?(coder: NSCoder) { fatalError() }

    override func layout() {
        super.layout()
        let w = bounds.width - 24
        nameLabel.frame = NSRect(x: 12, y: bounds.height - 18, width: w, height: 14)
        sampleLabel.frame = NSRect(x: 12, y: 4, width: w, height: bounds.height - 24)
    }
}

final class Controller: NSObject, NSTableViewDataSource, NSTableViewDelegate, NSSearchFieldDelegate, NSTextFieldDelegate {
    let allFamilies: [String]
    var shown: [String]
    var sample = defaultSample
    var size: CGFloat = 32

    let window: NSWindow
    let table = NSTableView()
    let search = NSSearchField()
    let sampleField = NSTextField()
    let slider = NSSlider(value: 32, minValue: 10, maxValue: 120, target: nil, action: nil)
    let sizeLabel = NSTextField(labelWithString: "32 pt")
    let countLabel = NSTextField(labelWithString: "")

    override init() {
        allFamilies = NSFontManager.shared.availableFontFamilies
            .sorted { $0.localizedCaseInsensitiveCompare($1) == .orderedAscending }
        shown = allFamilies
        window = NSWindow(contentRect: NSRect(x: 0, y: 0, width: 820, height: 640),
                          styleMask: [.titled, .closable, .miniaturizable, .resizable],
                          backing: .buffered, defer: false)
        super.init()
        build()
    }

    func build() {
        window.title = "Font Browser"
        window.setFrameAutosaveName("MainWindow")
        if !window.setFrameUsingName("MainWindow") { window.center() }

        search.placeholderString = "Search fonts"
        search.delegate = self
        sampleField.placeholderString = "Sample text"
        sampleField.delegate = self
        slider.target = self
        slider.action = #selector(sizeChanged)
        sizeLabel.alignment = .right
        countLabel.textColor = .secondaryLabelColor
        countLabel.font = .systemFont(ofSize: 11)

        let col = NSTableColumn(identifier: NSUserInterfaceItemIdentifier("c"))
        col.resizingMask = .autoresizingMask
        table.addTableColumn(col)
        table.headerView = nil
        table.dataSource = self
        table.delegate = self
        table.usesAutomaticRowHeights = false
        table.rowHeight = rowHeight()
        table.style = .plain

        let scroll = NSScrollView()
        scroll.documentView = table
        scroll.hasVerticalScroller = true
        table.columnAutoresizingStyle = .uniformColumnAutoresizingStyle

        let top = NSStackView(views: [search, sampleField, slider, sizeLabel])
        top.orientation = .horizontal
        top.spacing = 10
        search.widthAnchor.constraint(equalToConstant: 180).isActive = true
        slider.widthAnchor.constraint(equalToConstant: 120).isActive = true
        sizeLabel.widthAnchor.constraint(equalToConstant: 48).isActive = true
        sampleField.setContentHuggingPriority(.defaultLow, for: .horizontal)

        let root = NSStackView(views: [top, scroll, countLabel])
        root.orientation = .vertical
        root.alignment = .leading
        root.spacing = 8
        root.edgeInsets = NSEdgeInsets(top: 10, left: 10, bottom: 8, right: 10)
        top.translatesAutoresizingMaskIntoConstraints = false
        scroll.translatesAutoresizingMaskIntoConstraints = false
        top.widthAnchor.constraint(equalTo: root.widthAnchor, constant: -20).isActive = true
        scroll.widthAnchor.constraint(equalTo: root.widthAnchor, constant: -20).isActive = true
        scroll.heightAnchor.constraint(greaterThanOrEqualToConstant: 200).isActive = true
        window.contentView = root
        updateCount()
    }

    func rowHeight() -> CGFloat { (size * 1.5).rounded() + 26 }

    func updateCount() {
        countLabel.stringValue = "\(shown.count) of \(allFamilies.count) families"
    }

    @objc func sizeChanged() {
        size = CGFloat(slider.doubleValue.rounded())
        sizeLabel.stringValue = "\(Int(size)) pt"
        table.rowHeight = rowHeight()
        table.reloadData()
    }

    func controlTextDidChange(_ obj: Notification) {
        if (obj.object as? NSTextField) === sampleField {
            let s = sampleField.stringValue
            sample = s.isEmpty ? defaultSample : s
