import Cocoa

// Minimal native vector editor. AppKit only, no third-party dependencies,
// no web view: fast launch and a small memory footprint.

enum Kind { case rect, ellipse, line, path }

struct Shape {
    var kind: Kind
    var pts: [CGPoint]
    var fill: NSColor?
    var stroke: NSColor
    var width: CGFloat

    var bounds: CGRect {
        let xs = pts.map { $0.x }, ys = pts.map { $0.y }
        guard let x0 = xs.min(), let x1 = xs.max(), let y0 = ys.min(), let y1 = ys.max() else { return .zero }
        return CGRect(x: x0, y: y0, width: x1 - x0, height: y1 - y0)
    }

    var bezier: NSBezierPath {
        let b = bounds
        let p: NSBezierPath
        switch kind {
        case .rect: p = NSBezierPath(rect: b)
        case .ellipse: p = NSBezierPath(ovalIn: b)
        case .line, .path:
            p = NSBezierPath()
            p.move(to: pts[0])
            for q in pts.dropFirst() { p.line(to: q) }
        }
        p.lineWidth = width
        p.lineCapStyle = .round
        p.lineJoinStyle = .round
        return p
    }

    func hit(_ pt: CGPoint) -> Bool {
        let tol = max(6, width / 2 + 3)
        switch kind {
        case .rect, .ellipse:
            return bounds.insetBy(dx: -tol, dy: -tol).contains(pt)
        case .line, .path:
            if pts.count == 1 { return hypot(pts[0].x - pt.x, pts[0].y - pt.y) <= tol }
            for i in 1..<pts.count where dist(pt, pts[i - 1], pts[i]) <= tol { return true }
            return false
        }
    }

    private func dist(_ p: CGPoint, _ a: CGPoint, _ b: CGPoint) -> CGFloat {
        let dx = b.x - a.x, dy = b.y - a.y
        let len2 = dx * dx + dy * dy
        var t = len2 == 0 ? 0 : ((p.x - a.x) * dx + (p.y - a.y) * dy) / len2
        t = min(1, max(0, t))
        return hypot(p.x - (a.x + t * dx), p.y - (a.y + t * dy))
    }

    func svg() -> String {
        func n(_ v: CGFloat) -> String {
            let s = String(format: "%.2f", Double(v))
            return s.contains(".") ? s.replacingOccurrences(of: #"\.?0+$"#, with: "", options: .regularExpression) : s
        }
        let b = bounds
        let fillAttr = (kind == .rect || kind == .ellipse) ? (fill.map(hex) ?? "none") : "none"
        let style = "fill=\"\(fillAttr)\" stroke=\"\(hex(stroke))\" stroke-width=\"\(n(width))\" stroke-linecap=\"round\" stroke-linejoin=\"round\""
        switch kind {
        case .rect:
            return "<rect x=\"\(n(b.minX))\" y=\"\(n(b.minY))\" width=\"\(n(b.width))\" height=\"\(n(b.height))\" \(style)/>"
        case .ellipse:
            return "<ellipse cx=\"\(n(b.midX))\" cy=\"\(n(b.midY))\" rx=\"\(n(b.width / 2))\" ry=\"\(n(b.height / 2))\" \(style)/>"
        case .line:
            return "<line x1=\"\(n(pts[0].x))\" y1=\"\(n(pts[0].y))\" x2=\"\(n(pts[1].x))\" y2=\"\(n(pts[1].y))\" \(style)/>"
        case .path:
            let d = pts.enumerated().map { "\($0.offset == 0 ? "M" : "L")\(n($0.element.x)) \(n($0.element.y))" }.joined(separator: " ")
            return "<path d=\"\(d)\" \(style)/>"
        }
    }
}

func hex(_ c: NSColor) -> String {
    let s = c.usingColorSpace(.sRGB) ?? c
    func b(_ v: CGFloat) -> Int { Int((v * 255).rounded()) }
    return String(format: "#%02x%02x%02x", b(s.redComponent), b(s.greenComponent), b(s.blueComponent))
}

