import Cocoa

// MARK: - Model

enum Kind { case object, array, string, number, bool, null }

/// Scalars keep their raw source text (so formatting never alters numbers or escapes).
final class Node {
    let kind: Kind
    var key: String?      // raw key including quotes (objects only)
    var index = -1        // position inside an array parent
    var raw = ""
    var children: [Node] = []
    init(_ kind: Kind) { self.kind = kind }
}

struct ParseError: Error { let offset: Int; let message: String }

// MARK: - Parser (order-preserving, recursive descent over UTF-8 bytes)

struct Parser {
    let b: [UInt8]
    var i = 0
    var count = 0
    init(_ b: [UInt8]) { self.b = b }

    mutating func parseDocument() throws -> Node {
        let n = try parseValue(0)
        skipWS()
        if i < b.count { throw ParseError(offset: i, message: "Unexpected data after value") }
        return n
    }

    mutating func skipWS() {
        while i < b.count, b[i] == 0x20 || b[i] == 0x09 || b[i] == 0x0A || b[i] == 0x0D { i += 1 }
    }

    mutating func parseValue(_ depth: Int) throws -> Node {
        if depth > 512 { throw ParseError(offset: i, message: "Nesting too deep") }
        skipWS()
        guard i < b.count else { throw ParseError(offset: i, message: "Unexpected end of input") }
        count += 1
        switch b[i] {
        case 0x7B: return try parseContainer(.object, depth)
        case 0x5B: return try parseContainer(.array, depth)
        case 0x22:
            let n = Node(.string)
            n.raw = try scanString()
            return n
        case 0x74: return try literal("true", .bool)
        case 0x66: return try literal("false", .bool)
        case 0x6E: return try literal("null", .null)
        default:
            let start = i
            while i < b.count, (b[i] >= 0x30 && b[i] <= 0x39) || b[i] == 0x2B || b[i] == 0x2D
                    || b[i] == 0x2E || b[i] == 0x65 || b[i] == 0x45 { i += 1 }
            guard i > start else { throw ParseError(offset: i, message: "Unexpected character") }
            let n = Node(.number)
            n.raw = String(decoding: b[start..<i], as: UTF8.self)
            return n
        }
    }

    mutating func literal(_ word: String, _ kind: Kind) throws -> Node {
        let u = Array(word.utf8)
        guard i + u.count <= b.count, Array(b[i..<i + u.count]) == u else {
            throw ParseError(offset: i, message: "Invalid literal")
        }
        i += u.count
        let n = Node(kind)
        n.raw = word
        return n
    }

    mutating func scanString() throws -> String {
        let start = i
        i += 1
        while i < b.count {
            let c = b[i]
            if c == 0x22 {
                i += 1
                return String(decoding: b[start..<i], as: UTF8.self)
            }
            if c == 0x5C { i += 2; continue }
            if c < 0x20 { throw ParseError(offset: i, message: "Control character in string") }
            i += 1
        }
        throw ParseError(offset: start, message: "Unterminated string")
    }

    mutating func parseContainer(_ kind: Kind, _ depth: Int) throws -> Node {
        let close: UInt8 = kind == .object ? 0x7D : 0x5D
        let node = Node(kind)
        i += 1
        skipWS()
        if i < b.count, b[i] == close { i += 1; return node }
        while true {
            skipWS()
            var key: String?
            if kind == .object {
                guard i < b.count, b[i] == 0x22 else { throw ParseError(offset: i, message: "Expected string key") }
                key = try scanString()
                skipWS()
                guard i < b.count, b[i] == 0x3A else { throw ParseError(offset: i, message: "Expected ':'") }
                i += 1
            }
            let child = try parseValue(depth + 1)
            child.key = key
            child.index = node.children.count
            node.children.append(child)
            skipWS()
            guard i < b.count else { throw ParseError(offset: i, message: "Unexpected end of input") }
            if b[i] == 0x2C { i += 1; continue }
            if b[i] == close { i += 1; return node }
            throw ParseError(offset: i, message: "Expected ',' or closing bracket")
        }
    }
}

// MARK: - Serializer

func write(_ n: Node, pretty: Bool, level: Int, _ out: inout String) {
    guard n.kind == .object || n.kind == .array else { out += n.raw; return }
    let isObj = n.kind == .object
    if n.children.isEmpty { out += isObj ? "{}" : "[]"; return }
    out += isObj ? "{" : "["
    for (idx, c) in n.children.enumerated() {
        if idx > 0 { out += "," }
        if pretty { out += "\n"; out += String(repeating: "  ", count: level + 1) }
        if isObj { out += c.key ?? ""; out += pretty ? ": " : ":" }
        write(c, pretty: pretty, level: level + 1, &out)
    }
    if pretty { out += "\n"; out += String(repeating: "  ", count: level) }
    out += isObj ? "}" : "]"
}

