#!/usr/bin/env python3
"""A simple SQLite database browser with a query editor.

Run:  python3 sqlite_browser.py [optional_database_file]
It opens in your web browser. Everything stays on your computer.
"""
import json
import os
import secrets
import sqlite3
import subprocess
import sys
import threading
import webbrowser
from http.server import BaseHTTPRequestHandler, HTTPServer

TOKEN = secrets.token_urlsafe(24)
MAX_ROWS = 1000
state = {"conn": None, "path": None, "writable": False}


def quote(name):
    return '"' + name.replace('"', '""') + '"'


def connect(path, writable):
    path = os.path.abspath(os.path.expanduser(path.strip().strip("'\"")))
    if not os.path.isfile(path):
        raise ValueError("File not found: " + path)
    uri = "file:" + path.replace("?", "%3f").replace("#", "%23")
    uri += "?mode=rw" if writable else "?mode=ro"
    conn = sqlite3.connect(uri, uri=True, check_same_thread=False)
    conn.execute("SELECT count(*) FROM sqlite_master").fetchone()  # validates file
    if state["conn"]:
        state["conn"].close()
    state.update(conn=conn, path=path, writable=writable)


def need_conn():
    if not state["conn"]:
        raise ValueError("No database is open yet.")
    return state["conn"]


def api_open(body):
    connect(body["path"], bool(body.get("writable")))
    return {"path": state["path"], "writable": state["writable"]}


def api_browse(body):
    script = 'POSIX path of (choose file with prompt "Choose a SQLite database")'
    r = subprocess.run(["osascript", "-e", script], capture_output=True, text=True)
    if r.returncode != 0:
        return {"path": ""}  # cancelled or unavailable
    return {"path": r.stdout.strip()}


def api_tables(body):
    conn = need_conn()
    rows = conn.execute(
        "SELECT name, type, sql FROM sqlite_master "
        "WHERE type IN ('table','view') AND name NOT LIKE 'sqlite_%' ORDER BY name"
    ).fetchall()
    out = []
    for name, typ, sql in rows:
        cols = [c[1] + " " + (c[2] or "") for c in conn.execute(f"PRAGMA table_info({quote(name)})")]
        out.append({"name": name, "type": typ, "sql": sql, "columns": cols})
    return {"path": state["path"], "writable": state["writable"], "tables": out}


def api_query(body):
    conn = need_conn()
    sql = body["sql"]
    cur = conn.cursor()
    cur.execute(sql)
    if cur.description:
        cols = [d[0] for d in cur.description]
        rows = cur.fetchmany(MAX_ROWS + 1)
        truncated = len(rows) > MAX_ROWS
        rows = [[v if not isinstance(v, bytes) else f"<{len(v)} bytes>" for v in r] for r in rows[:MAX_ROWS]]
        return {"columns": cols, "rows": rows, "truncated": truncated}
    conn.commit()
    return {"message": f"Done. {cur.rowcount if cur.rowcount >= 0 else 0} row(s) affected."}


ROUTES = {"/api/open": api_open, "/api/browse": api_browse,
          "/api/tables": api_tables, "/api/query": api_query}


class Handler(BaseHTTPRequestHandler):
    def log_message(self, *a):
        pass

    def host_ok(self):
        return self.headers.get("Host", "").split(":")[0] in ("127.0.0.1", "localhost")

    def send(self, code, data, ctype="application/json"):
        raw = data if isinstance(data, bytes) else data.encode()
        self.send_response(code)
        self.send_header("Content-Type", ctype + "; charset=utf-8")
        self.send_header("Content-Length", str(len(raw)))
        self.end_headers()
        self.wfile.write(raw)

    def do_GET(self):
        if not self.host_ok() or self.path.split("?")[0] != "/" or ("t=" + TOKEN) not in self.path:
            return self.send(403, "Forbidden", "text/plain")
        self.send(200, PAGE.replace("__TOKEN__", TOKEN), "text/html")

    def do_POST(self):
        fn = ROUTES.get(self.path)
        if not self.host_ok() or self.headers.get("X-Token") != TOKEN or not fn:
            return self.send(403, json.dumps({"error": "Forbidden"}))
        try:
            n = int(self.headers.get("Content-Length", 0))
            body = json.loads(self.rfile.read(n) or b"{}")
            self.send(200, json.dumps(fn(body), default=str))
        except Exception as e:
            self.send(200, json.dumps({"error": str(e)}))


