"""Side-by-side text file diff tool.

Usage:
    python3 diff_tool.py                 (pops up windows to pick the two files)
    python3 diff_tool.py old.txt new.txt (compare the given files)

The result opens in your web browser. Nothing is modified or uploaded.
"""
import difflib
import subprocess
import sys
import tempfile
import webbrowser
from pathlib import Path

CSS = """
<style>
  body { font-family: -apple-system, Helvetica, Arial, sans-serif; margin: 20px; }
  h1 { font-size: 18px; }
  table.diff { font-family: Menlo, Courier, monospace; font-size: 13px;
               border: 1px solid #999; border-collapse: collapse; width: 100%; }
  table.diff td { padding: 1px 4px; vertical-align: top; white-space: pre-wrap; }
  .diff_header { background: #e0e0e0; color: #555; text-align: right; }
  td.diff_header { text-align: right; }
  .diff_next { background: #c0c0c0; }
  .diff_add { background: #aaffaa; }
  .diff_chg { background: #ffff77; }
  .diff_sub { background: #ffaaaa; }
  .legend span { padding: 2px 8px; margin-right: 8px; border: 1px solid #999; }
</style>
"""


def pick_file(prompt):
    """Show a macOS file-chooser dialog and return the chosen path (or None)."""
    script = f'POSIX path of (choose file with prompt "{prompt}")'
    result = subprocess.run(["osascript", "-e", script],
                            capture_output=True, text=True)
    path = result.stdout.strip()
    return path or None


def read_lines(path):
    try:
        return Path(path).read_text(encoding="utf-8", errors="replace").splitlines()
    except OSError as err:
        sys.exit(f"Could not read {path}: {err}")


def main():
    if len(sys.argv) == 3:
        left, right = sys.argv[1], sys.argv[2]
    elif len(sys.argv) == 1:
        left = pick_file("Choose the FIRST (original) file")
        right = left and pick_file("Choose the SECOND (changed) file")
        if not left or not right:
            sys.exit("Cancelled.")
    else:
        sys.exit(__doc__)

    a, b = read_lines(left), read_lines(right)
    if a == b:
        print("The files are identical.")

    table = difflib.HtmlDiff(wrapcolumn=80).make_table(
        a, b, Path(left).name, Path(right).name, context=False)

    html = f"""<!DOCTYPE html><html><head><meta charset="utf-8">
<title>Diff: {Path(left).name} vs {Path(right).name}</title>{CSS}</head><body>
<h1>{Path(left).name} &nbsp;vs&nbsp; {Path(right).name}</h1>
<p class="legend"><span class="diff_add">Added</span>
<span class="diff_chg">Changed</span>
<span class="diff_sub">Removed</span></p>
{"<p><b>The files are identical.</b></p>" if a == b else ""}
{table}
</body></html>"""

    out = Path(tempfile.gettempdir()) / "diff_result.html"
    out.write_text(html, encoding="utf-8")
    webbrowser.open(out.as_uri())
    print(f"Opened comparison in your browser ({out}).")


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""A small Git client: commit graph, staging, and committing.

Run:  python3 gitclient.py [path-to-repo]
It opens in your web browser. Only needs Python 3 and git. Stop with Ctrl+C.
"""
import json
import os
import secrets
import subprocess
import sys
import threading
import webbrowser
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from urllib.parse import parse_qs, urlparse

TOKEN = secrets.token_urlsafe(24)
STATE = {"repo": os.path.abspath(sys.argv[1] if len(sys.argv) > 1 else os.getcwd())}
LOCK = threading.Lock()


def git(*args, check=True):
    p = subprocess.run(["git", *args], cwd=STATE["repo"], capture_output=True)
    out = p.stdout.decode("utf-8", "replace")
    if check and p.returncode != 0:
        raise RuntimeError(p.stderr.decode("utf-8", "replace").strip() or "git failed")
    return out


def is_repo(path):
    if not os.path.isdir(path):
        return False
    p = subprocess.run(["git", "rev-parse", "--show-toplevel"], cwd=path, capture_output=True)
    if p.returncode == 0:
        STATE["repo"] = p.stdout.decode().strip()
        return True
    return False


def has_head():
    return subprocess.run(["git", "rev-parse", "--verify", "-q", "HEAD"],
                          cwd=STATE["repo"], capture_output=True).returncode == 0


def api_status():
    if not is_repo(STATE["repo"]):
        return {"repo": STATE["repo"], "valid": False}
    branch = git("branch", "--show-current").strip() or "(detached HEAD)"
    parts = git("status", "--porcelain=v1", "-z", "--untracked-files=all").split("\0")
    files, i = [], 0
    while i < len(parts):
        e = parts[i]
        i += 1
        if len(e) < 4:
            continue
        x, y, path = e[0], e[1], e[3:]
        if x in "RC":
            i += 1  # skip original name
        files.append({"path": path, "x": x, "y": y})
    return {"repo": STATE["repo"], "valid": True, "branch": branch, "files": files}


def api_log():
    if not has_head():
        return {"commits": []}
    fmt = "%H%x1f%P%x1f%an%x1f%ad%x1f%D%x1f%s"
    out = git("log", "--all", "--date-order", "-n", "500", "--date=format:%Y-%m-%d %H:%M",
              "--format=" + fmt)
    commits = []
    for line in out.splitlines():
        h, p, an, ad, refs, s = line.split("\x1f", 5)
        commits.append({"hash": h, "parents": p.split(), "author": an, "date": ad,
                        "refs": [r.strip() for r in refs.split(",") if r.strip()], "subject": s})
    return {"commits": commits}


def api_diff(path, staged):
    if staged:
        args = ["diff", "--cached"] + ([] if has_head() else [])
        return {"diff": git(*args, "--", path)}
    st = git("status", "--porcelain=v1", "--untracked-files=all", "--", path)
    if st.startswith("??"):
        return {"diff": git("diff", "--no-index", "--", os.devnull, path, check=False)}
    return {"diff": git("diff", "--", path)}


def api_show(h):
    return {"diff": git("show", "--stat", "--patch", "--format=fuller", h)}


def api_post(name, body):
    paths = body.get("paths", [])
    if name == "stage":
        git("add", "-A", "--", *paths)
    elif name == "unstage":
        if has_head():
            git("restore", "--staged", "--", *paths)
        else:
            git("rm", "--cached", "-r", "-q", "--", *paths)
    elif name == "commit":
        msg = body.get("message", "").strip()
        if not msg:
            raise RuntimeError("Please write a commit message.")
        if not git("diff", "--cached", "--name-only").strip():
            raise RuntimeError("Nothing is staged. Stage some files first.")
        git("commit", "-m", msg)
    elif name == "open":
        path = os.path.abspath(os.path.expanduser(body.get("path", "")))
        if not is_repo(path):
            raise RuntimeError("That folder is not a Git repository.")
    else:
        raise RuntimeError("unknown action")
    return {"ok": True}


class Handler(BaseHTTPRequestHandler):
    def log_message(self, *a):
        pass

    def _send(self, code, body, ctype="application/json"):
        data = body if isinstance(body, bytes) else body.encode()
        self.send_response(code)
        self.send_header("Content-Type", ctype + "; charset=utf-8")
        self.send_header("Content-Length", str(len(data)))
        self.send_header("Cache-Control", "no-store")
        self.end_headers()
        self.wfile.write(data)

    def _handle(self, method):
        # Block DNS-rebinding: only accept requests addressed to localhost.
        if self.headers.get("Host", "").split(":")[0] not in ("127.0.0.1", "localhost"):
            return self._send(403, "forbidden", "text/plain")
        u = urlparse(self.path)
        if u.path == "/" and method == "GET":
            return self._send(200, PAGE.replace("__TOKEN__", TOKEN), "text/html")
        if not u.path.startswith("/api/") or self.headers.get("X-Token") != TOKEN:
            return self._send(403, "forbidden", "text/plain")
        name, q = u.path[5:], {k: v[0] for k, v in parse_qs(u.query).items()}
        try:
            with LOCK:
                if method == "GET":
                    if name == "status":
                        r = api_status()
                    elif name == "log":
                        r = api_log()
                    elif name == "diff":
                        r = api_diff(q.get("path", ""), q.get("staged") == "1")
                    elif name == "show":
                        r = api_show(q.get("hash", ""))
                    else:
                        return self._send(404, "{}")
                else:
                    n = int(self.headers.get("Content-Length") or 0)
                    r = api_post(name, json.loads(self.rfile.read(n) or b"{}"))
            self._send(200, json.dumps(r))
        except Exception as e:  # shown to the user in the UI
            self._send(400, json.dumps({"error": str(e)}))

    def do_GET(self):
        self._handle("GET")

    def do_POST(self):
        self._handl

#!/usr/bin/env python3
"""Simple local network port scanner.

Usage:
    python3 port_scanner.py                  # scan your own /24 network, common ports
    python3 port_scanner.py --ports 1-1024   # scan a port range
    python3 port_scanner.py --network 192.168.1.0/24
    python3 port_scanner.py --host 192.168.1.10

Only private (home/office) addresses are allowed, so it can't be pointed
at machines on the internet.
"""

import argparse
import ipaddress
import socket
from concurrent.futures import ThreadPoolExecutor

COMMON_PORTS = [
    21, 22, 23, 25, 53, 80, 110, 111, 135, 139, 143, 443, 445, 465, 515,
    548, 587, 631, 993, 995, 1723, 1883, 3306, 3389, 5000, 5353, 5432,
    5900, 7000, 8000, 8080, 8443, 8888, 9100, 32400,
]


def local_network():
    """Guess this computer's /24 network."""
    s = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
    try:
        s.connect(("10.255.255.255", 1))  # no traffic is actually sent
        ip = s.getsockname()[0]
    except OSError:
        ip = "127.0.0.1"
    finally:
        s.close()
    return ipaddress.ip_network(f"{ip}/24", strict=False)


def parse_ports(text):
    ports = set()
    for part in text.split(","):
        if "-" in part:
            a, b = part.split("-")
            ports.update(range(int(a), int(b) + 1))
        else:
            ports.add(int(part))
    return sorted(p for p in ports if 0 < p < 65536)


def check(host, port, timeout):
    try:
        with socket.create_connection((host, port), timeout=timeout):
            return port
    except OSError:
        return None


def scan_host(host, ports, timeout):
    with ThreadPoolExecutor(max_workers=100) as pool:
        results = pool.map(lambda p: check(host, p, timeout), ports)
    return [p for p in results if p]


def service_name(port):
    try:
        return socket.getservbyport(port)
    except OSError:
        return "unknown"


def main():
    parser = argparse.ArgumentParser(description="Local network port scanner")
    parser.add_argument("--network", help="e.g. 192.168.1.0/24 (default: auto-detect)")
    parser.add_argument("--host", help="scan a single machine instead")
    parser.add_argument("--ports", help="e.g. 22,80,443 or 1-1024 (default: common ports)")
    parser.add_argument("--timeout", type=float, default=0.5, help="seconds per connection")
    args = parser.parse_args()

    if args.host:
        hosts = [ipaddress.ip_address(args.host)]
    else:
        net = ipaddress.ip_network(args.network, strict=False) if args.network else local_network()
        hosts = list(net.hosts())

    if not all(h.is_private for h in hosts):
        raise SystemExit("Refusing to scan non-private addresses. This tool is for your own network.")
    if len(hosts) > 1024:
        raise SystemExit("Network too large. Use a /22 or smaller (at most 1024 machines).")

    ports = parse_ports(args.ports) if args.ports else COMMON_PORTS
    print(f"Scanning {len(hosts)} address(es) on {len(ports)} port(s)... this may take a minute.\n")

    found = 0
    try:
        for host in hosts:
            open_ports = scan_host(str(host), ports, args.timeout)
            if open_ports:
                found += 1
                try:
                    name = socket.gethostbyaddr(str(host))[0]
                except OSError:
                    name = ""
                print(f"{host}  {name}")
                for p in open_ports:
                    print(f"    {p:<6} open   {service_name(p)}")
    except KeyboardInterrupt:
        print("\nStopped.")

    print(f"\nDone. {found} machine(s) with open ports.")


if __name__ == "__main__":
    main()

