"""Spreadsheet model and formula engine (no GUI dependencies)."""
import math
import re
import statistics


class FormulaError(Exception):
    def __init__(self, code):
        super().__init__(code)
        self.code = code


def col_name(i):
    s = ''
    i += 1
    while i:
        i, rem = divmod(i - 1, 26)
        s = chr(65 + rem) + s
    return s


def col_index(s):
    n = 0
    for ch in s.upper():
        n = n * 26 + ord(ch) - 64
    return n - 1


def cell_name(r, c):
    return f'{col_name(c)}{r + 1}'


NUMBER_RE = re.compile(r'^[-+]?(\d+\.?\d*|\.\d+)([eE][-+]?\d+)?$')
REF_RE = re.compile(r'\$?([A-Za-z]{1,3})\$?(\d+)$')
TOKEN_RE = re.compile(r'''\s*(?:
    (?P<num>\d+\.?\d*(?:[eE][+-]?\d+)?|\.\d+(?:[eE][+-]?\d+)?)|
    (?P<str>"(?:[^"]|"")*")|
    (?P<func>[A-Za-z_][A-Za-z0-9_.]*(?=\s*\())|
    (?P<ref>\$?[A-Za-z]{1,3}\$?\d+(?![A-Za-z0-9_]))|
    (?P<name>[A-Za-z_][A-Za-z0-9_.]*)|
    (?P<op><=|>=|<>|[-+*/^&=<>(),:%])
)''', re.X)


def tokenize(text):
    toks, pos = [], 0
    while pos < len(text):
        if not text[pos:].strip():
            break
        m = TOKEN_RE.match(text, pos)
        if not m:
            raise FormulaError('#ERR!')
        toks.append((m.lastgroup, m.group(m.lastgroup)))
        pos = m.end()
    return toks


def parse_ref(text):
    m = REF_RE.match(text)
    r, c = int(m.group(2)) - 1, col_index(m.group(1))
    if r < 0:
        raise FormulaError('#REF!')
    return r, c


class Parser:
    """Recursive descent parser producing a tuple-based AST."""

    def __init__(self, text):
        self.toks = tokenize(text)
        self.i = 0

    def peek(self):
        return self.toks[self.i] if self.i < len(self.toks) else (None, None)

    def accept(self, *ops):
        kind, text = self.peek()
        if kind == 'op' and text in ops:
            self.i += 1
            return text
        return None

    def parse(self):
        node = self.comparison()
        if self.i < len(self.toks):
            raise FormulaError('#ERR!')
        return node

    def binary(self, sub, *ops):
        node = sub()
        while (op := self.accept(*ops)):
            node = ('bin', op, node, sub())
        return node

    def comparison(self):
        return self.binary(self.concat, '=', '<>', '<=', '>=', '<', '>')

    def concat(self):
        return self.binary(self.additive, '&')

    def additive(self):
        return self.binary(self.term, '+', '-')

    def term(self):
        return self.binary(self.power, '*', '/')

    def power(self):
        return self.binary(self.unary, '^')

    def unary(self):
        if (op := self.accept('-', '+')):
            return ('un', op, self.unary())
        node = self.primary()
        while self.accept('%'):
            node = ('pct', node)
        return node

    def primary(self):
        kind, text = self.peek()
        self.i += 1
        if kind == 'num':
            return ('num', float(text))
        if kind == 'str':
            return ('str', text[1:-1].replace('""', '"'))
        if kind == 'func':
            if not self.accept('('):
                raise FormulaError('#ERR!')
            args = []
            if not self.accept(')'):
                while True:
                    args.append(self.comparison())
                    if self.accept(')'):
                        break
                    if not self.accept(','):
                        raise FormulaError('#ERR!')
            return ('fn', text.upper(), args)
        if kind == 'ref':
            r, c = parse_ref(text)
            if self.accept(':'):
                k2, t2 = self.peek()
                if k2 != 'ref':
                    raise FormulaError('#ERR!')
                self.i += 1
                r2, c2 = parse_ref(t2)
                return ('range', min(r, r2), min(c, c2), max(r, r2), max(c, c2))
            return ('ref', r, c)
        if kind == 'name':
            if text.upper() in ('TRUE', 'FALSE'):
                return ('bool', text.upper() == 'TRUE')
            raise FormulaError('#NAME?')
        if kind == 'op' and text == '(':
            node = self.comparison()
            if not self.accept(')'):
                raise FormulaError('#ERR!')
            return node
        raise FormulaError('#ERR!')


# ---- value coercion -------------------------------------------------------

def fmt_number(v):
    if v != v or v in (math.inf, -math.inf):
        raise FormulaError('#NUM!')
    if v == int(v) and abs(v) < 1e15:
        return str(int(v))
    return format(v, '.10g')


def scalar(v):
    if isinstance(v, list):
        raise FormulaError('#VALUE!')
    return v


def to_num(v):
    v = scalar(v)
    if v is None or v == '':
        return 0.0
    if isinstance(v, bool):
        return float(v)
    if isinstance(v, (int, float)):
        return float(v)
    if NUMBER_RE.match(v.strip()):
        return float(v)
    raise FormulaError('#VALUE!')


def to_text(v):
    v = scalar(v)
    if v is None:
        return ''
    if isinstance(v, bool):
        return 'TRUE' if v else 'FALSE'
    if isinstance(v, (int, float)):
        return fmt_number(v)
    return v


def to_bool(v):
    v = scalar(v)
    if v is None:
        return False
    if isinstance(v, str):
        if v.upper() in ('TRUE', 'FALSE'):
            return v.upper() == 'TRUE'
        raise FormulaError('#VALUE!')
    return bool(v)


def compare_key(v, other):
    if v is None:
        v = '' if isinstance(other, str) else 0.0
    if isinstance(v, bool):
        return (2, v)
    if isinstance(v, str):
        return (1, v.lower())
    return (0, v)


def is_number(v):
    return isinstance(v, (int, float)) and not isinstance(v, bool)


# ---- functions ------------------------------------------------------------

def nums(sh, args):
    out = []
    for a in args:
        v = sh.ev(a)
        if isinstance(v, list):
            out.extend(x for x in v if is_number(x))
        else:
            out.append(to_num(v))
    return out


