#!/usr/bin/env python3
"""Sheet - a small, fast spreadsheet with formulas and CSV import/export.

Standard library only (tkinter). Cells are stored sparsely and the grid is a
virtual canvas that draws just the visible cells, so startup and memory stay low.
"""
import csv
import io
import math
import re
import sys
import tkinter as tk
from tkinter import font as tkfont

sys.setrecursionlimit(12000)

MAXR, MAXC = 100000, 702          # rows 1..100000, columns A..ZZ
COLW, ROWH, HDRW, HDRH = 90, 22, 50, 22
MAC = sys.platform == "darwin"
MOD = "Command" if MAC else "Control"
MODTXT = "Cmd" if MAC else "Ctrl"
CTRL_MASK = 0x4 | (0x8 if MAC else 0)

GRID, HDRBG, HDRSEL, SELBG, BLUE = "#d8d8d8", "#f0f0f0", "#d6e4f7", "#dbe8fb", "#1a73e8"

# ---------------------------------------------------------------- references

def col_name(c):
    s = ""
    c += 1
    while c:
        c, rem = divmod(c - 1, 26)
        s = chr(65 + rem) + s
    return s


def name_to_col(s):
    n = 0
    for ch in s.upper():
        n = n * 26 + ord(ch) - 64
    return n - 1


REF_SUB = re.compile(r'("(?:[^"]|"")*")|(?<![\w.])(\$?)([A-Za-z]{1,3})(\$?)(\d+)(?![\w(.])')


def shift_formula(raw, dr, dc):
    """Move relative references in a formula, as when copy/pasting."""
    if raw[:1] != "=" or (dr == 0 and dc == 0):
        return raw

    def sub(m):
        if m.group(1):
            return m.group(1)
        cabs, col, rabs, row = m.group(2), m.group(3), m.group(4), m.group(5)
        c, r = name_to_col(col), int(row) - 1
        if not cabs:
            c += dc
        if not rabs:
            r += dr
        if not (0 <= r < MAXR and 0 <= c < MAXC):
            return "#REF!"
        return f"{cabs}{col_name(c)}{rabs}{r + 1}"

    return REF_SUB.sub(sub, raw)

# ------------------------------------------------------------------- parsing

class FormulaError(Exception):
    def __init__(self, code):
        super().__init__(code)
        self.code = code


class Rng(list):
    """Non-empty values of a range."""


NUM_RE = re.compile(r"^\s*[-+]?(\d+\.?\d*|\.\d+)([eE][+-]?\d+)?\s*$")
TOKEN_RE = re.compile(
    r'\s*(?:(?P<num>\d+\.?\d*(?:[eE][+-]?\d+)?|\.\d+)'
    r'|(?P<str>"(?:[^"]|"")*")'
    r'|(?P<ref>\$?[A-Za-z]{1,3}\$?\d+)(?![\w(.])'
    r'|(?P<name>[A-Za-z_][A-Za-z0-9_.]*)'
    r'|(?P<op><=|>=|<>|[-+*/^&=<>(),:%]))')
REF_RE = re.compile(r"\$?([A-Za-z]+)\$?(\d+)")


def tokenize(s):
    out, pos = [], 0
    while pos < len(s):
        m = TOKEN_RE.match(s, pos)
        if not m:
            if s[pos:].strip() == "":
                break
            raise FormulaError("#ERROR!")
        out.append((m.lastgroup, m.group(m.lastgroup)))
        pos = m.end()
    return out


def parse_ref(text):
    m = REF_RE.match(text)
    c, r = name_to_col(m.group(1)), int(m.group(2)) - 1
    if not (0 <= r < MAXR and 0 <= c < MAXC):
        raise FormulaError("#REF!")
    return r, c


def to_number(text):
    f = float(text)
    return int(f) if f.is_integer() and abs(f) < 1e15 else f


class Parser:
    def __init__(self, toks):
        self.t, self.i = toks, 0

    def peek(self):
        return self.t[self.i] if self.i < len(self.t) else ("end", "")

    def next(self):
        tok = self.peek()
        self.i += 1
        return tok

    def accept(self, *ops):
        k, v = self.peek()
        if k == "op" and v in ops:
            self.i += 1
            return v

    def parse(self):
        n = self.cmp()
        if self.peek()[0] != "end":
            raise FormulaError("#ERROR!")
        return n

    def cmp(self):
        n = self.cat()
        while True:
            op = self.accept("=", "<>", "<=", ">=", "<", ">")
            if not op:
                return n
            n = ("bin", op, n, self.cat())

    def cat(self):
        n = self.add()
        while self.accept("&"):
            n = ("bin", "&", n, self.add())
        return n

    def add(self):
        n = self.mul()
        while True:
            op = self.accept("+", "-")
            if not op:
                return n
            n = ("bin", op, n, self.mul())

    def mul(self):
        n = self.pow()
        while True:
            op = self.accept("*", "/")
            if not op:
                return n
            n = ("bin", op, n, self.pow())

    def pow(self):
        n = self.unary()
        while self.accept("^"):
            n = ("bin", "^", n, self.unary())
        return n

    def unary(self):
        if self.accept("-"):
            return ("neg", self.unary())
        if self.accept("+"):
            return self.unary()
        n = self.primary()
        while self.accept("%"):
            n = ("pct", n)
        return n

    def primary(self):
        kind, text = self.next()
        if kind == "num":
            return ("lit", to_number(text))
        if kind == "str":
            return ("lit", text[1:-1].replace('""', '"'))
        if kind == "ref":
            r, c = parse_ref(text)
            if self.accept(":"):
                k2, t2 = self.next()
                if k2 != "ref":
                    raise FormulaError("#ERROR!")
                r2, c2 = parse_ref(t2)
                return ("range", min(r, r2), min(c, c2), max(r, r2), max(c, c2))
            return ("ref", r, c)
        if kind == "name":
            if self.accept("("):
                args = []
                if not self.accept(")"):
                    while True:
                        args.append(self.cmp())
                        if self.accept(")"):
                            break
                        if not self.accept(","):
                            raise FormulaError("#ERROR!")
                return ("call", text.upper(), args)
            if text.upper() in ("TRUE", "FALSE"):
                return ("lit", text.upper() == "TRUE")
            raise FormulaError("#NAME?")
        if kind == "op" and text == "(":
            n = self.cmp()
            if not self.accept(")"):
                raise FormulaError("#ERROR!")

