"""SQLite storage for the finance tracker. Amounts are integer cents; expenses are negative."""
import os
import sqlite3
from datetime import date
from decimal import Decimal, InvalidOperation

DB_PATH = os.path.join(os.path.expanduser("~"), ".finance-tracker", "data.db")

SCHEMA = """
CREATE TABLE IF NOT EXISTS accounts (
    id INTEGER PRIMARY KEY,
    name TEXT NOT NULL UNIQUE,
    opening INTEGER NOT NULL DEFAULT 0
);
CREATE TABLE IF NOT EXISTS categories (
    id INTEGER PRIMARY KEY,
    name TEXT NOT NULL UNIQUE,
    kind TEXT NOT NULL CHECK (kind IN ('income', 'expense'))
);
CREATE TABLE IF NOT EXISTS transactions (
    id INTEGER PRIMARY KEY,
    account_id INTEGER NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,
    category_id INTEGER REFERENCES categories(id) ON DELETE SET NULL,
    date TEXT NOT NULL,
    amount INTEGER NOT NULL,
    note TEXT NOT NULL DEFAULT ''
);
CREATE INDEX IF NOT EXISTS idx_tx_date ON transactions(date);
"""

DEFAULT_CATEGORIES = [
    ("Salary", "income"), ("Other income", "income"),
    ("Groceries", "expense"), ("Rent", "expense"), ("Transport", "expense"),
    ("Utilities", "expense"), ("Dining out", "expense"), ("Health", "expense"),
    ("Entertainment", "expense"), ("Shopping", "expense"),
]


def connect(path=DB_PATH):
    if path != ":memory:":
        os.makedirs(os.path.dirname(path), exist_ok=True)
    conn = sqlite3.connect(path)
    conn.execute("PRAGMA foreign_keys = ON")
    conn.execute("PRAGMA journal_mode = WAL")
    conn.executescript(SCHEMA)
    if not conn.execute("SELECT 1 FROM categories LIMIT 1").fetchone():
        conn.executemany("INSERT INTO categories(name, kind) VALUES (?, ?)", DEFAULT_CATEGORIES)
    if not conn.execute("SELECT 1 FROM accounts LIMIT 1").fetchone():
        conn.execute("INSERT INTO accounts(name, opening) VALUES ('Cash', 0)")
    conn.commit()
    return conn


def parse_amount(text, allow_negative=False):
    """Parse a user-entered decimal into cents. Raises ValueError on bad input."""
    try:
        value = Decimal(text.replace(",", "").strip())
    except InvalidOperation:
        raise ValueError("Enter a valid amount, e.g. 12.50")
    if not value.is_finite():
        raise ValueError("Enter a valid amount, e.g. 12.50")
    if value < 0 and not allow_negative:
        raise ValueError("Amount must be positive")
    return int((value * 100).to_integral_value())


def fmt(cents):
    return f"{cents / 100:,.2f}"


def parse_date(text):
    try:
        return date.fromisoformat(text.strip()).isoformat()
    except ValueError:
        raise ValueError("Date must be YYYY-MM-DD")


def balances(conn):
    return conn.execute(
        "SELECT a.id, a.name, a.opening + COALESCE(SUM(t.amount), 0) "
        "FROM accounts a LEFT JOIN transactions t ON t.account_id = a.id "
        "GROUP BY a.id ORDER BY a.name"
    ).fetchall()


def last_months(n, today=None):
    """Return the last n months as 'YYYY-MM', oldest first."""
    today = today or date.today()
    y, m = today.year, today.month
    out = []
    for _ in range(n):
        out.append(f"{y:04d}-{m:02d}")
        m -= 1
        if m == 0:
            y, m = y - 1, 12
    return out[::-1]


def monthly_totals(conn, n=12):
    """Return [(month, income, expense)] for the last n months; expense is positive."""
    months = last_months(n)
    rows = conn.execute(
        "SELECT substr(date, 1, 7) m, "
        "SUM(CASE WHEN amount > 0 THEN amount ELSE 0 END), "
        "SUM(CASE WHEN amount < 0 THEN -amount ELSE 0 END) "
        "FROM transactions WHERE m >= ? GROUP BY m",
        (months[0],),
    ).fetchall()
    by_month = {m: (i, e) for m, i, e in rows}
    return [(m, *by_month.get(m, (0, 0))) for m in months]


def expense_breakdown(conn, month):
    return conn.execute(
        "SELECT COALESCE(c.name, 'Uncategorized'), SUM(-t.amount) s "
        "FROM transactions t LEFT JOIN categories c ON c.id = t.category_id "
        "WHERE substr(t.date, 1, 7) = ? AND t.amount < 0 GROUP BY 1 ORDER BY s DESC",
        (month,),
    ).fetchall()

