"""Shop Inventory Manager: a cross-platform desktop app (Tkinter + SQLite).

Barcode lookup: USB/Bluetooth scanners act as keyboards, so click the scan box
and scan (the scanner sends Enter). If the barcode is unknown, the app can
optionally look up the product name online via Open Food Facts.
"""
import csv
import json
import os
