APP_NAME = "ShopInventory"


def data_dir():
    if sys.platform == "win32":
        base = os.environ.get("APPDATA", os.path.expanduser("~"))
    elif sys.platform == "darwin":
        base = os.path.expanduser("~/Library/Application Support")
    else:
        base = os.environ.get("XDG_DATA_HOME", os.path.expanduser("~/.local/share"))
    path = os.path.join(base, APP_NAME)
    os.makedirs(path, exist_ok=True)
    return path


SCHEMA = """
CREATE TABLE IF NOT EXISTS products (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    barcode TEXT UNIQUE NOT NULL,
    name TEXT NOT NULL,
    category TEXT DEFAULT '',
    quantity INTEGER NOT NULL DEFAULT 0,
    min_stock INTEGER NOT NULL DEFAULT 0,
    cost REAL NOT NULL DEFAULT 0,
    price REAL NOT NULL DEFAULT 0,
    notes TEXT DEFAULT ''
);
"""

FIELDS = ["barcode", "name", "category", "quantity", "min_stock", "cost", "price", "notes"]


class DB:
    def __init__(self, path):
        self.conn = sqlite3.connect(path)
        self.conn.row_factory = sqlite3.Row
        self.conn.execute(SCHEMA)
        self.conn.commit()

    def search(self, text=""):
        like = f"%{text}%"
        return self.conn.execute(
            "SELECT * FROM products WHERE barcode LIKE ? OR name LIKE ? OR category LIKE ? "
            "ORDER BY name COLLATE NOCASE",
            (like, like, like),
        ).fetchall()

    def by_barcode(self, code):
        return self.conn.execute("SELECT * FROM products WHERE barcode=?", (code,)).fetchone()

    def get(self, pid):
        return self.conn.execute("SELECT * FROM products WHERE id=?", (pid,)).fetchone()

    def save(self, data, pid=None):
        with self.conn:
            if pid is None:
                self.conn.execute(
                    f"INSERT INTO products ({','.join(FIELDS)}) VALUES ({','.join('?' * len(FIELDS))})",
                    [data[f] for f in FIELDS],
                )
            else:
                self.conn.execute(
                    f"UPDATE products SET {','.join(f + '=?' for f in FIELDS)} WHERE id=?",
                    [data[f] for f in FIELDS] + [pid],
                )

    def adjust(self, pid, delta):
        with self.conn:
            self.conn.execute(
                "UPDATE products SET quantity=MAX(0, quantity+?) WHERE id=?", (delta, pid)
            )

    def delete(self, pid):
        with self.conn:
            self.conn.execute("DELETE FROM products WHERE id=?", (pid,))


def online_lookup(barcode):
    """Return a product name from Open Food Facts, or None. Never raises."""
    url = f"https://world.openfoodfacts.org/api/v2/product/{barcode}.json?fields=product_name,brands,categories"
    try:
        req = urllib.request.Request(url, headers={"User-Agent": f"{APP_NAME}/1.0"})
        with urllib.request.urlopen(req, timeout=6) as r:
            info = json.load(r)
        if info.get("status") != 1:
            return None
        p = info["product"]
        name = p.get("product_name", "").strip()
        brand = p.get("brands", "").split(",")[0].strip()
        if not name:
            return None
        return {
            "name": f"{brand} {name}".strip() if brand and brand.lower() not in name.lower() else name,
            "category": p.get("categories", "").split(",")[0].strip(),
        }
    except Exception:
        return None


