"""Minimal vCard (2.1/3.0/4.0) reader. Multi-value fields are newline-joined."""
import re

_FIELDS = {"EMAIL": "email", "TEL": "phone", "ORG": "org", "NOTE": "notes"}


def _unescape(v):
    return re.sub(r"\\([nN,;\\])", lambda m: "\n" if m.group(1) in "nN" else m.group(1), v)


def parse(text):
    """Return a list of dicts with keys name, email, phone, org, notes."""
    text = text.lstrip("﻿")
    text = re.sub(r"\r?\n[ \t]", "", text)  # unfold continuation lines
    cards, cur = [], None
    for line in text.splitlines():
        line = line.strip()
        up = line.upper()
        if up == "BEGIN:VCARD":
            cur = {"fn": "", "n": "", **{f: [] for f in _FIELDS.values()}}
        elif up == "END:VCARD":
            if cur is not None:
                cards.append(_finish(cur))
            cur = None
        elif cur is not None and ":" in line:
            head, value = line.split(":", 1)
            prop = head.split(";")[0].split(".")[-1].upper()  # drop group prefix
            value = _unescape(value.strip())
            if prop == "FN":
                cur["fn"] = value
            elif prop == "N":
                last, first, *_ = (value.replace("\\", "").split(";") + ["", ""])
                cur["n"] = f"{first} {last}".strip()
            elif prop in _FIELDS and value:
                cur[_FIELDS[prop]].append(value.replace(";", " ").strip() if prop == "ORG" else value)
    return [c for c in cards if c["name"] or c["email"] or c["phone"]]


def _finish(c):
    return {
        "name": c["fn"] or c["n"] or (c["email"][0] if c["email"] else ""),
        "email": "\n".join(c["email"]),
        "phone": "\n".join(c["phone"]),
        "org": " / ".join(c["org"]),
        "notes": "\n".join(c["notes"]),
    }

import sqlite3
from pathlib import Path

FIELDS = ("name", "email", "phone", "org", "notes")

SCHEMA = """
CREATE TABLE IF NOT EXISTS contacts(
  id INTEGER PRIMARY KEY, name TEXT NOT NULL DEFAULT '', email TEXT NOT NULL DEFAULT '',
  phone TEXT NOT NULL DEFAULT '', org TEXT NOT NULL DEFAULT '', notes TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS groups(id INTEGER PRIMARY KEY, name TEXT NOT NULL UNIQUE COLLATE NOCASE);
CREATE TABLE IF NOT EXISTS contact_groups(
  contact_id INTEGER NOT NULL REFERENCES contacts(id) ON DELETE CASCADE,
  group_id INTEGER NOT NULL REFERENCES groups(id) ON DELETE CASCADE,
  PRIMARY KEY(contact_id, group_id));
CREATE INDEX IF NOT EXISTS idx_cg_group ON contact_groups(group_id);
CREATE INDEX IF NOT EXISTS idx_contacts_name ON contacts(name COLLATE NOCASE);
"""


def default_path():
    d = Path.home() / ".contactmgr"
    d.mkdir(exist_ok=True)
    return d / "contacts.db"


class DB:
    def __init__(self, path=None):
        self.c = sqlite3.connect(path or default_path())
        self.c.row_factory = sqlite3.Row
        self.c.execute("PRAGMA foreign_keys=ON")
        self.c.execute("PRAGMA journal_mode=WAL")
        self.c.executescript(SCHEMA)

    # contacts
    def list_contacts(self, group_id=None, query=""):
        sql, args = "SELECT c.* FROM contacts c", []
        where = []
        if group_id is not None:
            sql += " JOIN contact_groups g ON g.contact_id=c.id"
            where.append("g.group_id=?")
            args.append(group_id)
        for term in query.split():
            like = f"%{term}%"
            where.append("(c.name LIKE ? OR c.email LIKE ? OR c.phone LIKE ? OR c.org LIKE ?)")
            args += [like] * 4
        if where:
            sql += " WHERE " + " AND ".join(where)
        return self.c.execute(sql + " ORDER BY c.name COLLATE NOCASE", args).fetchall()

    def get_contact(self, cid):
        return self.c.execute("SELECT * FROM contacts WHERE id=?", (cid,)).fetchone()

    def save_contact(self, cid, data, group_ids):
        with self.c:
            if cid is None:
                cur = self.c.execute(
                    f"INSERT INTO contacts({','.join(FIELDS)}) VALUES({','.join('?' * len(FIELDS))})",
                    [data[f] for f in FIELDS])
                cid = cur.lastrowid
            else:
                self.c.execute(
                    f"UPDATE contacts SET {','.join(f + '=?' for f in FIELDS)} WHERE id=?",
                    [data[f] for f in FIELDS] + [cid])
            self.c.execute("DELETE FROM contact_groups WHERE contact_id=?", (cid,))
            self.c.executemany("INSERT INTO contact_groups VALUES(?,?)", [(cid, g) for g in group_ids])
        return cid

    def delete_contact(self, cid):
        with self.c:
            self.c.execute("DELETE FROM contacts WHERE id=?", (cid,))

    def contact_group_ids(self, cid):
        return {r[0] for r in self.c.execute(
            "SELECT group_id FROM contact_groups WHERE contact_id=?", (cid,))}

    # groups
    def list_groups(self):
        return self.c.execute(
            "SELECT g.id, g.name, COUNT(cg.contact_id) n FROM groups g "
            "LEFT JOIN contact_groups cg ON cg.group_id=g.id GROUP BY g.id "
            "ORDER BY g.name COLLATE NOCASE").fetchall()

    def add_group(self, name):
        with self.c:
            row = self.c.execute("SELECT id FROM groups WHERE name=?", (name,)).fetchone()
            if row:
                return row[0]
            return self.c.execute("INSERT INTO groups(name) VALUES(?)", (name,)).lastrowid

    def rename_group(self, gid, name):
        with self.c:
            self.c.execute("UPDATE groups SET name=? WHERE id=?", (name, gid))

    def delete_group(self, gid):
        with self.c:
            self.c.execute("DELETE FROM groups WHERE id=?", (gid,))

    # import
    def import_cards(self, cards, group_id=None):
        """Insert cards, skipping ones that duplicate an existing name+email.
        Returns (added, skipped). Optionally adds all (incl. skipped) to group_id."""
        added = skipped = 0
        with self.c:
            for card in cards:
                row = self.c.execute(
                    "SELECT id FROM contacts WHERE name=? AND email=?",
                    (card["name"], card["email"])).fetchone()
                if row:
                    cid, skipped = row[0], skipped + 1
                else:
                    cid = self.c.execute(
                        f"INSERT INTO contacts({','.join(FIELDS)}) VALUES({','.join('?' * len(FIELDS))})",
                        [card[f] for f in FIELDS]).lastrowid
                    added += 1
                if group_id is not None:
                    self.c.execute("INSERT OR IGNORE INTO contact_groups VALUES(?,?)", (cid, group_id))
        return added, skipped

