"""PDF Tool: merge, split and reorder PDF pages. Runs on Windows, macOS and Linux."""
import os
import tkinter as tk
from tkinter import filedialog, messagebox, simpledialog, ttk

from pypdf import PdfReader, PdfWriter


class Page:
    def __init__(self, reader, path, index):
        self.reader = reader
        self.path = path
        self.index = index
        self.rotation = 0  # extra clockwise rotation in degrees


class App(tk.Tk):
    def __init__(self):
        super().__init__()
        self.title("PDF Tool")
        self.geometry("720x520")
        self.pages = []
        self.readers = {}
        self._build()

    # ---------- UI ----------
    def _build(self):
        bar = ttk.Frame(self, padding=6)
        bar.pack(fill="x")
        for text, cmd in [
            ("Add PDFs…", self.add_files),
            ("Remove", self.remove),
            ("Move Up", lambda: self.move(-1)),
            ("Move Down", lambda: self.move(1)),
            ("Rotate 90°", self.rotate),
            ("Reverse", self.reverse),
            ("Clear", self.clear),
        ]:
            ttk.Button(bar, text=text, command=cmd).pack(side="left", padx=2)

        cols = ("pos", "file", "page", "rot")
        self.tree = ttk.Treeview(self, columns=cols, show="headings", selectmode="extended")
        for c, t, w in [("pos", "#", 50), ("file", "File", 420), ("page", "Page", 70), ("rot", "Rotation", 80)]:
            self.tree.heading(c, text=t)
            self.tree.column(c, width=w, anchor="w")
        self.tree.pack(fill="both", expand=True, padx=6)
        self.tree.bind("<ButtonPress-1>", self._drag_start)
        self.tree.bind("<B1-Motion>", self._drag_move)

        bottom = ttk.Frame(self, padding=6)
        bottom.pack(fill="x")
        ttk.Button(bottom, text="Export All (Merge)…", command=self.export_all).pack(side="left", padx=2)
        ttk.Button(bottom, text="Export Selected…", command=self.export_selected).pack(side="left", padx=2)
        ttk.Button(bottom, text="Split: One File per Page…", command=self.split_each).pack(side="left", padx=2)
        ttk.Button(bottom, text="Split: By Ranges…", command=self.split_ranges).pack(side="left", padx=2)
        self.status = ttk.Label(self, text="Add PDFs, reorder with buttons or drag, then export.", padding=6)
        self.status.pack(fill="x")

    def refresh(self, select=()):
        self.tree.delete(*self.tree.get_children())
        for i, p in enumerate(self.pages):
            self.tree.insert("", "end", iid=str(i),
                             values=(i + 1, os.path.basename(p.path), p.index + 1, f"{p.rotation}°"))
        self.tree.selection_set([str(i) for i in select])
        self.status.config(text=f"{len(self.pages)} page(s) loaded")

    def selected(self):
        return sorted(int(i) for i in self.tree.selection())

    # ---------- editing ----------
    def add_files(self):
        paths = filedialog.askopenfilenames(title="Select PDFs", filetypes=[("PDF files", "*.pdf")])
        for path in paths:
            try:
                reader = PdfReader(path)
                if reader.is_encrypted and not reader.decrypt(""):
                    pw = simpledialog.askstring("Password", f"Password for {os.path.basename(path)}:", show="*")
                    if not pw or not reader.decrypt(pw):
                        raise ValueError("incorrect or missing password")
                n = len(reader.pages)
            except Exception as e:
                messagebox.showerror("Cannot open", f"{path}\n\n{e}")
                continue
            self.pages.extend(Page(reader, path, i) for i in range(n))
        self.refresh()

    def remove(self):
        sel = set(self.selected())
        self.pages = [p for i, p in enumerate(self.pages) if i not in sel]
        self.refresh()

    def clear(self):
        self.pages = []
        self.refresh()

    def reverse(self):
        self.pages.reverse()
        self.refresh()

    def rotate(self):
        sel = self.selected()
        for i in sel:
            self.pages[i].rotation = (self.pages[i].rotation + 90) % 360
        self.refresh(sel)

    def move(self, delta):
        sel = self.selected()
        if not sel:
            return
        order = sel if delta > 0 else sel[::-1]
        if delta > 0:
            order = order[::-1]
        new_sel = set(sel)
        for i in (sel if delta < 0 else sel[::-1]):
            j = i + delta
            if 0 <= j < len(self.pages) and j not in new_sel:
                self.pages[i], self.pages[j] = self.pages[j], self.pages[i]
                new_sel.discard(i)
                new_sel.add(j)
        self.refresh(new_sel)

    def _drag_start(self, e):
        self._drag_item = self.tree.identify_row(e.y)

    def _drag_move(self, e):
        src = getattr(self, "_drag_item", "")
        dst = self.tree.identify_row(e.y)
        if not src or not dst or src == dst:
            return
        s, d = int(src), int(dst)
        self.pages.insert(d, self.pages.pop(s))
        self._drag_item = dst
        self.refresh([d])

    # ---------- export ----------
    def _write(self, pages, path):
        w = PdfWriter()
        for p in pages:
            page = p.reader.pages[p.index]
            w.add_page(page)
            if p.rotation:
                w.pages[-1].rotate(p.rotation)
        with open(path, "wb") as f:
            w.write(f)

    def _save_dialog(self):
        return filedialog.asksaveasfilename(defaultextension=".pdf", filetypes=[("PDF files", "*.pdf")])

    def _guard(self, pages, fn):
        if not pages:
            messagebox.showinfo("Nothing to export", "No pages to export.")
            return
        try:
            fn()
        except Exception as e:
            messagebox.showerror("Export failed", str(e))

    def export_all(self):
        self._guard(self.pages, self._export(self.pages))

    def export_selected(self):
        pages = [self.pages[i] for i in self.selected()]
        self._guard(pages, sel

