#!/usr/bin/env python3
"""Recipe manager: recipes, ingredient scaling, shopping list.

Standard library only (tkinter + sqlite3) so it starts instantly and stays small.
Data lives in ~/.recipe-manager/recipes.db
"""
import os
import re
import sqlite3
import tkinter as tk
from fractions import Fraction
from tkinter import messagebox, ttk

DB_PATH = os.path.join(os.path.expanduser("~"), ".recipe-manager", "recipes.db")
UNITS = {
    "g", "kg", "mg", "ml", "l", "dl", "cl", "tsp", "tbsp", "cup", "cups", "oz", "lb", "lbs",
    "pinch", "dash", "clove", "cloves", "can", "cans", "slice", "slices", "piece", "pieces",
    "pkg", "bunch",
}


# ---------- quantity helpers ----------

def parse_qty(text):
    """'2', '1.5', '1/2', '1 1/2' -> float. Returns None if not a number."""
    try:
        return float(sum(Fraction(p) for p in text.split()))
    except (ValueError, ZeroDivisionError):
        return None


def fmt_qty(q):
    if q is None or q == 0:
        return ""
    whole, frac = divmod(q, 1)
    whole = int(whole)
    f = Fraction(frac).limit_denominator(8)
    if abs(float(f) - frac) > 0.02:  # not a friendly fraction: show decimal
        return f"{q:.2f}".rstrip("0").rstrip(".")
    if f == 1:
        whole, f = whole + 1, Fraction(0)
    if f == 0:
        return str(whole)
    return f"{whole} {f}" if whole else str(f)


def parse_line(line):
    """'1 1/2 cups flour' -> (1.5, 'cups', 'flour'). Qty and unit are optional."""
    tokens = line.split()
    qty, i = None, 0
    # take up to two leading tokens as the quantity ("1 1/2")
    for n in (2, 1):
        if len(tokens) >= n:
            q = parse_qty(" ".join(tokens[:n]))
            if q is not None:
                qty, i = q, n
                break
    unit = ""
    if i and len(tokens) > i + 1 and tokens[i].lower().rstrip(".") in UNITS:
        unit = tokens[i]
        i += 1
    return qty, unit, " ".join(tokens[i:])


def line_text(qty, unit, name):
    return " ".join(p for p in (fmt_qty(qty), unit, name) if p)


# ---------- storage ----------

class Store:
    def __init__(self, path=DB_PATH):
        os.makedirs(os.path.dirname(path), exist_ok=True)
        self.db = sqlite3.connect(path)
        self.db.execute("PRAGMA foreign_keys = ON")
        self.db.executescript("""
            CREATE TABLE IF NOT EXISTS recipes(
                id INTEGER PRIMARY KEY, name TEXT NOT NULL,
                servings INTEGER NOT NULL DEFAULT 4, instructions TEXT NOT NULL DEFAULT '');
            CREATE TABLE IF NOT EXISTS ingredients(
                id INTEGER PRIMARY KEY, recipe_id INTEGER NOT NULL
                    REFERENCES recipes(id) ON DELETE CASCADE,
                pos INTEGER NOT NULL, qty REAL, unit TEXT NOT NULL DEFAULT '', name TEXT NOT NULL);
            CREATE TABLE IF NOT EXISTS shopping(
                id INTEGER PRIMARY KEY, name TEXT NOT NULL, unit TEXT NOT NULL DEFAULT '',
                qty REAL, checked INTEGER NOT NULL DEFAULT 0);
        """)

    def recipes(self, search=""):
        return self.db.execute(
            "SELECT id, name FROM recipes WHERE name LIKE ? ORDER BY name COLLATE NOCASE",
            (f"%{search}%",)).fetchall()

    def recipe(self, rid):
        return self.db.execute(
            "SELECT name, servings, instructions FROM recipes WHERE id=?", (rid,)).fetchone()

    def ingredients(self, rid):
        return self.db.execute(
            "SELECT qty, unit, name FROM ingredients WHERE recipe_id=? ORDER BY pos", (rid,)).fetchall()

    def save_recipe(self, rid, name, servings, instructions, ingredients):
        with self.db:
            if rid is None:
                rid = self.db.execute(
                    "INSERT INTO recipes(name, servings, instructions) VALUES(?,?,?)",
                    (name, servings, instructions)).lastrowid
            else:
                self.db.execute("UPDATE recipes SET name=?, servings=?, instructions=? WHERE id=?",
                                (name, servings, instructions, rid))
                self.db.execute("DELETE FROM ingredients WHERE recipe_id=?", (rid,))
            self.db.executemany(
                "INSERT INTO ingredients(recipe_id, pos, qty, unit, name) VALUES(?,?,?,?,?)",
                [(rid, i, q, u, n) for i, (q, u, n) in enumerate(ingredients)])
        return rid

    def delete_recipe(self, rid):
        with self.db:
            self.db.execute("DELETE FROM recipes WHERE id=?", (rid,))

    def shopping(self):
        return self.db.execute(
            "SELECT id, name, unit, qty, checked FROM shopping ORDER BY checked, name COLLATE NOCASE"
        ).fetchall()

    def add_to_shopping(self, name, unit, qty):
        """Merge with an existing unchecked item of the same name and unit."""
        with self.db:
            row = self.db.execute(
                "SELECT id, qty FROM shopping WHERE lower(name)=lower(?) AND lower(unit)=lower(?) "
                "AND checked=0", (name, unit)).fetchone()
            if row and (row[1] is not None) == (qty is not None):
                self.db.execute("UPDATE shopping SET qty=? WHERE id=?",
                                (None if qty is None else row[1] + qty, row[0]))
            elif not row:
                self.db.execute("INSERT INTO shopping(name, unit, qty) VALUES(?,?,?)",
                                (name, unit, qty))
            else:
                self.db.execute("INSERT INTO shopping(name, unit, qty) VALUES(?,?,?)",
                                (name, unit, qty))

    def toggle_shopping(self, sid):
        with self.db:
            self.db.execute("UPDATE shopping SET checked = 1 - checked WHERE id=?", (sid,))

    def delete_shopping(self, ids):
        with self.db:
            self.db.executemany("DELETE FROM shopping WHERE id=?", [(i,) for i in ids])

    def clear_shopping(self, checked_only):
        with self.db:
            self.db.execute("DELETE FROM shopping" + (" WHERE checked=1" if checked_only else ""))


