"""LAN Chat - a serverless chat for your local network.

Every copy of this program sends messages by UDP broadcast and listens for
messages from the others. No server, no accounts, no internet needed.
"""
import json
import socket
import threading
import time
import queue
import getpass

PORT = 50555
BROADCAST = "255.255.255.255"

incoming = queue.Queue()


def make_socket():
    s = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
    s.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
    if hasattr(socket, "SO_REUSEPORT"):
        s.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEPORT, 1)
    s.setsockopt(socket.SOL_SOCKET, socket.SO_BROADCAST, 1)
    s.bind(("", PORT))
    return s


def listen(sock):
    while True:
        try:
            data, addr = sock.recvfrom(4096)
            msg = json.loads(data.decode("utf-8"))
            incoming.put((msg.get("kind"), str(msg.get("name", "?"))[:30],
                          str(msg.get("text", ""))[:2000]))
        except (ValueError, UnicodeDecodeError):
            continue
        except OSError:
            return


def send(sock, kind, name, text=""):
    data = json.dumps({"kind": kind, "name": name, "text": text}).encode("utf-8")
    sock.sendto(data, (BROADCAST, PORT))


def run_gui(sock, name):
    import tkinter as tk
    from tkinter import scrolledtext

    root = tk.Tk()
    root.title(f"LAN Chat - {name}")
    root.geometry("520x420")

    log = scrolledtext.ScrolledText(root, state="disabled", wrap="word")
    log.pack(fill="both", expand=True, padx=6, pady=6)
    log.tag_config("note", foreground="gray")
    log.tag_config("name", font=("Helvetica", 12, "bold"))

    bottom = tk.Frame(root)
    bottom.pack(fill="x", padx=6, pady=(0, 6))
    entry = tk.Entry(bottom)
    entry.pack(side="left", fill="x", expand=True)
    entry.focus()

    def write(parts):
        log.config(state="normal")
        for text, tag in parts:
            log.insert("end", text, tag)
        log.see("end")
        log.config(state="disabled")

    def on_send(_event=None):
        text = entry.get().strip()
        if text:
            send(sock, "msg", name, text)
            entry.delete(0, "end")

    def poll():
        while not incoming.empty():
            kind, who, text = incoming.get()
            stamp = time.strftime("%H:%M ")
            if kind == "msg":
                write([(stamp, "note"), (who + ": ", "name"), (text + "\n", None)])
            elif kind == "join":
                write([(f"{stamp}{who} joined\n", "note")])
            elif kind == "leave":
                write([(f"{stamp}{who} left\n", "note")])
        root.after(100, poll)

    def on_close():
        send(sock, "leave", name)
        root.destroy()

    tk.Button(bottom, text="Send", command=on_send).pack(side="right", padx=(6, 0))
    entry.bind("<Return>", on_send)
    root.protocol("WM_DELETE_WINDOW", on_close)

    send(sock, "join", name)
    poll()
    root.mainloop()


def run_terminal(sock, name):
    print("Type a message and press Enter. Press Ctrl+C to quit.")

    def show():
        while True:
            kind, who, text = incoming.get()
            if kind == "msg":
                print(f"\r{who}: {text}")
            elif kind in ("join", "leave"):
                print(f"\r* {who} {'joined' if kind == 'join' else 'left'}")

    threading.Thread(target=show, daemon=True).start()
    send(sock, "join", name)
    try:
        while True:
            text = input().strip()
            if text:
                send(sock, "msg", name, text)
    except (KeyboardInterrupt, EOFError):
        send(sock, "leave", name)


def main():
    default = getpass.getuser()
    try:
        name = input(f"Your name [{default}]: ").strip() or default
    except EOFError:
        name = default
    name = name[:30]

    try:
        sock = make_socket()
    except OSError as e:
        print("Could not start networking:", e)
        return
    threading.Thread(target=listen, args=(sock,), daemon=True).start()

    try:
        import tkinter  # noqa: F401
        run_gui(sock, name)
    except ImportError:
        run_terminal(sock, name)


if __name__ == "__main__":
    main()

