"""Serverless LAN chat core: UDP-broadcast discovery + direct TCP messaging.

Every instance is both client and server. Peers announce themselves with a
UDP broadcast; messages are sent straight to each peer over TCP as
newline-delimited JSON. Standard library only.
"""
import json
import socket
import threading
import time
import uuid

DISCOVERY_PORT = 54545
ANNOUNCE_INTERVAL = 3.0
PEER_TIMEOUT = 10.0
MAX_LINE = 64 * 1024
EVERYONE = "*"


def local_ip():
    """Best-effort LAN address of this machine (no packets are actually sent)."""
    s = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
    try:
        s.connect(("10.255.255.255", 1))
        return s.getsockname()[0]
    except OSError:
        return "127.0.0.1"
    finally:
        s.close()


class Node:
    def __init__(self, name, on_message, on_peers, discovery_port=DISCOVERY_PORT):
        self.id = uuid.uuid4().hex
        self.name = name
        self.on_message = on_message  # (sender_name, sender_id, target, text, ts)
        self.on_peers = on_peers      # ()
        self.discovery_port = discovery_port
        self.peers = {}               # id -> {"name", "ip", "port", "seen"}
        self.lock = threading.Lock()
        self.running = False

        self.tcp = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        self.tcp.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
        self.tcp.bind(("0.0.0.0", 0))
        self.tcp.listen(16)
        self.tcp_port = self.tcp.getsockname()[1]

    # -- lifecycle ---------------------------------------------------------
    def start(self):
        self.running = True
        for target in (self._tcp_loop, self._listen_loop, self._announce_loop, self._reaper_loop):
            threading.Thread(target=target, daemon=True).start()

    def stop(self):
        if self.running:
            self._announce(bye=True)
        self.running = False
        try:
            self.tcp.close()
        except OSError:
            pass

    def set_name(self, name):
        self.name = name
        self._announce()

    # -- discovery ---------------------------------------------------------
    def _announce(self, bye=False):
        msg = json.dumps({"app": "lanchat", "id": self.id, "name": self.name,
                          "port": self.tcp_port, "bye": bye}).encode()
        ip = local_ip()
        targets = ["255.255.255.255", "127.0.0.1"]
        if ip.count(".") == 3:
            targets.append(ip.rsplit(".", 1)[0] + ".255")
