"""A simple personal RSS reader with folders and unread counters.

Run:  python3 rss_reader.py
Then it opens http://127.0.0.1:8765 in your browser. Your data is stored in
the file rss_reader.db next to this script. Press Ctrl+C in Terminal to quit.
"""
import html
import json
import re
import sqlite3
import threading
import time
import webbrowser
import xml.etree.ElementTree as ET
from datetime import datetime, timezone
from email.utils import parsedate_to_datetime
