from urllib.request import Request, urlopen

HOST, PORT = "127.0.0.1", 8765
DB_PATH = Path(__file__).with_name("rss_reader.db")
REFRESH_EVERY = 30 * 60  # seconds
refresh_lock = threading.Lock()


def db():
    conn = sqlite3.connect(DB_PATH, timeout=30)
    conn.row_factory = sqlite3.Row
    conn.execute("PRAGMA foreign_keys = ON")
    return conn


def init_db():
    with db() as c:
        c.executescript("""
        CREATE TABLE IF NOT EXISTS folders (
            id INTEGER PRIMARY KEY, name TEXT NOT NULL UNIQUE);
        CREATE TABLE IF NOT EXISTS feeds (
            id INTEGER PRIMARY KEY, url TEXT NOT NULL UNIQUE, title TEXT,
            folder_id INTEGER REFERENCES folders(id) ON DELETE SET NULL,
            error TEXT);
        CREATE TABLE IF NOT EXISTS items (
            id INTEGER PRIMARY KEY,
            feed_id INTEGER NOT NULL REFERENCES feeds(id) ON DELETE CASCADE,
            guid TEXT NOT NULL, title TEXT, link TEXT, summary TEXT,
            published TEXT, is_read INTEGER NOT NULL DEFAULT 0,
            UNIQUE(feed_id, guid));
        """)


# ---------- Fetching and parsing ----------

def local(tag):
    return tag.rsplit("}", 1)[-1] if isinstance(tag, str) else ""


def child_text(el, *names):
    for ch in el:
        if local(ch.tag) in names and (ch.text or "").strip():
            return ch.text.strip()
    return ""


def strip_html(text):
    text = re.sub(r"(?is)<(script|style).*?</\1>", "", text or "")
    text = re.sub(r"(?i)<br\s*/?>|</p>", "\n", text)
    text = re.sub(r"<[^>]+>", "", text)
    return re.sub(r"\n{3,}", "\n\n", html.unescape(text)).strip()[:3000]


def parse_date(text):
    if text:
        try:
            d = parsedate_to_datetime(text)
        except (TypeError, ValueError):
            try:
                d = datetime.fromisoformat(text.replace("Z", "+00:00"))
            except ValueError:
                d = None
        if d:
            if d.tzinfo is None:
                d = d.replace(tzinfo=timezone.utc)
            return d.astimezone(timezone.utc).isoformat()
    return datetime.now(timezone.utc).isoformat()


def parse_feed(data):
    root = ET.fromstring(data)
    channel = root.find("channel") if local(root.tag) == "rss" else root
    title = child_text(channel, "title")
    items = []
    for el in channel.iter():
        if local(el.tag) not in ("item", "entry"):
            continue
        link = child_text(el, "link")
        if not link:
            for ch in el:
                if local(ch.tag) == "link" and ch.get("href"):
                    if ch.get("rel", "alternate") == "alternate":
                        link = ch.get("href")
                        break
        if not link.startswith(("http://", "https://")):
            link = ""
        item_title = strip_html(child_text(el, "title")) or "(no title)"
        summary = strip_html(child_text(el, "encoded", "content", "summary", "description"))
        guid = child_text(el, "guid", "id") or link or item_title
        date = child_text(el, "pubDate", "published", "updated", "date")
        items.append((guid, item_title, link, summary, parse_date(date)))
    return title, items


def refresh_feed(feed_id):
    with db() as c:
        url = c.execute("SELECT url FROM feeds WHERE id=?", (feed_id,)).fetchone()["url"]
    try:
        req = Request(url, headers={"User-Agent": "Mozilla/5.0 (personal RSS reader)"})
