"""Download engine: resumable HTTP downloads with a shared global speed limit.

No third-party dependencies (standard library only).
"""
import os
import re
import threading
import time
import urllib.error
import urllib.parse
import urllib.request

CHUNK = 16 * 1024

QUEUED, DOWNLOADING, PAUSED, COMPLETED, ERROR = (
    "Queued", "Downloading", "Paused", "Completed", "Error")


class RateLimiter:
    """Shared limiter: all downloads draw from one bytes/sec budget."""

    def __init__(self):
        self.limit = 0  # bytes per second, 0 = unlimited
        self._lock = threading.Lock()
        self._next = 0.0

    def set_limit(self, bytes_per_sec):
        with self._lock:
            self.limit = max(0, int(bytes_per_sec))
            self._next = 0.0

    def consume(self, n, stop):
        """Block long enough that throughput stays under the limit."""
        with self._lock:
            limit = self.limit
            if not limit:
                return
            now = time.monotonic()
            # Allow at most ~0.25s of accumulated credit so changes apply fast.
            self._next = max(self._next, now - 0.25) + n / limit
            delay = self._next - now
        while delay > 0 and not stop.is_set():
            step = min(delay, 0.1)
            time.sleep(step)
            delay -= step


def filename_from(url, content_disposition=None):
    if content_disposition:
        m = re.search(r"filename\*=(?:UTF-8'')?([^;]+)", content_disposition, re.I)
        if m:
            name = urllib.parse.unquote(m.group(1).strip('" '))
        else:
            m = re.search(r'filename="?([^";]+)"?', content_disposition, re.I)
            name = m.group(1) if m else ""
        name = os.path.basename(name.replace("\\", "/"))
        if name:
            return name
    path = urllib.parse.unquote(urllib.parse.urlparse(url).path)
    return os.path.basename(path) or "download"


def unique_path(path):
    if not os.path.exists(path):
        return path
    base, ext = os.path.splitext(path)
    i = 1
    while os.path.exists(f"{base} ({i}){ext}"):
        i += 1
    return f"{base} ({i}){ext}"


class Download:
    _ids = 0

    def __init__(self, url, folder, limiter, on_change=None):
        Download._ids += 1
        self.id = Download._ids
        self.url = url
        self.folder = folder
        self.limiter = limiter
        self.on_change = on_change or (lambda d: None)
        self.name = filename_from(url)
        self.state = QUEUED
        self.total = 0
        self.downloaded = 0
        self.error = ""
        self.final_path = ""
        self._stop = threading.Event()
        self._thread = None
        self._sync_part_size()

    @property
    def part_path(self):
        return os.path.join(self.folder, self.name + ".part")

    def _sync_part_size(self):
        try:
            self.downloaded = os.path.getsize(self.part_path)
        except OSError:
            self.downloaded = 0

    def _set_state(self, state, error=""):
        self.state = state
        self.error = error
        self.on_change(self)

    # --- controls -------------------------------------------------------
    def start(self):
        if self._thread and self._thread.is_alive():
            return
        if self.state in (COMPLETED, DOWNLOADING):
            return
        self._stop.clear()
        self._set_state(DOWNLOADING)
        self._thread = threading.Thread(target=self._run, daemon=True)
        self._thread.start()

    def pause(self):
        if self.state == DOWNLOADING:
            self._stop.set()
            self._pause_requested = True
        elif self.state == QUEUED:
            self._set_state(PAUSED)

    def cancel(self, delete_partial=True):
