def utf7_decode(s):
    def repl(m):
        if m.group(1) == "":
            return "&"
        b = m.group(1).replace(",", "/")
        b += "=" * (-len(b) % 4)
        return base64.b64decode(b).decode("utf-16-be")
    return re.sub(r"&([^-]*)-", repl, s)


def utf7_encode(s):
    out, buf = "", ""

    def flush():
        nonlocal out, buf
        if buf:
            b = base64.b64encode(buf.encode("utf-16-be")).decode().rstrip("=")
            out += "&" + b.replace("/", ",") + "-"
            buf = ""
    for ch in s:
        if 0x20 <= ord(ch) <= 0x7E:
            flush()
            out += "&-" if ch == "&" else ch
        else:
            buf += ch
    flush()
    return out


def quote(name):
    return '"' + utf7_encode(name).replace("\\", "\\\\").replace('"', '\\"') + '"'


def dh(value):
    try:
        return str(make_header(decode_header(value or "")))
    except Exception:
        return value or ""


