def list_folders():
    conn = need_conn()
    typ, data = conn.list()
    folders = []
    for line in data:
        if not line:
            continue
        line = line.decode("utf-8", "replace")
        m = re.match(r'\((.*?)\) (?:"(.*?)"|NIL) (.*)$', line)
        if not m:
            continue
        flags, name = m.group(1), m.group(3).strip()
        if "\\Noselect" in flags:
            continue
        if name.startswith('"') and name.endswith('"'):
            name = name[1:-1].replace('\\"', '"').replace("\\\\", "\\")
        folders.append(utf7_decode(name))
    folders.sort(key=lambda f: (f.upper() != "INBOX", f.lower()))
    return folders


def list_messages(folder, page):
    conn = need_conn()
    typ, _ = conn.select(quote(folder))
    if typ != "OK":
        raise ValueError("Cannot open folder")
    typ, data = conn.uid("SEARCH", None, "ALL")
    uids = data[0].split() if data and data[0] else []
    total = len(uids)
    end = total - page * PAGE_SIZE
    start = max(0, end - PAGE_SIZE)
    chunk = uids[start:max(0, end)]
    messages = []
    if chunk:
        typ, data = conn.uid(
            "FETCH", b",".join(chunk),
            "(FLAGS BODY.PEEK[HEADER.FIELDS (FROM SUBJECT DATE)])")
        for item in data:
            if not isinstance(item, tuple):
                continue
            meta = item[0].decode("utf-8", "replace")
            uid = re.search(r"UID (\d+)", meta)
            flags = re.search(r"FLAGS \((.*?)\)", meta)
            hdr = email.message_from_bytes(item[1], policy=policy.default)
            messages.append({
                "uid": uid.group(1) if uid else "",
                "unread": "\\Seen" not in (flags.group(1) if flags else ""),
                "from": dh(hdr["From"]),
                "subject": dh(hdr["Subject"]) or "(no subject)",
                "date": dh(hdr["Date"]),
            })
        messages.sort(key=lambda m: int(m["uid"]), reverse=True)
    return {"messages": messages, "total": total,
            "has_more": start > 0}


def get_message(folder, uid):
    conn = need_conn()
    if not re.fullmatch(r"\d+", uid):
        raise ValueError("Bad id")
    typ, _ = conn.select(quote(folder))
    if typ != "OK":
        raise ValueError("Cannot open folder")
    typ, data = conn.uid("FETCH", uid, "(BODY.PEEK[])")
    raw = next((i[1] for i in data if isinstance(i, tuple)), None)
    if raw is None:
        raise ValueError("Message not found")
    conn.uid("STORE", uid, "+FLAGS", "(\\Seen)")
    msg = email.message_from_bytes(raw, policy=policy.default)

    body = msg.get_body(preferencelist=("html", "plain"))
    html, text = None, ""
    if body is not None:
        try:
            content = body.get_content()
        except Exception:
            content = ""
        if body.get_content_type() == "text/html":
            html = content
        else:
            text = content
    if html:
        # Show embedded (cid:) images; remote images stay blocked.
        for part in msg.walk():
            cid = part.get("Content-ID")
            if cid and part.get_content_maintype() == "image":
                data_uri = "data:%s;base64,%s" % (
                    part.get_content_type(),
                    base64.b64encode(part.get_payload(decode=True) or b"").decode())
                html = html.replace("cid:" + cid.strip("<>"), data_uri)
    attachments = [p.get_filename() for p in msg.iter_attachments()
                   if p.get_filename()]
    return {
        "from": dh(msg["From"]), "to": dh(msg["To"]), "cc": dh(msg["Cc"]),
        "subject": dh(msg["Subject"]) or "(no subject)",
        "date": dh(msg["Date"]), "html": html, "text": text,
        "attachments": attachments,
    }


