#!/usr/bin/env python3
"""Small download manager: pause, resume, global speed limit.

Standard library only (tkinter + urllib), so it starts fast and stays small.
Run: python3 downloader.py
"""
import json
import os
import threading
import time
import tkinter as tk
from tkinter import messagebox, ttk
from urllib.parse import unquote, urlparse

CHUNK = 16 * 1024
STATE_FILE = os.path.join(os.path.expanduser("~"), ".pydl_state.json")
DEST_DIR = os.path.join(os.path.expanduser("~"), "Downloads")


class Limiter:
    """Shared rate limiter. rate is in bytes/s, 0 means unlimited."""

    def __init__(self):
        self.rate = 0
        self.next = 0.0
        self.lock = threading.Lock()

    def acquire(self, n, stop):
        rate = self.rate
        if not rate:
            return
        with self.lock:
            now = time.monotonic()
            start = max(self.next, now)
            self.next = start + n / rate
            wait = start - now
        if wait > 0:
            stop.wait(wait)


class Download:
    def __init__(self, url, path, **kw):
        self.url = url
        self.path = path
        self.state = kw.get("state", "queued")  # queued/downloading/pausing/paused/done/error
        self.downloaded = kw.get("downloaded", 0)
        self.total = kw.get("total", 0)
        self.etag = kw.get("etag", "")
        self.error = ""
        self.speed = 0.0
        self.thread = None
        self.stop = threading.Event()

    @property
    def part(self):
        return self.path + ".part"

    def to_json(self):
        return {"url": self.url, "path": self.path, "state": self.state,
                "downloaded": self.downloaded, "total": self.total, "etag": self.etag}

    def active(self):
        return self.thread is not None and self.thread.is_alive()

    def start(self, limiter):
        if self.active():
            return
        self.stop = threading.Event()
        self.state = "downloading"
        self.error = ""
        self.thread = threading.Thread(target=self._run, args=(limiter, self.stop), daemon=True)
        self.thread.start()

    def pause(self):
        if self.active():
            self.state = "pausing"
            self.stop.set()
        elif self.state in ("queued", "downloading"):
            self.state = "paused"

    def _run(self, limiter, stop):
        import urllib.error
        import urllib.request
        try:
            for attempt in (0, 1):
                try:
                    self._transfer(limiter, stop, urllib.request)
                    break
                except urllib.error.HTTPError as e:
                    # 416: our partial file doesn't match the server; restart once.
                    if e.code == 416 and attempt == 0:
                        self._reset()
                        continue
                    raise
        except Exception as e:  # network, disk, HTTP errors
            self.error = str(e)
            self.state = "error"
            return
        if self.state == "done":
            return
        self.state = "paused" if stop.is_set() else "error"

    def _reset(self):
        self.downloaded = 0
        self.etag = ""
        try:
            os.remove(self.part)
        except OSError:
            pass

    def _transfer(self, limiter, stop, request):
        have = os.path.getsize(self.part) if os.path.exists(self.part) else 0
        self.downloaded = have
        headers = {"User-Agent": "pydl/1.0"}
        if have:
            headers["Range"] = f"bytes={have}-"
            if self.etag:
                headers["If-Range"] = self.etag
        req = request.Request(self.url, headers=headers)
        with request.urlopen(req, timeout=15) as resp:
            if have and resp.status != 206:  # server ignored Range: start over
                have = 0
                self.downloaded = 0
            cr = resp.headers.get("Content-Range")  # "bytes a-b/total"
            if resp.status == 206 and cr and "/" in cr and cr.rsplit("/", 1)[1].isdigit():
                self.total = int(cr.rsplit("/", 1)[1])
            else:
                length = resp.headers.get("Content-Length")
                self.total = have + int(length) if length and length.isdigit() else 0
            self.etag = resp.headers.get("ETag", "") or ""
            if self.etag.startswith("W/"):  # weak validators are invalid in If-Range
                self.etag = ""
            os.makedirs(os.path.dirname(self.part), exist_ok=True)
            last_t, last_n = time.monotonic(), self.downloaded
            with open(self.part, "ab" if have else "wb") as f:
                while not stop.is_set():
                    data = resp.read(CHUNK)
                    if not data:
                        break
                    f.write(data)
                    self.downloaded += len(data)
                    now = time.monotonic()
                    if now - last_t >= 1:
                        self.speed = (self.downloaded - last_n) / (now - last_t)
                        last_t, last_n = now, self.downloaded
                    limiter.acquire(len(data), stop)
                else:
                    self.speed = 0
                    return  # paused
        self.speed = 0
        if self.total and self.downloaded < self.total:
            raise IOError("connection closed before download completed")
        os.replace(self.part, self.path)
        if not self.total:
            self.total = self.downloaded
        self.state = "done"


def unique_path(name):
    os.makedirs(DEST_DIR, exist_ok=True)
    base, ext = os.path.splitext(name)
    path, i = os.path.join(DEST_DIR, name), 1
    while os.path.exists(path) or os.path.exists(path + ".part"):
        path = os.path.join(DEST_DIR, f"{base} ({i}){ext}")
        i += 1
    return path


def fmt_size(n):
    for unit in ("B", "KB", "MB", "GB"):
        if n < 1024 or unit == "GB":
            return f"{n:.0f} {unit}" if unit == "B" else f"{n:.1f} {unit}"
        n /= 1024


