import Cocoa
import Darwin

// Sum of 64-bit rx/tx byte counters over all up, non-loopback interfaces.
func readCounters(_ buf: inout [UInt8]) -> (rx: UInt64, tx: UInt64) {
    var mib: [Int32] = [CTL_NET, PF_ROUTE, 0, 0, NET_RT_IFLIST2, 0]
    var len = 0
    guard sysctl(&mib, UInt32(mib.count), nil, &len, nil, 0) == 0, len > 0 else { return (0, 0) }
    if buf.count < len { buf = [UInt8](repeating: 0, count: len * 2) }
    len = buf.count
    guard sysctl(&mib, UInt32(mib.count), &buf, &len, nil, 0) == 0 else { return (0, 0) }

    var rx: UInt64 = 0, tx: UInt64 = 0
    buf.withUnsafeBytes { raw in
        var off = 0
        while off + MemoryLayout<if_msghdr>.size <= len {
            let hdr = raw.baseAddress!.advanced(by: off).assumingMemoryBound(to: if_msghdr.self)
            let msgLen = Int(hdr.pointee.ifm_msglen)
            if msgLen == 0 { break }
            if Int32(hdr.pointee.ifm_type) == RTM_IFINFO2 {
                let h2 = raw.baseAddress!.advanced(by: off).assumingMemoryBound(to: if_msghdr2.self)
                let d = h2.pointee.ifm_data
                if Int32(h2.pointee.ifm_flags) & IFF_UP != 0, Int32(d.ifi_type) != IFT_LOOP {
                    rx &+= d.ifi_ibytes
                    tx &+= d.ifi_obytes
                }
            }
            off += msgLen
        }
    }
    return (rx, tx)
}

func fmt(_ bytesPerSec: Double) -> String {
    let units = ["B", "K", "M", "G"]
    var v = bytesPerSec, i = 0
    while v >= 1000 && i < units.count - 1 { v /= 1024; i += 1 }
    return v < 10 && i > 0 ? String(format: "%.1f%@", v, units[i]) : String(format: "%.0f%@", v, units[i])
}

final class App: NSObject, NSApplicationDelegate {
    let item = NSStatusBar.system.statusItem(withLength: NSStatusItem.variableLength)
    let totalItem = NSMenuItem(title: "", action: nil, keyEquivalent: "")
    var buf = [UInt8](repeating: 0, count: 16384)
    var last = (rx: UInt64(0), tx: UInt64(0))
    var lastTime = DispatchTime.now()
    var base = (rx: UInt64(0), tx: UInt64(0))
    var timer: DispatchSourceTimer?
    let font = NSFont.monospacedDigitSystemFont(ofSize: 10, weight: .regular)

    func applicationDidFinishLaunching(_ n: Notification) {
        let menu = NSMenu()
        totalItem.isEnabled = false
        menu.addItem(totalItem)
        menu.addItem(.separator())
        menu.addItem(NSMenuItem(title: "Quit", action: #selector(NSApplication.terminate(_:)), keyEquivalent: "q"))
        item.menu = menu
        item.button?.font = font

        last = readCounters(&buf)
        base = last
        update(down: 0, up: 0)

        let t = DispatchSource.makeTimerSource(queue: .main)
        t.schedule(deadline: .now() + 1, repeating: 1, leeway: .milliseconds(100))
        t.setEventHandler { [weak self] in self?.tick() }
        t.resume()
        timer = t
    }

    func tick() {
        let now = DispatchTime.now()
        let dt = Double(now.uptimeNanoseconds - lastTime.uptimeNanoseconds) / 1e9
        let cur = readCounters(&buf)
        // Counters can drop if an interface goes away; clamp to zero.
        let down = cur.rx >= last.rx ? Double(cur.rx - last.rx) / dt : 0
        let up = cur.tx >= last.tx ? Double(cur.tx - last.tx) / dt : 0
        last = cur
        lastTime = now
        update(down: down, up: up)
    }

    func update(down: Double, up: Double) {
        item.button?.title = "↓\(fmt(down)) ↑\(fmt(up))"
        let rx = last.rx >= base.rx ? last.rx - base.rx : 0
        let tx = last.tx >= base.tx ? last.tx - base.tx : 0
        totalItem.title = "Since launch: ↓\(fmt(Double(rx)))B  ↑\(fmt(Double(tx)))B"
    }
}

