"""pyrc - a small, fast-starting IRC client with multiple servers and channels.

Standard library only. One Text widget is shared by all buffers and only the
active buffer is rendered; scrollback per buffer is capped to keep memory low.
"""
import json
import os
import queue
import socket
import ssl
import sys
import threading
import time
import tkinter as tk
from collections import deque
from tkinter import messagebox, ttk

SCROLLBACK = 1000
CONFIG_PATH = os.path.join(
    os.environ.get("XDG_CONFIG_HOME") or os.path.expanduser("~/.config"),
    "pyrc", "servers.json")
PREFIXES = "~&@%+"


# --------------------------------------------------------------- protocol ---

def parse(line):
    """Return (nick, prefix, command, params) for a raw IRC line."""
    if line.startswith("@"):  # message tags: ignored
        line = line.split(" ", 1)[1] if " " in line else ""
    prefix = ""
    if line.startswith(":"):
        prefix, _, line = line[1:].partition(" ")
    trailing = None
    if " :" in line:
        line, _, trailing = line.partition(" :")
    elif line.startswith(":"):
        line, trailing = "", line[1:]
    parts = line.split()
    if not parts:
        return "", prefix, "", []
    params = parts[1:] + ([trailing] if trailing is not None else [])
    return prefix.split("!", 1)[0], prefix, parts[0].upper(), params


def decode(data):
    try:
        return data.decode("utf-8")
    except UnicodeDecodeError:
        return data.decode("latin-1")


class Conn:
    """One server connection. Network I/O runs in threads; results are posted
    to `events` and consumed by the Tk thread, so no widget is touched here."""

    def __init__(self, cfg, events):
        self.cfg = cfg
        self.name = cfg["name"]
        self.events = events
        self.nick = cfg["nick"]
        self.out = queue.Queue()
        self.sock = None
        self.alive = False
        self.generation = 0

    def start(self):
        self.close()
        self.generation += 1
        self.alive = True
        self.out = queue.Queue()
        self.nick = self.cfg["nick"]
        threading.Thread(target=self._run, args=(self.generation, self.out),
                         daemon=True).start()

    def post(self, kind, data=""):
        self.events.put((self, kind, data))

    def send(self, line):
        line = line.replace("\r", " ").replace("\n", " ")
        if self.alive:
            self.out.put(line.encode("utf-8")[:510] + b"\r\n")

    def close(self):
        self.alive = False
        self.out.put(None)
        if self.sock:
            try:
                self.sock.close()
            except OSError:
                pass

    def _run(self, gen, out):
        cfg = self.cfg
        try:
            self.post("status", "Connecting to %s:%s%s..." % (
                cfg["host"], cfg["port"], " (TLS)" if cfg["tls"] else ""))
            sock = socket.create_connection((cfg["host"], int(cfg["port"])), 20)
            if cfg["tls"]:
                sock = ssl.create_default_context().wrap_socket(
                    sock, server_hostname=cfg["host"])
            sock.settimeout(None)
            self.sock = sock
            threading.Thread(target=self._write, args=(sock, out),
                             daemon=True).start()
            if cfg.get("password"):
                self.send("PASS " + cfg["password"])
            self.send("NICK " + cfg["nick"])
            self.send("USER %s 0 * :%s" % (cfg["nick"], cfg["nick"]))
            buf = b""
            while True:
                data = sock.recv(4096)
                if not data:
                    break
                buf += data
                *lines, buf = buf.split(b"\n")
                for raw in lines:
                    raw = decode(raw.rstrip(b"\r"))
                    if raw:
                        self.post("line", raw)
        except (OSError, ssl.SSLError) as e:
            if gen == self.generation and self.alive:
                self.post("status", "Connection error: %s" % e)
        finally:
            if gen == self.generation:
                self.alive = False
                self.post("closed")
            out.put(None)

    @staticmethod
    def _write(sock, out):
        try:
            while True:
                item = out.get()
                if item is None:
                    return
                sock.sendall(item)
        except OSError:
            pass


# ------------------------------------------------------------------ state ---

class Buffer:
    def __init__(self, conn, name):
        self.conn = conn
        self.name = name            # "" for the server buffer
        self.lines = deque(maxlen=SCROLLBACK)
        self.nicks = {}             # nick -> prefix char
        self.topic = ""
        self.unread = 0             # 0 none, 1 activity, 2 highlight
        self.joined = False

    @property
    def is_channel(self):
        return self.name[:1] in "#&+!"


def load_config():
    try:
        with open(CONFIG_PATH, encoding="utf-8") as f:
            return json.load(f)
    except (OSError, ValueError):
        return []


def save_config(servers):
    os.makedirs(os.path.dirname(CONFIG_PATH), exist_ok=True)
    with open(CONFIG_PATH, "w", encoding="utf-8") as f:
        json.dump(servers, f, indent=2)
    try:
        os.chmod(CONFIG_PATH, 0o600)  # may hold passwords
    except OSError:
        pass


