//! Renders the current speeds into a tiny RGBA tray icon using a 3x5 bitmap font.

use tray_icon::Icon;

const SIZE: u32 = 32;
const SCALE: u32 = 2;
const GLYPH_W: u32 = 3;
const GLYPH_H: u32 = 5;
const GAP: u32 = 1;

const DOWN: [u8; 4] = [0x3d, 0xdc, 0x84, 0xff];
const UP: [u8; 4] = [0xff, 0x9f, 0x1c, 0xff];

fn glyph(c: char) -> [u8; 5] {
    match c {
        '0' => [0b111, 0b101, 0b101, 0b101, 0b111],
        '1' => [0b010, 0b110, 0b010, 0b010, 0b111],
        '2' => [0b111, 0b001, 0b111, 0b100, 0b111],
        '3' => [0b111, 0b001, 0b111, 0b001, 0b111],
        '4' => [0b101, 0b101, 0b111, 0b001, 0b001],
        '5' => [0b111, 0b100, 0b111, 0b001, 0b111],
        '6' => [0b111, 0b100, 0b111, 0b101, 0b111],
        '7' => [0b111, 0b001, 0b001, 0b010, 0b010],
        '8' => [0b111, 0b101, 0b111, 0b101, 0b111],
        '9' => [0b111, 0b101, 0b111, 0b001, 0b111],
        '.' => [0b000, 0b000, 0b000, 0b000, 0b010],
        'K' => [0b101, 0b101, 0b110, 0b101, 0b101],
        'M' => [0b101, 0b111, 0b111, 0b101, 0b101],
        'G' => [0b111, 0b100, 0b101, 0b101, 0b111],
        'B' => [0b110, 0b101, 0b110, 0b101, 0b110],
        _ => [0; 5],
    }
}

fn draw_text(buf: &mut [u8], text: &str, top: u32, color: [u8; 4]) {
    let advance = (GLYPH_W + GAP) * SCALE;
    for (i, ch) in text.chars().take(4).enumerate() {
        let x0 = i as u32 * advance;
        for (row, bits) in glyph(ch).iter().enumerate() {
            for col in 0..GLYPH_W {
                if bits & (1 << (GLYPH_W - 1 - col)) == 0 {
                    continue;
                }
                for dy in 0..SCALE {
                    for dx in 0..SCALE {
                        let x = x0 + col * SCALE + dx;
                        let y = top + row as u32 * SCALE + dy;
                        if x < SIZE && y < SIZE {
                            let o = ((y * SIZE + x) * 4) as usize;
                            buf[o..o + 4].copy_from_slice(&color);
                        }
                    }
                }
            }
        }
    }
}

/// `down` and `up` are compact strings such as "1.2M" (see `format::compact`).
pub fn render(down: &str, up: &str) -> Icon {
    let mut buf = vec![0u8; (SIZE * SIZE * 4) as usize];
    draw_text(&mut buf, down, 4, DOWN);
    draw_text(&mut buf, up, 4 + GLYPH_H * SCALE + 4, UP);
    Icon::from_rgba(buf, SIZE, SIZE).expect("valid icon buffer")
}

#![cfg_attr(all(not(debug_assertions), target_os = "windows"), windows_subsystem = "windows")]

mod icon;

use std::time::{Duration, Instant};

use sysinfo::Networks;
use tao::event::{Event, StartCause};
use tao::event_loop::{ControlFlow, EventLoopBuilder};
use tray_icon::menu::{Menu, MenuEvent, MenuItem, PredefinedMenuItem};
use tray_icon::TrayIconBuilder;

const INTERVAL: Duration = Duration::from_secs(1);

enum UserEvent {
    Menu(MenuEvent),
}

/// Compact form for the icon, at most 4 chars: "0B", "512K", "1.2M".
fn compact(bytes_per_sec: f64) -> String {
    let units = ['B', 'K', 'M', 'G'];
    let mut v = bytes_per_sec;
    let mut u = 0;
    while v >= 999.5 && u < units.len() - 1 {
        v /= 1024.0;
        u += 1;
    }
    if v < 9.95 && u > 0 {
        format!("{:.1}{}", v, units[u])
    } else {
        format!("{:.0}{}", v, units[u])
    }
}

/// Human readable form for the menu and tooltip.
fn human(bytes_per_sec: f64) -> String {
    let units = ["B/s", "KB/s", "MB/s", "GB/s"];
    let mut v = bytes_per_sec;
    let mut u = 0;
    while v >= 1024.0 && u < units.len() - 1 {
        v /= 1024.0;
        u += 1;
    }
    format!("{:.1} {}", v, units[u])
}

/// Sum of byte counters over all non-loopback interfaces.
fn totals(networks: &Networks) -> (u64, u64) {
    networks
        .iter()
        .filter(|(name, _)| !(name.as_str() == "lo" || name.starts_with("lo0")))
        .fold((0, 0), |(rx, tx), (_, d)| {
            (rx + d.total_received(), tx + d.total_transmitted())
        })
}

fn main() {
    let mut builder = EventLoopBuilder::<UserEvent>::with_user_event();
    #[cfg(target_os = "macos")]
    {
        use tao::platform::macos::{ActivationPolicy, EventLoopBuilderExtMacOS};
        builder.with_activation_policy(ActivationPolicy::Accessory);
    }
    let event_loop = builder.build();

    let proxy = event_loop.create_proxy();
    MenuEvent::set_event_handler(Some(move |e| {
        let _ = proxy.send_event(UserEvent::Menu(e));
    }));

    let down_item = MenuItem::new("Down: 0.0 B/s", false, None);
    let up_item = MenuItem::new("Up: 0.0 B/s", false, None);
    let quit_item = MenuItem::new("Quit", true, None);
    let menu = Menu::new();
    menu.append_items(&[
        &down_item,
        &up_item,
        &PredefinedMenuItem::separator(),
        &quit_item,
    ])
    .expect("build menu");
    let quit_id = quit_item.id().clone();

    let mut networks = Networks::new_with_refreshed_list();
    let (mut last_rx, mut last_tx) = totals(&networks);
    let mut last_time = Instant::now();
    let mut tray = None;

    event_loop.run(move |event, _, control_flow| {
        *control_flow = ControlFlow::WaitUntil(Instant::now() + INTERVAL);

        match event {
            // The tray icon must be created once the event loop is running (macOS/Linux).
            Event::NewEvents(StartCause::Init) => {
                tray = TrayIconBuilder::new()
                    .with_menu(Box::new(menu.clone()))
                    .with_icon(icon::render("0B", "0B"))
                    .with_tooltip("Network speed")
                    .build()
                    .map_err(|e| eprintln!("failed to create tray icon: {e}"))
                    .ok();
                if tray.is_none() {
                    *control_flow = ControlFlow::Exit;
                }
            }
            Event::NewEvents(StartCause::ResumeTimeReached { .. }) => {
                networks.refresh(true);
                let (rx, tx) = totals(&networks);
                let now = Instant::now();
                let secs = now.duration_since(last_time).as_secs_f64().max(0.001);
                // Counters can reset (interface removed/reset); never go negative.
                let down = rx.saturating_sub(last_rx) as f64 / secs;
                let up = tx.saturating_sub(last_tx) as f64 / secs;
                (last_rx, last_tx, last_time) = (rx, tx, now);

                let (down_s, up_s) = (human(down), human(up));
                down_item.set_text(format!("Down: {down_s}"));
                up_item.set_text(format!("Up: {up_s}"));
                if let Some(t) = &tray {
                    t.set_icon(Some(icon::render(&compact(down), &compact(up)))).ok();
                    let _ = t.set_tooltip(Some(format!("Down: {down_s}\nUp: {up_s}")));
                    // Shown next to the icon in the macOS menu bar; ignored on Windows.
                    t.set_title(Some(format!("↓{} ↑{}", compact(down), compact(up))));
                }
            }
            Event::UserEvent(UserEvent::Menu(e)) if e.id == quit_id => {
                tray.take();
                *control_flow = ControlFlow::Exit;
            }
            _ => {}
        }
    });
}

