"""A small SFTP file browser that runs on your own computer.

It starts a local web page (only reachable from this computer) where you can
connect to an SFTP server, browse folders, download, upload, create folders,
and delete files.
"""
import json
import posixpath
import secrets
import stat
import threading
import webbrowser
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from urllib.parse import parse_qs, quote, urlparse

import paramiko

HOST = "127.0.0.1"
PORT = 8765
TOKEN = secrets.token_urlsafe(24)  # stops other websites from talking to this app

state = {"ssh": None, "sftp": None}
lock = threading.Lock()


def disconnect():
    for key in ("sftp", "ssh"):
        if state[key]:
            try:
                state[key].close()
            except Exception:
                pass
        state[key] = None


def connect(data):
    disconnect()
    ssh = paramiko.SSHClient()
    ssh.load_system_host_keys()
    ssh.set_missing_host_key_policy(paramiko.AutoAddPolicy())
    key_file = (data.get("key_file") or "").strip() or None
    ssh.connect(
        data["host"].strip(),
        port=int(data.get("port") or 22),
        username=data["username"].strip(),
        password=data.get("password") or None,
        key_filename=key_file and posixpath.expanduser(key_file),
        timeout=15,
        look_for_keys=not data.get("password"),
        allow_agent=not data.get("password"),
    )
    state["ssh"] = ssh
    state["sftp"] = ssh.open_sftp()
    return state["sftp"].normalize(".")


def list_dir(path):
    sftp = state["sftp"]
    path = sftp.normalize(path)
    items = []
    for a in sftp.listdir_attr(path):
        items.append({
            "name": a.filename,
            "is_dir": stat.S_ISDIR(a.st_mode or 0),
            "size": a.st_size,
            "mtime": a.st_mtime,
        })
    items.sort(key=lambda i: (not i["is_dir"], i["name"].lower()))
    return {"path": path, "items": items}


def delete(path):
    sftp = state["sftp"]
    if stat.S_ISDIR(sftp.lstat(path).st_mode):
        for a in sftp.listdir_attr(path):
            delete(posixpath.join(path, a.filename))
        sftp.rmdir(path)
    else:
        sftp.remove(path)


class Handler(BaseHTTPRequestHandler):
    def log_message(self, *args):
        pass

    def _authorized(self, query):
        host_ok = self.headers.get("Host", "").split(":")[0] in ("127.0.0.1", "localhost")
        tok = self.headers.get("X-Token") or query.get("token", [""])[0]
        return host_ok and secrets.compare_digest(tok, TOKEN)

    def _json(self, obj, code=200):
        body = json.dumps(obj).encode()
        self.send_response(code)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    def do_GET(self):
        url = urlparse(self.path)
        q = parse_qs(url.query)
        if url.path == "/":
            body = PAGE.replace("__TOKEN__", TOKEN).encode()
            self.send_response(200)
            self.send_header("Content-Type", "text/html; charset=utf-8")
            self.send_header("Content-Length", str(len(body)))
            self.end_headers()
            self.wfile.write(body)
            return
        if not self._authorized(q):
            return self._json({"error": "Not authorized"}, 403)
        try:
            if url.path == "/api/list":
                with lock:
                    return self._json(list_dir(q.get("path", ["."])[0]))
            if url.path == "/api/download":
                path = q["path"][0]
                with lock:
                    f = state["sftp"].open(path, "rb")
                    size = state["sftp"].stat(path).st_size
                    self.send_response(200)
                    self.send_header("Content-Type", "application/octet-stream")
                    self.send_header("Content-Length", str(size))
                    self.send_header(
                        "Content-Disposition",
                        "attachment; filename*=UTF-8''" + quote(posixpath.basename(path)),
                    )
                    self.end_headers()
                    with f:
                        while chunk := f.read(65536):
                            self.wfile.write(chunk)
                return
            self._json({"error": "Not found"}, 404)
        except Exception as e:
            self._json({"error": str(e) or type(e).__name__}, 500)

    def do_POST(self):
        url = urlparse(self.path)
        q = parse_qs(url.query)
        if not self._authorized(q):
            return self._json({"error": "Not authorized"}, 403)
        length = int(self.headers.get("Content-Length") or 0)
        try:
            if url.path == "/api/upload":
                dest = q["path"][0]
                with lock:
                    with state["sftp"].open(dest, "wb") as f:
                        left = length
                        while left > 0:
                            chunk = self.rfile.read(min(65536, left))
                            if not chunk:
                                break
                            f.write(chunk)
                            left -= len(chunk)
                return self._json({"ok": True})
            data = json.loads(self.rfile.read(length) or b"{}")
            with lock:
                if url.path == "/api/connect":
                    return self._json({"path": connect(data)})
                if url.path == "/api/disconnect":
                    disconnect()
                    return self._json({"ok": True})
                if not state["sftp"]:
                    return self._json({"error": "Not connected"}, 400)
                if url.path == "/api/mkdir":
                    state["sftp"].mkdir(data["path"])
                elif url.path == "/api/delete":
                    delete(data["path"])
                elif url.path == "/api/rename":
                    state["sftp"].rename

