"""


class WebhookHandler(BaseHTTPRequestHandler):
    def handle_any(self):
        global counter
        length = int(self.headers.get("Content-Length") or 0)
        raw = self.rfile.read(length) if length else b""
        text = raw.decode("utf-8", errors="replace")
        try:  # pretty-print JSON when possible
            text = json.dumps(json.loads(text), indent=2)
        except ValueError:
            pass
        with lock:
            counter += 1
            requests_log.insert(0, {
                "id": counter,
                "method": self.command,
                "path": self.path,
                "client": self.client_address[0],
                "time": datetime.now().strftime("%H:%M:%S"),
                "headers": dict(self.headers.items()),
                "body": text,
            })
            del requests_log[MAX_STORED:]
        print(f"[{datetime.now():%H:%M:%S}] {self.command} {self.path} ({len(raw)} bytes)")
        body = b'{"status":"received"}'
        self.send_response(200)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    do_GET = do_POST = do_PUT = do_PATCH = do_DELETE = do_OPTIONS = handle_any

    def log_message(self, *args):
        pass


class DashboardHandler(BaseHTTPRequestHandler):
    def send(self, code, ctype, body):
        self.send_response(code)
        self.send_header("Content-Type", ctype)
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    def do_GET(self):
        if self.path == "/api/requests":
            with lock:
                data = json.dumps(requests_log).encode()
            self.send(200, "application/json", data)
        elif self.path == "/":
            page = PAGE.replace("__WPORT__", str(WEBHOOK_PORT)).encode()
            self.send(200, "text/html; charset=utf-8", page)
        else:
            self.send(404, "text/plain", b"Not found")

    def do_POST(self):
        if self.path == "/api/clear":
            with lock:
                requests_log.clear()
            self.send(200, "application/json", b"{}")
        else:
            self.send(404, "text/plain", b"Not found")

    def log_message(self, *args):
        pass


