#!/usr/bin/env python3
"""Wi-Fi Analyzer: lists nearby networks with signal strength.

Backends: macOS (system_profiler), Linux (nmcli), Windows (netsh).
Only the Python standard library (tkinter) is required.
"""
import json
import platform
import re
import subprocess
import threading
import tkinter as tk
from tkinter import ttk

REFRESH_MS = 5000


def run(cmd):
    return subprocess.run(cmd, capture_output=True, text=True, timeout=30).stdout


def pct_to_dbm(pct):
    return int(pct / 2 - 100)


def dbm_to_pct(dbm):
    return max(0, min(100, 2 * (dbm + 100)))


def scan_macos():
    data = json.loads(run(["system_profiler", "SPAirPortDataType", "-json"]))
    nets = []
    for card in data.get("SPAirPortDataType", []):
        for iface in card.get("spairport_airport_interfaces", []):
            cur = iface.get("spairport_current_network_information")
            groups = list(iface.get("spairport_airport_other_local_wireless_networks", []))
            if cur:
                groups.insert(0, cur)
            for n in groups:
                sig = re.search(r"(-\d+)\s*dBm", n.get("spairport_signal_noise", ""))
                if not sig:
                    continue
                chan = n.get("spairport_network_channel", "")
                num = re.match(r"\d+", chan)
                band = re.search(r"(\d(?:\.\d)?)GHz", chan)
                sec = n.get("spairport_security_mode", "").replace("spairport_security_mode_", "")
                nets.append({
                    "ssid": n.get("_name", ""),
                    "dbm": int(sig.group(1)),
                    "channel": num.group(0) if num else "?",
                    "band": band.group(1) + " GHz" if band else "?",
                    "security": sec or "?",
                    "connected": n is cur,
                })
    return nets


def scan_linux():
    out = run(["nmcli", "-t", "-e", "yes", "-f", "IN-USE,SSID,SIGNAL,CHAN,FREQ,SECURITY",
               "dev", "wifi", "list", "--rescan", "yes"])
    nets = []
    for line in out.splitlines():
        f = re.split(r"(?<!\\):", line)
        if len(f) < 6:
            continue
        f = [x.replace("\\:", ":").replace("\\\\", "\\") for x in f]
        try:
            pct = int(f[2])
        except ValueError:
            continue
        mhz = re.match(r"\d+", f[4])
        nets.append({
            "ssid": f[1],
            "dbm": pct_to_dbm(pct),
            "channel": f[3],
            "band": f"{int(mhz.group(0)) / 1000:g} GHz" if mhz else "?",
            "security": f[5] or "Open",
            "connected": f[0].strip() == "*",
        })
    return nets


def scan_windows():
    out = run(["netsh", "wlan", "show", "networks", "mode=bssid"])
    nets, cur = [], None
    for line in out.splitlines():
        line = line.strip()
        m = re.match(r"SSID \d+ : (.*)", line)
        if m:
            cur = {"ssid": m.group(1), "security": "?"}
            continue
        if cur is None or ":" not in line:
            continue
        key, val = [s.strip() for s in line.split(":", 1)]
        if key == "Authentication":
            cur["security"] = val
        elif key == "Signal":
            cur_bss = {**cur, "dbm": pct_to_dbm(int(val.rstrip("%"))),
                       "channel": "?", "band": "?", "connected": False}
            nets.append(cur_bss)
        elif key == "Channel" and nets:
            nets[-1]["channel"] = val
            nets[-1]["band"] = "5 GHz" if int(val) > 14 else "2.4 GHz"
    return nets


def scan():
    system = platform.system()
    fn = {"Darwin": scan_macos, "Linux": scan_linux, "Windows": scan_windows}.get(system)
    if not fn:
        raise RuntimeError(f"Unsupported platform: {system}")
    return fn()


