func securityName(_ n: CWNetwork) -> String {
    let order: [(CWSecurity, String)] = [
        (.wpa3Enterprise, "WPA3 Enterprise"), (.wpa3Personal, "WPA3"),
        (.wpa2Enterprise, "WPA2 Enterprise"), (.wpa2Personal, "WPA2"),
        (.wpaEnterprise, "WPA Enterprise"), (.wpaPersonal, "WPA"),
        (.dynamicWEP, "WEP"), (.WEP, "WEP"), (.none, "Open"),
    ]
    for (s, name) in order where n.supportsSecurity(s) { return name }
    return "Other"
}

