"""Cross-platform Wi-Fi scanning using only OS-provided tools and the stdlib."""
import json
import platform
import re
import subprocess
from dataclasses import dataclass
from typing import List, Optional


class ScanError(Exception):
    pass


@dataclass
class Network:
    ssid: str
    bssid: str = ""
    signal_pct: int = 0      # 0-100
    dbm: Optional[int] = None
    channel: str = ""
    band: str = ""
    security: str = ""


def pct_to_dbm(pct: int) -> int:
    return round(pct / 2 - 100)


def dbm_to_pct(dbm: int) -> int:
    return max(0, min(100, 2 * (dbm + 100)))


def _run(cmd: List[str], timeout: int = 30) -> str:
    try:
        r = subprocess.run(cmd, capture_output=True, text=True, timeout=timeout,
                           encoding="utf-8", errors="replace")
    except FileNotFoundError:
        raise ScanError(f"Required tool not found: {cmd[0]}")
    except subprocess.TimeoutExpired:
        raise ScanError(f"{cmd[0]} timed out")
    if r.returncode != 0:
        raise ScanError((r.stderr or r.stdout).strip() or f"{cmd[0]} failed")
    return r.stdout


def _band_from_channel(ch: str) -> str:
    try:
        n = int(ch)
    except ValueError:
        return ""
    return "2.4 GHz" if n <= 14 else "5 GHz"


def _band_from_freq(mhz: int) -> str:
    if mhz < 3000:
        return "2.4 GHz"
    if mhz < 5925:
        return "5 GHz"
    return "6 GHz"


# ---------------------------------------------------------------- Windows
def parse_netsh(text: str) -> List[Network]:
    nets: List[Network] = []
    ssid = auth = ""
    cur: Optional[Network] = None
    for line in text.splitlines():
        m = re.match(r"^SSID\s+\d+\s*:\s*(.*)$", line.strip())
        if m:
            ssid, auth, cur = m.group(1).strip(), "", None
            continue
        m = re.match(r"^\s*([^:]+?)\s*:\s*(.*)$", line)
        if not m:
            continue
        key, val = m.group(1).strip().lower(), m.group(2).strip()
        if key.startswith("bssid"):
            cur = Network(ssid=ssid or "<hidden>", bssid=val, security=auth)
            nets.append(cur)
        elif key == "authentication":
            auth = val
            if cur is None:
                continue
        elif cur is not None:
            if key == "signal":
                cur.signal_pct = int(val.rstrip("%") or 0)
                cur.dbm = pct_to_dbm(cur.signal_pct)
            elif key == "channel":
                cur.channel = val
                cur.band = _band_from_channel(val)
    return nets


def _scan_windows() -> List[Network]:
    return parse_netsh(_run(["netsh", "wlan", "show", "networks", "mode=bssid"]))


# ------------------------------------------------------------------ Linux
def _split_terse(line: str) -> List[str]:
    parts, buf, i = [], "", 0
    while i < len(line):
        c = line[i]
        if c == "\\" and i + 1 < len(line):
            buf += line[i + 1]
            i += 2
            continue
        if c == ":":
            parts.append(buf)
            buf = ""
        else:
            buf += c
        i += 1
    parts.append(buf)
    return parts


def parse_nmcli(text: str) -> List[Network]:
    nets = []
    for line in text.splitlines():
        f = _split_terse(line)
        if len(f) < 6:
            continue
        ssid, bssid, sig, chan, freq, sec = f[:6]
        try:
            pct = int(sig)
        except ValueError:
            continue
        mhz = int(re.sub(r"\D", "", freq) or 0)
        nets.append(Network(
            ssid=ssid or "<hidden>", bssid=bssid, signal_pct=pct,
            dbm=pct_to_dbm(pct), channel=chan,
            band=_band_from_freq(mhz) if mhz else _band_from_channel(chan),
            security=sec or "Open"))
    return nets


def _scan_linux() -> List[Network]:
    out = _run(["nmcli", "-t", "-f", "SSID,BSSID,SIGNAL,CHAN,FREQ,SECURITY",
                "dev", "wifi", "list", "--rescan", "yes"])
    return parse_nmcli(out)


# ------------------------------------------------------------------ macOS
def parse_system_profiler(text: str) -> List[Network]:
    try:
        data = json.loads(text)
    except json.JSONDecodeError:
        raise ScanError("Could not parse system_profiler output")
    nets = []
    for entry in data.get("SPAirPortDataType", []):
        for iface in entry.get("spairport_airport_interfaces", []):
            items = list(iface.get("spairport_airport_other_local_wireless_networks", []))
            cur = iface.get("spairport_current_network_information")
            if cur:
                items.insert(0, cur)
            for n in items:
                m = re.search(r"(-\d+)\s*dBm", n.get("spairport_signal_noise", ""))
                dbm = int(m.group(1)) if m else None
                chan_s = str(n.get("spairport_network_channel", ""))
                cm = re.match(r"(\d+)", chan_s)
                bm = re.search(r"(\d(?:\.\d)?)\s*GHz", chan_s)
                sec = n.get("spairport_security_mode", "")
                sec = sec.replace("spairport_security_mode_", "").replace("_", " ")
                name = n.get("_name", "")
                if not name or "redacted" in name.lower():
                    name = "<hidden / location access needed>"
                nets.append(Network(
                    ssid=name, signal_pct=dbm_to_pct(dbm) if dbm is not None else 0,
                    dbm=dbm, channel=cm.group(1) if cm else "",
                    band=f"{bm.group(1)} GHz" if bm else "", security=sec))
    return nets


def _scan_macos() -> List[Network]:
    out = _run(["system_profiler", "SPAirPortDataType", "-json"], timeout=60)
    return parse_system_profiler(out)


# ------------------------------------------------------------------ API
def scan() -> List[Network]:
    system = platform.system()
    if system == "Windows":
        nets = _scan_windows()
    elif system == "Linux":
        nets = _scan_linux()
    elif system == "Darwin":
        nets = _scan_macos()
    else:
        raise ScanError(f"Unsuppo

import CoreWLAN
import Foundation

// Wi-Fi analyzer: lists nearby networks, strongest first.
// Run with:  swift wifi_analyzer.swift

func quality(_ rssi: Int) -> String {
    switch rssi {
    case -50...0: return "Excellent"
    case -60..<(-50): return "Good"
    case -70..<(-60): return "Fair"
    default: return "Weak"
    }
}

func bar(_ rssi: Int) -> String {
    // Map -100 dBm...-30 dBm onto 0...10 blocks
    let clamped = max(-100, min(-30, rssi))
    let filled = Int(round(Double(clamped + 100) / 70.0 * 10.0))
    return String(repeating: "█", count: filled) + String(repeating: "░", count: 10 - filled)
}

func band(_ channel: CWChannel?) -> String {
    switch channel?.channelBand {
    case .band2GHz?: return "2.4 GHz"
    case .band5GHz?: return "5 GHz"
    case .band6GHz?: return "6 GHz"
    default: return "?"
    }
}

func pad(_ s: String, _ n: Int) -> String {
    s.count >= n ? String(s.prefix(n)) : s + String(repeating: " ", count: n - s.count)
}

