#!/usr/bin/env python3
"""Scientific calculator with persistent history (Tkinter, stdlib only)."""
import ast
import json
import math
import operator
import re
import tkinter as tk
from pathlib import Path
from tkinter import ttk

HISTORY_FILE = Path.home() / ".sci_calc_history.json"
MAX_HISTORY = 200

BIN_OPS = {
    ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul,
    ast.Div: operator.truediv, ast.Pow: operator.pow, ast.Mod: operator.mod,
}
UNARY_OPS = {ast.UAdd: operator.pos, ast.USub: operator.neg}


def build_namespace(degrees, ans):
    to_rad = (lambda x: math.radians(x)) if degrees else (lambda x: x)
    from_rad = (lambda x: math.degrees(x)) if degrees else (lambda x: x)

    def fact(x):
        if x < 0 or x != int(x):
            raise ValueError("factorial needs a non-negative integer")
        return math.factorial(int(x))

    funcs = {
        "sin": lambda x: math.sin(to_rad(x)),
        "cos": lambda x: math.cos(to_rad(x)),
        "tan": lambda x: math.tan(to_rad(x)),
        "asin": lambda x: from_rad(math.asin(x)),
        "acos": lambda x: from_rad(math.acos(x)),
        "atan": lambda x: from_rad(math.atan(x)),
        "sinh": math.sinh, "cosh": math.cosh, "tanh": math.tanh,
        "ln": math.log, "log": math.log10, "sqrt": math.sqrt,
        "abs": abs, "exp": math.exp, "fact": fact,
    }
    consts = {"pi": math.pi, "e": math.e, "ans": ans}
    return funcs, consts


def evaluate(expr, degrees=True, ans=0):
    """Safely evaluate a math expression using a whitelisted AST walk."""
    expr = (expr.replace("×", "*").replace("÷", "/").replace("−", "-")
            .replace("^", "**").replace("π", "pi").replace("√", "sqrt")
            .replace("Ans", "ans"))
    expr = re.sub(r"(\d|\)|pi|ans)\s*(?=[a-zA-Z(])", r"\1*", expr)  # implicit *
    expr = re.sub(r"\)\s*(?=\d)", ")*", expr)
    # Close unbalanced parentheses so "sin(30" still works.
    expr += ")" * max(0, expr.count("(") - expr.count(")"))
    funcs, consts = build_namespace(degrees, ans)

    def walk(n):
        if isinstance(n, ast.Expression):
            return walk(n.body)
        if isinstance(n, ast.Constant) and isinstance(n.value, (int, float)):
            return n.value
        if isinstance(n, ast.BinOp) and type(n.op) in BIN_OPS:
            right = walk(n.right)
            left = walk(n.left)
            if isinstance(n.op, ast.Pow) and abs(right) > 10000:
                raise ValueError("exponent too large")
            return BIN_OPS[type(n.op)](left, right)
        if isinstance(n, ast.UnaryOp) and type(n.op) in UNARY_OPS:
            return UNARY_OPS[type(n.op)](walk(n.operand))
        if isinstance(n, ast.Name) and n.id in consts:
            return consts[n.id]
        if (isinstance(n, ast.Call) and isinstance(n.func, ast.Name)
                and n.func.id in funcs and len(n.args) == 1 and not n.keywords):
            return funcs[n.func.id](walk(n.args[0]))
        raise ValueError("invalid expression")

    try:
        result = walk(ast.parse(expr.strip(), mode="eval"))
    except ZeroDivisionError:
        raise ValueError("division by zero")
    except OverflowError:
        raise ValueError("result too large")
    except SyntaxError:
        raise ValueError("syntax error")
    if isinstance(result, complex):
        raise ValueError("complex result")
    return result


def fmt(x):
    if isinstance(x, int) and abs(x) < 10**15:
        return str(x)
    if isinstance(x, float) and x.is_integer() and abs(x) < 1e15:
        return str(int(x))
    return format(x, ".12g")


