#!/usr/bin/env python3
"""Scientific calculator with history. Pure standard library (tkinter)."""
import ast
import json
import math
import operator
import tkinter as tk
from pathlib import Path
from tkinter import messagebox

HISTORY_FILE = Path.home() / ".sci_calc_history.json"
MAX_HISTORY = 200

BIN_OPS = {
    ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul,
    ast.Div: operator.truediv, ast.Mod: operator.mod, ast.Pow: operator.pow,
    ast.FloorDiv: operator.floordiv,
}
UNARY_OPS = {ast.UAdd: operator.pos, ast.USub: operator.neg}


def _fact(x):
    if x != int(x) or x < 0 or x > 1000:
        raise ValueError("factorial domain")
    return math.factorial(int(x))


def build_env(degrees):
    """Names available to expressions."""
    to_rad = (lambda x: math.radians(x)) if degrees else (lambda x: x)
    from_rad = (lambda x: math.degrees(x)) if degrees else (lambda x: x)
    funcs = {
        "sin": lambda x: math.sin(to_rad(x)),
        "cos": lambda x: math.cos(to_rad(x)),
        "tan": lambda x: math.tan(to_rad(x)),
        "asin": lambda x: from_rad(math.asin(x)),
        "acos": lambda x: from_rad(math.acos(x)),
        "atan": lambda x: from_rad(math.atan(x)),
        "sinh": math.sinh, "cosh": math.cosh, "tanh": math.tanh,
        "ln": math.log, "log": math.log10, "exp": math.exp,
        "sqrt": math.sqrt, "cbrt": math.cbrt if hasattr(math, "cbrt") else (lambda x: math.copysign(abs(x) ** (1 / 3), x)),
        "abs": abs, "fact": _fact,
    }
    return funcs, {"pi": math.pi, "e": math.e}


def safe_eval(expr, degrees=True, ans=0):
    funcs, consts = build_env(degrees)
    consts["ans"] = ans
    expr = (expr.replace("×", "*").replace("÷", "/").replace("−", "-")
            .replace("^", "**").replace("π", "pi").replace("√", "sqrt"))
    expr = expr.replace("!", "")  # factorial is used as fact(x)

    def ev(n):
        if isinstance(n, ast.Expression):
            return ev(n.body)
        if isinstance(n, ast.Constant) and isinstance(n.value, (int, float)):
            return n.value
        if isinstance(n, ast.BinOp) and type(n.op) in BIN_OPS:
            l, r = ev(n.left), ev(n.right)
            if isinstance(n.op, ast.Pow) and abs(r) > 10000:
                raise ValueError("exponent too large")
            return BIN_OPS[type(n.op)](l, r)
        if isinstance(n, ast.UnaryOp) and type(n.op) in UNARY_OPS:
            return UNARY_OPS[type(n.op)](ev(n.operand))
        if isinstance(n, ast.Name) and n.id in consts:
            return consts[n.id]
        if (isinstance(n, ast.Call) and isinstance(n.func, ast.Name)
                and n.func.id in funcs and len(n.args) == 1 and not n.keywords):
            return funcs[n.func.id](ev(n.args[0]))
        raise ValueError("invalid expression")

    result = ev(ast.parse(expr.strip(), mode="eval"))
    if isinstance(result, complex):
        raise ValueError("complex result")
    return result


def fmt(x):
    if isinstance(x, int):
        return str(x)
    if x == int(x) and abs(x) < 1e15:
        return str(int(x))
    return f"{x:.12g}"


class Calculator(tk.Tk):
