#!/usr/bin/env python3
"""Scientific calculator with history. Pure stdlib (tkinter), no eval."""
import json
import math
import os
import re
import tkinter as tk
from tkinter import ttk

HISTORY_FILE = os.path.join(os.path.expanduser("~"), ".sci_calc_history.json")
HISTORY_MAX = 200

TOKEN_RE = re.compile(r"\s*(?:(\d+\.?\d*(?:[eE][+-]?\d+)?|\.\d+(?:[eE][+-]?\d+)?)|([A-Za-z_]\w*)|(.))")


class CalcError(Exception):
    pass


class Evaluator:
    """Recursive-descent parser: + - * / ^ ! % unary-minus, functions, constants."""

    def __init__(self, degrees=False, ans=0.0):
        self.deg = degrees
        self.ans = ans

    def _to_rad(self, x):
        return math.radians(x) if self.deg else x

    def _from_rad(self, x):
        return math.degrees(x) if self.deg else x

    def funcs(self):
        return {
            "sin": lambda x: math.sin(self._to_rad(x)),
            "cos": lambda x: math.cos(self._to_rad(x)),
            "tan": lambda x: math.tan(self._to_rad(x)),
            "asin": lambda x: self._from_rad(math.asin(x)),
            "acos": lambda x: self._from_rad(math.acos(x)),
            "atan": lambda x: self._from_rad(math.atan(x)),
            "sinh": math.sinh, "cosh": math.cosh, "tanh": math.tanh,
            "ln": math.log, "log": math.log10, "log2": math.log2,
            "sqrt": math.sqrt, "cbrt": math.cbrt, "abs": abs, "exp": math.exp,
            "fact": self._fact, "floor": math.floor, "ceil": math.ceil,
        }

    @staticmethod
    def _fact(x):
        if x < 0 or x != int(x):
            raise CalcError("factorial needs a non-negative integer")
        if x > 1000:
            raise CalcError("factorial too large")
        return float(math.factorial(int(x)))

    def evaluate(self, text):
        self.toks = []
        pos = 0
        text = text.strip()
        while pos < len(text):
            m = TOKEN_RE.match(text, pos)
            if not m:
                break
            pos = m.end()
            if m.group(1):
                self.toks.append(("num", float(m.group(1))))
            elif m.group(2):
                self.toks.append(("id", m.group(2).lower()))
            else:
                ch = m.group(3)
                ch = {"×": "*", "÷": "/", "−": "-", "√": "sqrt", "π": "pi"}.get(ch, ch)
                self.toks.append(("id" if ch.isalpha() else "op", ch))
        self.i = 0
        if not self.toks:
            raise CalcError("empty expression")
        try:
            v = self.expr()
            if self.i != len(self.toks):
                raise CalcError("unexpected '%s'" % self.toks[self.i][1])
        except ZeroDivisionError:
            raise CalcError("division by zero")
        except OverflowError:
            raise CalcError("overflow")
        except ValueError:
            raise CalcError("math domain error")
        if isinstance(v, complex):
            raise CalcError("complex result")
        return v

    def peek(self):
        return self.toks[self.i] if self.i < len(self.toks) else (None, None)

    def accept(self, op):
        if self.peek() == ("op", op):
            self.i += 1
            return True
        return False

    def expr(self):
        v = self.term()
        while True:
            if self.accept("+"):
                v += self.term()
            elif self.accept("-"):
                v -= self.term()
            else:
                return v

    def term(self):
        v = self.unary()
        while True:
            if self.accept("*"):
                v *= self.unary()
            elif self.accept("/"):
                v /= self.unary()
            elif self.peek()[0] in ("num", "id") or self.peek() == ("op", "("):
                v *= self.unary()  # implicit multiplication: 2pi, 3(4)
            else:
                return v

    def unary(self):
        if self.accept("-"):
            return -self.unary()
        if self.accept("+"):
            return self.unary()
        return self.power()

    def power(self):
        base = self.postfix()
        if self.accept("^") or (self.peek() == ("op", "*") and self._double_star()):
            return base ** self.unary()  # right-assoc, binds looser than unary on rhs
        return base

    def _double_star(self):
        if self.i + 1 < len(self.toks) and self.toks[self.i + 1] == ("op", "*"):
            self.i += 2
            return True
        return False

    def postfix(self):
        v = self.atom()
        while True:
            if self.accept("!"):
                v = self._fact(v)
            elif self.accept("%"):
                v /= 100.0
            else:
                return v

    def atom(self):
        kind, val = self.peek()
        if kind == "num":
            self.i += 1
            return val
        if kind == "id":
            self.i += 1
            consts = {"pi": math.pi, "e": math.e, "ans": self.ans, "tau": math.tau}
            if val in consts:
                return consts[val]
            f = self.funcs().get(val)
            if not f:
                raise CalcError("unknown name '%s'" % val)
            if self.accept("("):
                arg = self.expr()
                if not self.accept(")"):
                    raise CalcError("missing ')'")
            else:
                arg = self.unary()  # allow `sin 30`
            return f(arg)
        if self.accept("("):
            v = self.expr()
            if not self.accept(")"):
                raise CalcError("missing ')'")
            return v
        raise CalcError("unexpected end" if kind is None else "unexpected '%s'" % val)


