    0: "Queued", 1: "Checking", 2: "Getting info", 3: "Downloading",
    4: "Finished", 5: "Seeding", 6: "Allocating", 7: "Checking",
}


def save_state():
    data = [{"source": e["source"], "priorities": e["priorities"]} for e in entries]
    with open(STATE_FILE, "w") as f:
        json.dump(data, f)


def start_torrent(source):
    if source["kind"] == "magnet":
        params = lt.parse_magnet_uri(source["value"])
    else:
        params = lt.add_torrent_params()
        params.ti = lt.torrent_info(source["value"])
    params.save_path = DOWNLOAD_DIR
    return session.add_torrent(params)


def add_entry(source, priorities=None):
    entry = {
        "source": source,
        "priorities": priorities or {},
        "handle": start_torrent(source),
        "applied": False,
    }
    entries.append(entry)
    save_state()


def load_state():
    if not os.path.exists(STATE_FILE):
        return
    try:
        with open(STATE_FILE) as f:
            data = json.load(f)
    except ValueError:
        return
    for item in data:
        try:
            add_entry(item["source"], {int(k): v for k, v in item["priorities"].items()})
        except Exception as exc:
            print("Could not restore a torrent:", exc)


def apply_saved_priorities(entry):
    h = entry["handle"]
    if entry["applied"] or not h.status().has_metadata:
        return
    prios = h.get_file_priorities() if hasattr(h, "get_file_priorities") else h.file_priorities()
    for idx, p in entry["priorities"].items():
        if idx < len(prios):
            prios[idx] = p
    h.prioritize_files(prios)
    entry["applied"] = True


def torrent_summary(i, entry):
    h = entry["handle"]
    st = h.status()
    apply_saved_priorities(entry)
    paused = bool(st.flags & lt.torrent_flags.paused)
    state = "Paused" if paused else STATE_NAMES.get(int(st.state), "Unknown")
    return {
        "id": i,
        "name": st.name or "(fetching name…)",
        "state": state,
        "paused": paused,
        "progress": round(st.progress * 100, 1),
        "down": st.download_rate,
        "up": st.upload_rate,
        "peers": st.num_peers,
        "size": st.total_wanted,
        "has_metadata": st.has_metadata,
        "error": st.errc.message() if st.errc.value() else "",
    }


def torrent_files(entry):
    h = entry["handle"]
    if not h.status().has_metadata:
        return []
    files = h.torrent_file().files()
    prios = h.get_file_priorities() if hasattr(h, "get_file_priorities") else h.file_priorities()
    progress = h.file_progress()
    out = []
    for i in range(files.num_files()):
        size = files.file_size(i)
        out.append({
            "index": i,
            "path": files.file_path(i),
            "size": size,
            "progress": round(progress[i] / size * 100, 1) if size else 100,
            "priority": prios[i],
        })
    return out


