TEMPERATURE_UNITS = ("Celsius", "Fahrenheit", "Kelvin")


def _to_celsius(value, unit):
    if unit == "Celsius":
        return value
    if unit == "Fahrenheit":
        return (value - 32) * 5 / 9
    return value - 273.15


def _from_celsius(value, unit):
    if unit == "Celsius":
        return value
    if unit == "Fahrenheit":
        return value * 9 / 5 + 32
    return value + 273.15


def categories():
    return list(LINEAR_UNITS) + ["Temperature", "Currency"]


def units_for(category):
    if category == "Temperature":
        return list(TEMPERATURE_UNITS)
    return list(LINEAR_UNITS[category])


def convert_unit(category, value, from_unit, to_unit):
    if category == "Temperature":
        celsius = _to_celsius(value, from_unit)
        if from_unit == "Kelvin" and value < 0 or celsius < -273.15 - 1e-9:
            raise ValueError("Temperature is below absolute zero")
        return _from_celsius(celsius, to_unit)
    table = LINEAR_UNITS[category]
    return value * table[from_unit] / table[to_unit]


