RATES_URL = "https://open.er-api.com/v6/latest/USD"
CACHE_FILE = Path.home() / ".unit_currency_converter_rates.json"
CACHE_MAX_AGE = 6 * 3600

# Approximate fallback rates (per 1 USD) used only if no network and no cache.
FALLBACK_RATES = {
    "USD": 1.0, "EUR": 0.92, "GBP": 0.78, "JPY": 150.0, "CHF": 0.88,
    "CAD": 1.36, "AUD": 1.52, "CNY": 7.2, "INR": 83.0, "UAH": 40.0,
    "PLN": 4.0, "SEK": 10.5, "NOK": 10.7, "MXN": 17.0, "BRL": 5.0,
}


class CurrencyRates:
    """Rates relative to USD. `source` describes where they came from."""

    def __init__(self):
        self.rates = dict(FALLBACK_RATES)
        self.source = "built-in approximate rates (offline)"

    def load(self, force_refresh=False):
        """Load rates from fresh cache, then network, then stale cache."""
        cached = self._read_cache()
        if cached and not force_refresh and time.time() - cached["time"] < CACHE_MAX_AGE:
            self._apply(cached, "cached")
            return
        try:
            req = urllib.request.Request(RATES_URL, headers={"User-Agent": "unit-currency-converter"})
            with urllib.request.urlopen(req, timeout=10) as resp:
                data = json.load(resp)
            if data.get("result") != "success":
                raise ValueError("bad response")
            fresh = {"time": time.time(), "rates": data["rates"]}
            self._apply(fresh, "live")
            try:
                CACHE_FILE.write_text(json.dumps(fresh))
            except OSError:
                pass
        except Exception:
            if cached:
                self._apply(cached, "stale cache")

    def _read_cache(self):
        try:
            data = json.loads(CACHE_FILE.read_text())
            if isinstance(data.get("rates"), dict) and "time" in data:
                return data
        except (OSError, ValueError):
            pass
        return None

    def _apply(self, data, label):
        self.rates = data["rates"]
        stamp = time.strftime("%Y-%m-%d %H:%M", time.localtime(data["time"]))
        self.source = f"{label} rates, fetched {stamp}"

    def codes(self):
        return sorted(self.rates)

    def convert(self, value, from_code, to_code):
        return value / self.rates[from_code] * self.rates[to_code]

"""Encrypted vault storage: scrypt key derivation + AES-256-GCM."""
import base64
import json
import os
import secrets
import string
import tempfile

from cryptography.exceptions import InvalidTag
from cryptography.hazmat.primitives.ciphers.aead import AESGCM
from cryptography.hazmat.primitives.kdf.scrypt import Scrypt

MAGIC = "pwvault"
VERSION = 1
KDF_N, KDF_R, KDF_P = 2**15, 8, 1


class WrongPassword(Exception):
    pass


class CorruptVault(Exception):
    pass


def _b64e(b: bytes) -> str:
    return base64.b64encode(b).decode("ascii")


def _b64d(s: str) -> bytes:
    return base64.b64decode(s.encode("ascii"))


def _derive(password: str, salt: bytes, n: int, r: int, p: int) -> bytes:
    return Scrypt(salt=salt, length=32, n=n, r=r, p=p).derive(password.encode("utf-8"))


def generate_password(length=20, symbols=True) -> str:
    alphabet = string.ascii_letters + string.digits + ("!@#$%^&*()-_=+[]{};:,.?" if symbols else "")
    while True:
        pw = "".join(secrets.choice(alphabet) for _ in range(length))
        if (any(c.islower() for c in pw) and any(c.isupper() for c in pw)
                and any(c.isdigit() for c in pw)):
            return pw


class Vault:
    """Holds decrypted entries in memory; the derived key is kept so saves are fast."""

    def __init__(self, path: str):
        self.path = path
        self.entries: list[dict] = []
        self._key: bytes | None = None
        self._salt: bytes | None = None

    @staticmethod
    def exists(path: str) -> bool:
        return os.path.isfile(path)

    def create(self, password: str):
        self._salt = os.urandom(16)
        self._key = _derive(password, self._salt, KDF_N, KDF_R, KDF_P)
        self.entries = []
        self.save()

    def unlock(self, password: str):
        try:
            with open(self.path, "r", encoding="utf-8") as f:
                doc = json.load(f)
            if doc.get("magic") != MAGIC:
                raise CorruptVault("Not a vault file")
            kdf = doc["kdf"]
            salt = _b64d(kdf["salt"])
            key = _derive(password, salt, kdf["n"], kdf["r"], kdf["p"])
            blob = _b64d(doc["data"])
            nonce, ct = blob[:12], blob[12:]
            plain = AESGCM(key).decrypt(nonce, ct, self._aad(doc))
        except InvalidTag:
            raise WrongPassword()
        except (KeyError, ValueError, json.JSONDecodeError):
            raise CorruptVault("Vault file is damaged")
        self._salt, self._key = salt, key
        self.entries = json.loads(plain)["entries"]

    @staticmethod
    def _aad(doc: dict) -> bytes:
        # Bind header (version + KDF params) to the ciphertext.
        return json.dumps({"magic": doc["magic"], "version": doc["version"], "kdf": doc["kdf"]},
                          sort_keys=True).encode()

    def save(self):
        doc = {
            "magic": MAGIC,
            "version": VERSION,
            "kdf": {"name": "scrypt", "n": KDF_N, "r": KDF_R, "p": KDF_P, "salt": _b64e(self._salt)},
        }
        nonce = os.urandom(12)
        plain = json.dumps({"entries": self.entries}).encode()
        ct = AESGCM(self._key).encrypt(nonce, plain, self._aad(doc))
        doc["data"] = _b64e(nonce + ct)
        d = os.path.dirname(os.path.abspath(self.path))
        fd, tmp = tempfile.mkstemp(dir=d, prefix=".vault-")
        try:
            with os.fdopen(fd, "w", encoding="utf-8") as f:
                json.dump(doc, f)
                f.flush()
                os.fsync(f.fileno())
            os.chmod(tmp, 0o600)
            os.replace(tmp, self.path)  # atomic: never leaves a half-written vault
        except BaseException:
            if os.path.exists(tmp):
                os.remove(tmp)
            raise

    def change_password(self, new_password: str):
        self._salt = os.urandom(16)
        self._key = _derive(new_password, self._salt, KDF_N, KDF_R, KDF_P)
        self.save()

    def lock(self):
        self._key = None
        self.entries = []

#!/usr/bin/env python3
"""A simple password manager. Entries are stored in an encrypted local file.

Setup (once):   pip3 install cryptography
Run:            python3 password_manager.py
"""

import base64
import getpass
import hashlib
import json
import os
import secrets
import string
import subprocess
import sys
from pathlib import Path

try:
    from cryptography.fernet import Fernet, InvalidToken
except ImportError:
    sys.exit("Missing a required package. Run this once:  pip3 install cryptography")

VAULT_FILE = Path(__file__).resolve().parent / "vault.enc"
SALT_SIZE = 16


def derive_key(master_password, salt):
    raw = hashlib.scrypt(
        master_password.encode("utf-8"),
        salt=salt,
        n=2**15,
        r=8,
        p=1,
        maxmem=128 * 1024 * 1024,
        dklen=32,
    )
    return base64.urlsafe_b64encode(raw)


def save_vault(entries, master_password, salt):
    token = Fernet(derive_key(master_password, salt)).encrypt(
        json.dumps(entries).encode("utf-8")
    )
    tmp = VAULT_FILE.with_suffix(".tmp")
    tmp.write_bytes(salt + token)
    os.chmod(tmp, 0o600)
    tmp.replace(VAULT_FILE)  # replace in one step so a crash can't corrupt the vault


def load_vault(master_password):
    data = VAULT_FILE.read_bytes()
    salt, token = data[:SALT_SIZE], data[SALT_SIZE:]
    plain = Fernet(derive_key(master_password, salt)).decrypt(token)
    return json.loads(plain), salt


def generate_password(length=20):
    alphabet = string.ascii_letters + string.digits + "!@#$%^&*-_=+?"
    while True:
        pw = "".join(secrets.choice(alphabet) for _ in range(length))
        if (any(c.islower() for c in pw) and any(c.isupper() for c in pw)
                and any(c.isdigit() for c in pw) and any(c in "!@#$%^&*-_=+?" for c in pw)):
            return pw


def copy_to_clipboard(text):
    for cmd in (["pbcopy"], ["clip"], ["xclip", "-selection", "clipboard"]):
        try:
            subprocess.run(cmd, input=text.encode(), check=True)
            return True
        except (FileNotFoundError, subprocess.CalledProcessError):
            continue
    return False


def clear_clipboard():
    copy_to_clipboard("")


def unlock():
    if not VAULT_FILE.exists():
        print("No vault found. Let's create one.")
        print("Choose a master password. If you forget it, your data CANNOT be recovered.")
        while True:
            pw = getpass.getpass("New master password: ")
            if len(pw) < 8:
                print("Please use at least 8 characters (a long phrase is best).")
                continue
            if pw != getpass.getpass("Repeat master password: "):
                print("Passwords did not match. Try again.")
                continue
            break
        salt = secrets.token_bytes(SALT_SIZE)
        entries = {}
        save_vault(entries, pw, salt)
        print("Vault created.")
        return entries, pw, salt

    for _ in range(3):
        pw = getpass.getpass("Master password: ")
        try:
            entries, salt = load_vault(pw)
            return entries, pw, salt
        except InvalidToken:
            print("Wrong master password.")
    sys.exit("Too many failed attempts.")


def pick_name(entries, prompt="Entry name: "):
    name = input(prompt).strip()
    if name in entries:
        return name
    matches = [n for n in entries if name.lower() in n.lower()]
    if len(matches) == 1:
