"""Encrypted vault storage: scrypt key derivation + AES-256-GCM, single local file."""
import base64
import json
import os
import secrets
import tempfile
import time
import uuid

from cryptography.exceptions import InvalidTag
from cryptography.hazmat.primitives.ciphers.aead import AESGCM
from cryptography.hazmat.primitives.kdf.scrypt import Scrypt

MAGIC = "pwvault"
VERSION = 1
KDF_PARAMS = {"n": 2 ** 15, "r": 8, "p": 1}


class VaultError(Exception):
    pass


class WrongPassword(VaultError):
    pass


def _b64e(b: bytes) -> str:
    return base64.b64encode(b).decode("ascii")


def _b64d(s: str) -> bytes:
    return base64.b64decode(s.encode("ascii"))


def _derive(password: str, salt: bytes, kdf: dict) -> bytes:
    return Scrypt(salt=salt, length=32, n=kdf["n"], r=kdf["r"], p=kdf["p"]).derive(
        password.encode("utf-8")
    )


def default_path() -> str:
    if os.name == "nt":
        base = os.environ.get("APPDATA") or os.path.expanduser("~")
    elif os.uname().sysname == "Darwin":
        base = os.path.expanduser("~/Library/Application Support")
    else:
        base = os.environ.get("XDG_DATA_HOME") or os.path.expanduser("~/.local/share")
    return os.path.join(base, "PyPasswordManager", "vault.pwv")


class Vault:
    def __init__(self, path, key, salt, kdf, entries):
        self.path = path
        self._key = key
        self._salt = salt
        self._kdf = kdf
        self.entries = entries

    # --- lifecycle -------------------------------------------------------
    @classmethod
    def create(cls, path: str, password: str) -> "Vault":
        if os.path.exists(path):
            raise VaultError("A vault already exists at this location.")
        salt = secrets.token_bytes(16)
        kdf = dict(KDF_PARAMS)
        vault = cls(path, _derive(password, salt, kdf), salt, kdf, [])
        vault.save()
        return vault

    @classmethod
    def open(cls, path: str, password: str) -> "Vault":
        try:
            with open(path, "r", encoding="utf-8") as f:
                doc = json.load(f)
            if doc.get("magic") != MAGIC:
                raise ValueError
            salt = _b64d(doc["salt"])
            kdf = doc["kdf"]
            nonce = _b64d(doc["nonce"])
            ct = _b64d(doc["ciphertext"])
        except (OSError, ValueError, KeyError, TypeError) as e:
            raise VaultError("Not a valid vault file.") from e
        if not (isinstance(kdf, dict) and all(isinstance(kdf.get(k), int) for k in "nrp")):
            raise VaultError("Not a valid vault file.")
        # Guard against absurd cost parameters in a tampered file.
        if kdf["n"] > 2 ** 22 or kdf["n"] < 2 ** 14 or kdf["r"] > 16 or kdf["p"] > 4:
            raise VaultError("Unsupported key derivation parameters.")
        key = _derive(password, salt, kdf)
        try:
            plain = AESGCM(key).decrypt(nonce, ct, cls._aad(doc["version"], salt, kdf))
        except InvalidTag:
            raise WrongPassword("Wrong master password, or the file was modified.")
        return cls(path, key, salt, kdf, json.loads(plain)["entries"])

    @staticmethod
    def _aad(version, salt, kdf) -> bytes:
        return json.dumps(
            {"magic": MAGIC, "version": version, "salt": _b64e(salt), "kdf": kdf},
            sort_keys=True,
        ).encode()

    def save(self):
        nonce = secrets.token_bytes(12)  # fresh nonce on every save
        plain = json.dumps({"entries": self.entries}).encode("utf-8")
        ct = AESGCM(self._key).encrypt(nonce, plain, self._aad(VERSION, self._salt, self._kdf))
        doc = {
            "magic": MAGIC,
            "version": VERSION,
            "kdf": self._kdf,
            "salt": _b64e(self._salt),
            "nonce": _b64e(nonce),
            "ciphertext": _b64e(ct),
        }
        directory = os.path.dirname(os.path.abspath(self.path))
        os.makedirs(directory, exist_ok=True)
        fd, tmp = tempfile.mkstemp(dir=directory, prefix=".vault-")
        try:
            with os.fdopen(fd, "w", encoding="utf-8") as f:
                json.dump(doc, f)
                f.flush()
                os.fsync(f.fileno())
            try:
                os.chmod(tmp, 0o600)
            except OSError:
                pass
            os.replace(tmp, self.path)  # atomic on all platforms
        except BaseException:
            if os.path.exists(tmp):
                os.remove(tmp)
            raise

    def change_password(self, new_password: str):
        self._salt = secrets.token_bytes(16)
        self._kdf = dict(KDF_PARAMS)
        self._key = _derive(new_password, self._salt, self._kdf)
        self.save()

    def lock(self):
        self._key = None
        self.entries = []

    # --- entries ---------------------------------------------------------
    def upsert(self, entry: dict) -> dict:
        entry = dict(entry)
        entry.setdefault("id", uuid.uuid4().hex)
        entry["updated"] = int(time.time())
        for i, e in enumerate(self.entries):
            if e["id"] == entry["id"]:
                self.entries[i] = entry
                break
        else:
            self.entries.append(entry)
        self.save()
        return entry

    def delete(self, entry_id: str):
        self.entries = [e for e in self.entries if e["id"] != entry_id]
        self.save()


def generate_password(length=20, symbols=True) -> str:
    import string

    alphabet = string.ascii_letters + string.digits + ("!@#$%^&*()-_=+[]{}" if symbols else "")
    while True:
        pw = "".join(secrets.choice(alphabet) for _ in range(length))
        if (
            any(c.islower() for c in pw)
            and any(c.isupper() for c in pw)
            and any(c.isdigit() for c in pw)
            and (not symbols or any(not c.isalnum() for c in pw))
        ):
            return pw

"""Encrypted vault storage: scrypt key derivation + AES-256-GCM.

File layout: MAGIC(4) | log2n(1) | r(1) | p(1) | salt(16) | nonce(12) | ciphertext+tag
The header (everything before the nonce) is authenticated as AAD.
"""
import hashlib
import json
import os
import secrets
import tempfile
import time

MAGIC = b"PMV1"
LOG2N, R, P = 15, 8, 1  # ~32 MB transient memory, only during unlock/create
MAX_LOG2N = 16
HEADER_LEN = 4 + 3 + 16
NONCE_LEN = 12


class VaultError(Exception):
    pass


def _derive(password, salt, log2n, r, p):
    return hashlib.scrypt(
        password.encode("utf-8"), salt=salt, n=1 << log2n, r=r, p=p,
        maxmem=192 * 1024 * 1024, dklen=32,
    )


def _aes():
    from cryptography.hazmat.primitives.ciphers.aead import AESGCM  # lazy: faster startup
    return AESGCM


class Vault:
    def __init__(self, path):
        self.path = path
        self.entries = []
        self._key = None
        self._header = None

    @staticmethod
    def exists(path):
        return os.path.isfile(path)

    @classmethod
    def create(cls, path, password):
        if os.path.exists(path):
            raise VaultError("Vault file already exists.")
        v = cls(path)
        salt = secrets.token_bytes(16)
        v._header = MAGIC + bytes([LOG2N, R, P]) + salt
        v._key = _derive(password, salt, LOG2N, R, P)
        v.save()
        return v

    @classmethod
    def open(cls, path, password):
        with open(path, "rb") as f:
            blob = f.read()
        if len(blob) < HEADER_LEN + NONCE_LEN + 16 or blob[:4] != MAGIC:
            raise VaultError("Not a valid vault file.")
        log2n, r, p = blob[4], blob[5], blob[6]
        if not (10 <= log2n <= MAX_LOG2N and 1 <= r <= 16 and 1 <= p <= 4):
            raise VaultError("Unsupported key-derivation parameters.")
        header = blob[:HEADER_LEN]
        nonce = blob[HEADER_LEN:HEADER_LEN + NONCE_LEN]
        ct = blob[HEADER_LEN + NONCE_LEN:]
        key = _derive(password, header[7:], log2n, r, p)
        try:
            data = _aes()(key).decrypt(nonce, ct, header)
        except Exception:
            raise VaultError("Wrong password or corrupted vault.") from None
        v = cls(path)
        v._key, v._header = key, header
        v.entries = json.loads(data)["entries"]
        return v

    def save(self):
        nonce = secrets.token_bytes(NONCE_LEN)
        plain = json.dumps({"entries": self.entries}, separators=(",", ":")).encode()
        blob = self._header + nonce + _aes()(self._key).encrypt(nonce, plain, self._header)
        d = os.path.dirname(self.path) or "."
        os.makedirs(d, mode=0o700, exist_ok=True)
        fd, tmp = tempfile.mkstemp(dir=d, prefix=".vault-")
        try:
            with os.fdopen(fd, "wb") as f:
                f.write(blob)
                f.flush()
                os.fsync(f.fileno())
            os.chmod(tmp, 0o600)
            os.replace(tmp, self.path)  # atomic: no half-written vault
        except BaseException:
            if os.path.exists(tmp):
                os.remove(tmp)
            raise

    def lock(self):
        self._key = None
        self.entries = []

    # entry helpers
    def upsert(self, entry):
        entry["modified"] = int(time.time())
        for i, e in enumerate(self.entries):
            if e["id"] == entry["id"]:
                self.entries[i] = entry
                break
        else:
            self.entries.append(entry)
        self.save()

    def delete(self, entry_id):
        self.entries = [e for e in self.entries if e["id"] != entry_id]
        self.save()

    def search(self, text):
        t = text.lower()
        hits = [e for e in self.entries
                if not t or t in e["title"].lower() or t in e["username"].lower() or t in e["url"].lower()]
        return sorted(hits, key=lambda e: e["title"].lower())


def new_entry():
    return {"id": secrets.token_hex(8), "title": "", "username": "", "password": "",
            "url": "", "notes": "", "modified": 0}


def generate_password(length=20, symbols=True):
    import string
    alphabet = string.ascii_letters + string.digits + ("!@#$%^&*-_=+?" if symbols else "")
    while True:
        pw = "".join(secrets.choice(alphabet) for _ in range(length))
        if (any(c.islower() for c in pw) and any(c.isupper() for c in pw)
                and any(c.isdigit() for c in pw)):
            return pw

#!/usr/bin/env python3
"""Password generator with configurable rules.

Run it with:  python3 password_generator.py
Press Enter at any question to accept the default shown in [brackets].
"""

import secrets
import string

AMBIGUOUS = "O0oIl1|`'\""
DEFAULT_SYMBOLS = "!@#$%^&*()-_=+[]{};:,.<>?/"


def ask_int(question, default, minimum=0, maximum=1000):
    while True:
        answer = input(f"{question} [{default}]: ").strip()
        if not answer:
            return default
        if answer.isdigit() and minimum <= int(answer) <= maximum:
            return int(answer)
        print(f"  Please enter a whole number from {minimum} to {maximum}.")


def ask_yes_no(question, default):
    hint = "Y/n" if default else "y/N"
    while True:
        answer = input(f"{question} [{hint}]: ").strip().lower()
        if not answer:
            return default
        if answer in ("y", "yes"):
            return True
        if answer in ("n", "no"):
            return False
        print("  Please answer y or n.")


def ask_rules():
    print("\n--- Password rules ---")
    length = ask_int("Password length", 16, minimum=4, maximum=256)
    count = ask_int("How many passwords to generate", 5, minimum=1, maximum=100)

    pools = []
    if ask_yes_no("Include lowercase letters (a-z)?", True):
        pools.append(string.ascii_lowercase)
    if ask_yes_no("Include uppercase letters (A-Z)?", True):
        pools.append(string.ascii_uppercase)
    if ask_yes_no("Include digits (0-9)?", True):
        pools.append(string.digits)
    if ask_yes_no("Include symbols (!@#$...)?", True):
        pools.append(DEFAULT_SYMBOLS)

    avoid_lookalikes = ask_yes_no("Avoid look-alike characters (O/0, l/1/I, quotes)?", False)
    extra_excluded = input("Any other characters to exclude? (Enter for none): ").strip()
    excluded = set(extra_excluded)
    if avoid_lookalikes:
        excluded |= set(AMBIGUOUS)

    pools = ["".join(c for c in pool if c not in excluded) for pool in pools]
    pools = [pool for pool in pools if pool]

    if not pools:
        print("\nNo characters left to use. Please try again with different rules.")
        return None
    if length < len(pools):
        print("\nThe password is too short to include every selected type. Try again.")
        return None

    no_repeats = ask_yes_no("Forbid repeated characters?", False)
    if no_repeats and length > len("".join(pools)):
        print("\nNot enough distinct characters available for that length. Try again.")
        return None

    return length, count, pools, no_repeats


def generate(length, pools, no_repeats):
    """Build one password containing at least one character from every pool."""
    all_chars = "".join(pools)
    chars = []

    # Guarantee one character from each selected type.
    for pool in pools:
        choices = [c for c in pool if not (no_repeats and c in chars)]
        chars.append(secrets.choice(choices))

    # Fill the rest from everything allowed.
    while len(chars) < length:
        c = secrets.choice(all_chars)
        if no_repeats and c in chars:
            continue
        chars.append(c)

    # Shuffle so the guaranteed characters aren't always at the start.
    secrets.SystemRandom().shuffle(chars)
    return "".join(chars)


def main():
    print("=== Password Generator ===")
    while True:
        rules = ask_rules()
        if rules:
            length, count, pools, no_repeats = rules
            print("\nYour passwords:\n")
            for _ in range(count):
                print("  " + generate(length, pools, no_repeats))
            print()
        if not ask_yes_no("Generate more with new rules?", False):
            break
    print("Done. Goodbye!")


if __name__ == "__main__":
    try:
        main()
    except (KeyboardInterrupt, EOFError):
        print("\nGoodbye!")

