"""GUI-independent QR generation and decoding."""
from __future__ import annotations

import io

import cv2
import numpy as np
import qrcode
from qrcode.constants import ERROR_CORRECT_H, ERROR_CORRECT_L, ERROR_CORRECT_M, ERROR_CORRECT_Q
from qrcode.image.svg import SvgPathImage
from PIL import Image

ERROR_LEVELS = {
    "L (7%)": ERROR_CORRECT_L,
    "M (15%)": ERROR_CORRECT_M,
    "Q (25%)": ERROR_CORRECT_Q,
    "H (30%)": ERROR_CORRECT_H,
}


def _build(text: str, error: int, border: int) -> qrcode.QRCode:
    qr = qrcode.QRCode(error_correction=error, border=border, box_size=10)
    qr.add_data(text)
    qr.make(fit=True)
    return qr


def generate_image(text: str, error: int = ERROR_CORRECT_M, border: int = 4,
                   fill: str = "#000000", back: str = "#ffffff", scale: int = 10) -> Image.Image:
    """Render a QR code as an RGB PIL image. `scale` is pixels per module."""
    qr = _build(text, error, border)
    qr.box_size = scale
    return qr.make_image(fill_color=fill, back_color=back).convert("RGB")


def generate_svg(text: str, error: int = ERROR_CORRECT_M, border: int = 4) -> bytes:
    qr = _build(text, error, border)
    buf = io.BytesIO()
    qr.make_image(image_factory=SvgPathImage).save(buf)
    return buf.getvalue()


def decode_image(image: Image.Image | np.ndarray) -> list[str]:
    """Return every QR payload found in the image (empty list if none).

    Accepts a PIL image or a BGR/gray numpy array (e.g. a camera frame).
    """
    if isinstance(image, Image.Image):
        arr = cv2.cvtColor(np.array(image.convert("RGB")), cv2.COLOR_RGB2BGR)
    else:
        arr = image
    gray = cv2.cvtColor(arr, cv2.COLOR_BGR2GRAY) if arr.ndim == 3 else arr

    detector = cv2.QRCodeDetector()
    # Retry with a quiet-zone pad and different scales; detection is finicky.
    padded = cv2.copyMakeBorder(gray, 40, 40, 40, 40, cv2.BORDER_CONSTANT, value=255)
    for factor in (1.0, 2.0, 0.5):
        img = padded if factor == 1.0 else cv2.resize(
            padded, None, fx=factor, fy=factor, interpolation=cv2.INTER_CUBIC)
        results = _try_detect(detector, img)
        if results:
            return results
    return []


def _try_detect(detector: cv2.QRCodeDetector, img: np.ndarray) -> list[str]:
    try:
        ok, texts, _, _ = detector.detectAndDecodeMulti(img)
        if ok:
            found = [t for t in texts if t]
            if found:
                return found
    except cv2.error:
        pass
    try:
        text, _, _ = detector.detectAndDecode(img)
        if text:
            return [text]
    except cv2.error:
        pass
    return []

