    private let stopButton = NSButton(title: "Stop", target: nil, action: nil)
    private let voicePopup = NSPopUpButton(frame: .zero, pullsDown: false)
    private let rateSlider = NSSlider(value: Double(AVSpeechUtteranceDefaultSpeechRate),
                                      minValue: Double(AVSpeechUtteranceMinimumSpeechRate),
                                      maxValue: Double(AVSpeechUtteranceMaximumSpeechRate),
                                      target: nil, action: nil)
    private var voices: [AVSpeechSynthesisVoice] = []
    private var spokenOffset = 0          // UTF-16 offset of the utterance within the text view
    private var highlighted: NSRange?

    func applicationDidFinishLaunching(_ notification: Notification) {
        buildMenu()
        buildWindow()
        loadVoices()
        synth.delegate = self
        NSApp.activate(ignoringOtherApps: true)
    }

    func application(_ sender: NSApplication, openFile filename: String) -> Bool {
        load(URL(fileURLWithPath: filename))
        return true
    }

    func applicationShouldTerminateAfterLastWindowClosed(_ sender: NSApplication) -> Bool { true }

    // MARK: UI

    private func buildMenu() {
        let main = NSMenu()
        func add(_ menu: NSMenu, _ title: String, _ action: Selector?, _ key: String,
                 target: AnyObject? = nil) {
            let item = NSMenuItem(title: title, action: action, keyEquivalent: key)
            item.target = target
            menu.addItem(item)
        }
        func submenu(_ title: String) -> NSMenu {
            let item = NSMenuItem(); main.addItem(item)
            let m = NSMenu(title: title); item.submenu = m
            return m
        }
        let app = submenu("Reader")
        add(app, "Quit Reader", #selector(NSApplication.terminate(_:)), "q")
        let file = submenu("File")
        add(file, "Open…", #selector(openDocument), "o", target: self)
        add(file, "Play / Pause", #selector(togglePlay), " ", target: self)
        let edit = submenu("Edit")
        add(edit, "Cut", #selector(NSText.cut(_:)), "x")
        add(edit, "Copy", #selector(NSText.copy(_:)), "c")
        add(edit, "Paste", #selector(NSText.paste(_:)), "v")
        add(edit, "Select All", #selector(NSText.selectAll(_:)), "a")
        NSApp.mainMenu = main
    }

    private func buildWindow() {
        window.title = "Reader"
        window.isReleasedWhenClosed = false

        let scroll = NSScrollView()
        scroll.hasVerticalScroller = true
        scroll.documentView = textView
        textView.autoresizingMask = [.width]
        textView.isVerticallyResizable = true
        textView.textContainerInset = NSSize(width: 12, height: 12)
        textView.font = .systemFont(ofSize: 15)
        textView.isRichText = false
        textView.string = "Open a document (⌘O) or paste text here, then press Play.\n"
            + "Playback starts at the cursor, or at the selection if there is one."

        playButton.target = self; playButton.action = #selector(togglePlay)
        stopButton.target = self; stopButton.action = #selector(stop)
        rateSlider.target = self; rateSlider.action = #selector(rateChanged)
        rateSlider.widthAnchor.constraint(equalToConstant: 140).isActive = true
        let open = NSButton(title: "Open…", target: self, action: #selector(openDocument))

        let bar = NSStackView(views: [open, playButton, stopButton, voicePopup,
                                      NSTextField(labelWithString: "Speed"), rateSlider])
        bar.spacing = 8
        bar.edgeInsets = NSEdgeInsets(top: 8, left: 12, bottom: 8, right: 12)

        let root = NSStackView(views: [bar, scroll])
        root.orientation = .vertical
        root.spacing = 0
        root.alignment = .leading
        scroll.setContentHuggingPriority(.defaultLow, for: .vertical)
        scroll.widthAnchor.constraint(equalTo: root.widthAnchor).isActive = true

        window.contentView = root
        window.center()
        window.makeKeyAndOrderFront(nil)
    }

    private func loadVoices() {
        let lang = Locale.preferredLanguages.first ?? "en-US"
        let prefix = String(lang.prefix(2))
        voices = AVSpeechSynthesisVoice.speechVoices()
            .filter { $0.language.hasPrefix(prefix) }
            .sorted { $0.quality.rawValue > $1.quality.rawValue }
        voicePopup.removeAllItems()
        voicePopup.addItems(withTitles: voices.map { "\($0.name) (\($0.language))" })
    }

    // MARK: Documents

    @objc private func openDocument() {
        let panel = NSOpenPanel()
        panel.allowedContentTypes = [.plainText, .pdf, .rtf, .html, .text]
            + ["docx", "doc", "odt", "md"].compactMap { UTType(filenameExtension: $0) }
        if panel.runModal() == .OK, let url = panel.url { load(url) }
    }

    private func load(_ url: URL) {
        stop()
        let text: String?
        switch url.pathExtension.lowercased() {
        case "pdf":
            text = PDFDocument(url: url)?.string
        case "rtf", "rtfd", "html", "htm", "doc", "docx", "odt":
            text = try? NSAttributedString(url: url, options: [:], documentAttributes: nil).string
        default:
            var enc = String.Encoding.utf8
            text = (try? String(contentsOf: url, usedEncoding: &enc))

"""Extract plain text from common document formats."""
import os
import re
from html.parser import HTMLParser


class LoadError(Exception):
    pass


def _read_text(path):
    with open(path, "rb") as f:
        raw = f.read()
    for enc in ("utf-8-sig", "utf-16"):
        try:
            return raw.decode(enc)
        except UnicodeError:
            pass
    return raw.decode("latin-1")


class _HTMLText(HTMLParser):
    BLOCK = {"p", "div", "br", "li", "tr", "h1", "h2", "h3", "h4", "h5", "h6"}

    def __init__(self):
        super().__init__()
        self.parts, self._skip = [], 0

    def handle_starttag(self, tag, attrs):
        if tag in ("script", "style"):
            self._skip += 1
        elif tag in self.BLOCK:
            self.parts.append("\n")

    def handle_endtag(self, tag):
        if tag in ("script", "style"):
            self._skip = max(0, self._skip - 1)
        elif tag in self.BLOCK:
            self.parts.append("\n")

    def handle_data(self, data):
        if not self._skip:
            self.parts.append(data)


def _load_html(path):
    p = _HTMLText()
    p.feed(_read_text(path))
    return "".join(p.parts)


def _load_pdf(path):
    try:
        from pypdf import PdfReader
    except ImportError:
        raise LoadError("PDF support needs pypdf:  pip install pypdf")
    try:
        pages = [(pg.extract_text() or "") for pg in PdfReader(path).pages]
    except Exception as e:
        raise LoadError(f"Could not read PDF: {e}")
    text = "\n\n".join(pages)
    if not text.strip():
        raise LoadError("No extractable text (scanned PDFs need OCR).")
    return text


def _load_docx(path):
    try:
        import docx
    except ImportError:
        raise LoadError("DOCX support needs python-docx:  pip install python-docx")
    try:
        return "\n".join(p.text for p in docx.Document(path).paragraphs)
    except Exception as e:
        raise LoadError(f"Could not read DOCX: {e}")


def load_document(path):
    ext = os.path.splitext(path)[1].lower()
    if ext == ".pdf":
        text = _load_pdf(path)
    elif ext == ".docx":
        text = _load_docx(path)
    elif ext in (".html", ".htm", ".xhtml"):
        text = _load_html(path)
    else:
        text = _read_text(path)
    text = text.replace("\r\n", "\n").replace("\r", "\n")
    return re.sub(r"[ \t]+\n", "\n", text)


FILETYPES = [
    ("Documents", "*.txt *.md *.pdf *.docx *.html *.htm"),
    ("All files", "*.*"),
]

#!/usr/bin/env python3
"""Simple document reader for macOS: reads a document aloud or saves it as audio.

Run:  python3 reader.py            (opens a file picker)
  or: python3 reader.py my_file.docx

Supports .txt, .md, .rtf, .html, .doc, .docx, .odt (built in)
and .pdf (needs a one-time:  pip3 install pypdf)
"""
import subprocess
import sys
import tempfile
from pathlib import Path

TEXTUTIL_TYPES = {".rtf", ".rtfd", ".html", ".htm", ".doc", ".docx", ".odt", ".webarchive"}


def pick_file():
    script = 'POSIX path of (choose file with prompt "Choose a document to read")'
    result = subprocess.run(["osascript", "-e", script], capture_output=True, text=True)
    if result.returncode != 0:
        return None  # user cancelled
    return Path(result.stdout.strip())


def extract_text(path):
    suffix = path.suffix.lower()
    if suffix == ".pdf":
        try:
            from pypdf import PdfReader
        except ImportError:
            sys.exit("To read PDFs, first run this once in Terminal:\n  pip3 install pypdf")
        return "\n".join((page.extract_text() or "") for page in PdfReader(str(path)).pages)
    if suffix in TEXTUTIL_TYPES:
        result = subprocess.run(
            ["textutil", "-convert", "txt", "-stdout", str(path)],
            capture_output=True, text=True,
        )
        if result.returncode != 0:
            sys.exit(f"Could not open the file: {result.stderr.strip()}")
        return result.stdout
    return path.read_text(errors="replace")


def ask(question, default):
    answer = input(f"{question} [{default}]: ").strip()
    return answer or default


def main():
    if len(sys.argv) > 1:
        path = Path(sys.argv[1]).expanduser()
    else:
        path = pick_file()
        if path is None:
            return
    if not path.exists():
        sys.exit(f"File not found: {path}")

    text = extract_text(path).strip()
    if not text:
        sys.exit("No readable text was found in that document.")
    print(f"Loaded {path.name}: about {len(text.split())} words.")

    rate = ask("Speed in words per minute (slow 140, normal 175, fast 220)", "175")
    voice = ask("Voice name (press Enter for your default; list with: say -v '?')", "")
    mode = ask("Type 1 to listen now, or 2 to save as an audio file", "1")

    cmd = ["say", "-r", rate]
    if voice:
        cmd += ["-v", voice]

    with tempfile.NamedTemporaryFile("w", suffix=".txt", delete=False) as f:
        f.write(text)
        temp_path = f.name

    try:
        if mode == "2":
            out = path.with_suffix(".aiff")
            subprocess.run(cmd + ["-o", str(out), "-f", temp_path], check=True)
            print(f"Saved: {out}")
        else:
            print("Reading... press Ctrl+C to stop.")
            subprocess.run(cmd + ["-f", temp_path], check=True)
    except KeyboardInterrupt:
        print("\nStopped.")
    except subprocess.CalledProcessError:
        print("Speech failed. Check that the voice name is correct.")
    finally:
        Path(temp_path).unlink(missing_ok=True)


if __name__ == "__main__":
    main()

