import Cocoa
import Carbon.HIToolbox
import Vision

// Menu-bar OCR: hotkey -> native region selection -> Vision OCR -> clipboard.
// No windows, no web runtime, no dependencies; idle cost is a status item and an event hotkey.

final class App: NSObject, NSApplicationDelegate {
    private let statusItem = NSStatusBar.system.statusItem(withLength: NSStatusItem.squareLength)
    private let previewItem = NSMenuItem(title: "No capture yet", action: nil, keyEquivalent: "")
    private var hotKeyRef: EventHotKeyRef?
    private var busy = false

    func applicationDidFinishLaunching(_ note: Notification) {
        setIcon("text.viewfinder")

        let menu = NSMenu()
        let capture = NSMenuItem(title: "Capture Text", action: #selector(capture), keyEquivalent: "o")
        capture.keyEquivalentModifierMask = [.control, .option]
        capture.target = self
        menu.addItem(capture)
        previewItem.isEnabled = false
        menu.addItem(previewItem)
        menu.addItem(.separator())
        menu.addItem(withTitle: "Quit", action: #selector(NSApplication.terminate(_:)), keyEquivalent: "q")
        statusItem.menu = menu

        registerHotKey()
    }

    private func setIcon(_ symbol: String) {
        statusItem.button?.image = NSImage(systemSymbolName: symbol, accessibilityDescription: "OCR")
    }

    // Ctrl+Option+O. Carbon hotkeys need no Accessibility permission.
    private func registerHotKey() {
        var spec = EventTypeSpec(eventClass: OSType(kEventClassKeyboard), eventKind: UInt32(kEventHotKeyPressed))
        InstallEventHandler(GetApplicationEventTarget(), { _, _, ctx in
            let app = Unmanaged<App>.fromOpaque(ctx!).takeUnretainedValue()
            DispatchQueue.main.async { app.capture() }
            return noErr
        }, 1, &spec, Unmanaged.passUnretained(self).toOpaque(), nil)
        let id = EventHotKeyID(signature: OSType(0x4F435254), id: 1) // 'OCRT'
        RegisterEventHotKey(UInt32(kVK_ANSI_O), UInt32(controlKey | optionKey), id,
                            GetApplicationEventTarget(), 0, &hotKeyRef)
    }

    @objc func capture() {
        guard !busy else { return }
        busy = true
        let path = NSTemporaryDirectory() + "ocr-\(UUID().uuidString).png"

        // -i interactive selection (Esc cancels), -x no shutter sound.
        let task = Process()
        task.executableURL = URL(fileURLWithPath: "/usr/sbin/screencapture")
        task.arguments = ["-i", "-x", path]
        task.terminationHandler = { [weak self] _ in
            DispatchQueue.global(qos: .userInitiated).async { self?.recognize(path) }
        }
        do { try task.run() } catch { finish(nil, error: "Could not run screencapture") }
    }

    private func recognize(_ path: String) {
        defer { try? FileManager.default.removeItem(atPath: path) }
        guard FileManager.default.fileExists(atPath: path) else {
            return finish(nil, error: nil) // cancelled
        }
        let request = VNRecognizeTextRequest()
        request.recognitionLevel = .accurate
        request.usesLanguageCorrection = true
        request.automaticallyDetectsLanguage = true
        do {
            try VNImageRequestHandler(url: URL(fileURLWithPath: path)).perform([request])
        } catch {
            return finish(nil, error: "OCR failed: \(error.localizedDescription)")
        }
        let lines = (request.results ?? []).compactMap { $0.topCandidates(1).first?.string }
        finish(lines.joined(separator: "\n"), error: nil)
    }

    private func finish(_ text: String?, error: String?) {
        DispatchQueue.main.async {
            self.busy = false
            if let error = error { self.previewItem.title = error; NSSound.beep(); return }
            guard let text = text else { return }
            if text.isEmpty {
                self.previewItem.title = "No text found"
                NSSound.beep()
                return
            }
            let pb = NSPasteboard.general
            pb.clearContents()
            pb.setString(text, forType: .string)
            let oneLine = text.replacingOccurrences(of: "\n", with: " ")
            self.previewItem.title = "Copied: " + String(oneLine.prefix(50)) + (oneLine.count > 50 ? "…" : "")
            NSSound(named: "Pop")?.play()
            self.setIcon("checkmark.circle")
            DispatchQueue.main.asyncAfter(deadline: .now() + 1.2) { self.setIcon("text.viewfinder") }
        }
    }
}

