"""Build the offline dictionary database from Princeton WordNet 3.0 files.

Usage: python build_db.py [path/to/wordnet/dict] [output.db]

The WordNet folder must contain data.noun, index.noun, etc. NLTK's
`nltk.download("wordnet")` produces one at ~/nltk_data/corpora/wordnet.
"""
import os
import re
import sqlite3
import sys

POS_FILES = {"noun": "n", "verb": "v", "adj": "a", "adv": "r"}
SCHEMA = """
CREATE TABLE synsets (id TEXT PRIMARY KEY, pos TEXT, definition TEXT, examples TEXT);
CREATE TABLE lemmas (word TEXT, synset_id TEXT, rank INTEGER);
CREATE TABLE antonyms (word TEXT, synset_id TEXT, antonym TEXT);
CREATE TABLE words (word TEXT PRIMARY KEY);
CREATE INDEX idx_lemmas_word ON lemmas(word);
CREATE INDEX idx_lemmas_synset ON lemmas(synset_id);
CREATE INDEX idx_antonyms_word ON antonyms(word);
"""

DEFAULT_DIRS = [
    "~/nltk_data/corpora/wordnet",
    "/usr/share/nltk_data/corpora/wordnet",
    "/usr/local/share/nltk_data/corpora/wordnet",
    "/opt/homebrew/share/nltk_data/corpora/wordnet",
    "/usr/share/wordnet",
    "/usr/local/WordNet-3.0/dict",
    "/opt/homebrew/opt/wordnet/dict",
]


def find_wordnet_dir():
    for d in DEFAULT_DIRS:
        d = os.path.expanduser(d)
        if os.path.exists(os.path.join(d, "data.noun")):
            return d
    return None


def clean(word):
    return re.sub(r"\(.*?\)$", "", word).replace("_", " ").lower()


def parse_data(path, pos):
    """Yield (synset_id, pos, words, definition, examples, antonym_pairs)."""
    with open(path, encoding="utf-8") as f:
        for line in f:
            if line.startswith("  ") or not line.strip():
                continue  # license header
            head, _, gloss = line.partition(" | ")
            t = head.split()
            offset = t[0]
            n_words = int(t[3], 16)
            words = [clean(t[4 + 2 * i]) for i in range(n_words)]
            i = 4 + 2 * n_words
            n_ptr = int(t[i])
            i += 1
            ants = []
            for _ in range(n_ptr):
                sym, target_off, target_pos, st = t[i : i + 4]
                i += 4
                if sym == "!" and st != "0000":
                    ants.append((int(st[:2], 16), target_pos, target_off, int(st[2:], 16)))
            parts = [p.strip() for p in gloss.strip().split("; ")]
            examples = [p.strip('"') for p in parts if p.startswith('"')]
            definition = "; ".join(p for p in parts if not p.startswith('"'))
            yield f"{pos}{offset}", words, definition, examples, ants


def build(wordnet_dir, db_path, progress=None):
    tmp = db_path + ".tmp"
    if os.path.exists(tmp):
        os.remove(tmp)
    db = sqlite3.connect(tmp)
    db.executescript(SCHEMA)

    synset_words = {}  # (pos, offset) -> words
    raw_ants = []
    for fname, pos in POS_FILES.items():
        if progress:
            progress(f"Reading {fname}...")
        for sid, words, definition, examples, ants in parse_data(
            os.path.join(wordnet_dir, f"data.{fname}"), pos
        ):
            synset_words[(pos, sid[1:])] = words
            db.execute(
                "INSERT INTO synsets VALUES (?,?,?,?)",
                (sid, pos, definition, "\n".join(examples)),
            )
            for src, tpos, toff, tgt in ants:
                raw_ants.append((sid, words[src - 1], tpos, toff, tgt))

    for fname, pos in POS_FILES.items():
        with open(os.path.join(wordnet_dir, f"index.{fname}"), encoding="utf-8") as f:
            for line in f:
                if line.startswith("  ") or not line.strip():
                    continue
                t = line.split()
                count = int(t[2])
                for rank, off in enumerate(t[-count:]):
                    db.execute(
                        "INSERT INTO lemmas VALUES (?,?,?)",
                        (clean(t[0]), f"{pos}{off}", rank),
                    )

    for sid, word, tpos, toff, tgt in raw_ants:
        target_words = synset_words.get(("a" if tpos == "s" else tpos, toff))
        if target_words and tgt - 1 < len(target_words):
            db.execute("INSERT INTO antonyms VALUES (?,?,?)", (word, sid, target_words[tgt - 1]))

    db.execute("INSERT INTO words SELECT DISTINCT word FROM lemmas")
    db.commit()
    db.close()
    os.replace(tmp, db_path)


if __name__ == "__main__":
    src = sys.argv[1] if len(sys.argv) > 1 else find_wordnet_dir()
    out = sys.argv[2] if len(sys.argv) > 2 else os.path.join(os.path.dirname(__file__), "dictionary.db")
    if not src:
        sys.exit("WordNet files not found. Pass the folder containing data.noun as an argument.")
    build(src, out, print)
    print(f"Wrote {out}")

#!/usr/bin/env python3
"""Build lexicon.db from Princeton WordNet 3.0 (one-time, needs network unless --dict is given).

Usage:
    python3 build_db.py                  # downloads WordNet 3.0 (~12 MB)
    python3 build_db.py --dict /path/to/dict   # use an extracted WordNet "dict" directory
"""
import argparse
import io
import os
import sqlite3
import tarfile
import urllib.request

URL = "https://wordnetcode.princeton.edu/3.0/WordNet-3.0.tar.gz"
POS_FILES = {"n": "noun", "v": "verb", "a": "adj", "r": "adv"}
OUT = os.path.join(os.path.dirname(os.path.abspath(__file__)), "lexicon.db")


def load_files(dict_dir):
    """Return {filename: list of lines} for the index.* and data.* files."""
    names = [f"{kind}.{name}" for kind in ("index", "data") for name in POS_FILES.values()]
    files = {}
    if dict_dir:
        for n in names:
            with open(os.path.join(dict_dir, n), encoding="utf-8") as f:
                files[n] = f.read().splitlines()
        return files
    print("Downloading WordNet 3.0 ...")
    with urllib.request.urlopen(URL) as r:
        blob = r.read()
    with tarfile.open(fileobj=io.BytesIO(blob), mode="r:gz") as tar:
        for m in tar.getmembers():
            base = os.path.basename(m.name)
            if "/dict/" in m.name and base in names:
                files[base] = tar.extractfile(m).read().decode("utf-8").splitlines()
    missing = set(names) - set(files)
    if missing:
        raise SystemExit(f"Missing files in archive: {sorted(missing)}")
    return files


def clean(word):
    # Adjectives may carry a syntactic marker like "big(a)"; underscores join phrases.
    if word.endswith(")") and "(" in word:
        word = word[: word.rindex("(")]
    return word.replace("_", " ")


def parse_data(lines, pos, synsets, words_of, raw_ants):
    for line in lines:
        if line.startswith("  "):  # license header
            continue
        head, _, gloss = line.partition(" | ")
        t = head.split()
        offset = t[0]
        wcnt = int(t[3], 16)
        words = [clean(t[4 + 2 * i]) for i in range(wcnt)]
        i = 4 + 2 * wcnt
        pcnt = int(t[i])
        key = (pos, offset)
        sid = len(synsets) + 1
        synsets[key] = sid
        words_of[sid] = words
        for p in range(pcnt):
            sym, toff, tpos, st = t[i + 1 + 4 * p : i + 5 + 4 * p]
            if sym == "!" and st != "0000":
                src, tgt = int(st[:2], 16), int(st[2:], 16)
                if src and tgt:
                    raw_ants.append((sid, src - 1, ("a" if tpos == "s" else tpos, toff), tgt - 1))
        parts = gloss.strip().split("; ")
        defn = "; ".join(p for p in parts if not p.startswith('"'))
        exs = [p.strip('"') for p in parts if p.startswith('"')]
        yield sid, pos, defn, "\n".join(exs)


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--dict", help="path to an extracted WordNet dict directory")
    args = ap.parse_args()
    files = load_files(args.dict)

    synsets, words_of, raw_ants, rows = {}, {}, [], []
    for pos, name in POS_FILES.items():
        rows.extend(parse_data(files[f"data.{name}"], pos, synsets, words_of, raw_ants))

    if os.path.exists(OUT):
        os.remove(OUT)
    db = sqlite3.connect(OUT)
    db.executescript(
        """
        CREATE TABLE synsets(id INTEGER PRIMARY KEY, pos TEXT, gloss TEXT, examples TEXT);
        CREATE TABLE synset_words(synset_id INTEGER, word TEXT);
        CREATE TABLE lemmas(word TEXT, pos TEXT, rank INTEGER, synset_id INTEGER);
        CREATE TABLE antonyms(synset_id INTEGER, word TEXT, ant TEXT);
        """
    )
    db.executemany("INSERT INTO synsets VALUES(?,?,?,?)", rows)
    db.executemany(
        "INSERT INTO synset_words VALUES(?,?)",
        ((sid, w) for sid, ws in words_of.items() for w in ws),
    )

    lemma_rows = []
    for pos, name in POS_FILES.items():
        for line in files[f"index.{name}"]:
            if line.startswith("  "):
                continue
            t = line.split()
            word = t[0].replace("_", " ").lower()
            n_ptr = int(t[3])
            sense_cnt = int(t[4 + n_ptr])
            offsets = t[6 + n_ptr : 6 + n_ptr + sense_cnt]
            for rank, off in enumerate(offsets):
                lemma_rows.append((word, pos, rank, synsets[(pos, off)]))
    db.executemany("INSERT INTO lemmas VALUES(?,?,?,?)", lemma_rows)

    ants = set()
    for sid, si, tkey, ti in raw_ants:
        tsid = synsets.get(tkey)
        if tsid:
            ants.add((sid, words_of[sid][si].lower(), words_of[tsid][ti]))
    db.executemany("INSERT INTO antonyms VALUES(?,?,?)", ants)

    db.executescript(
        """
        CREATE INDEX lemmas_word ON lemmas(word, pos, rank);
        CREATE INDEX synset_words_sid ON synset_words(synset_id);
        CREATE INDEX antonyms_sid ON antonyms(synset_id, word);
        """
    )
    db.commit()
    db.execute("VACUUM")
    db.close()
    print(f"Wrote {OUT} ({os.path.getsize(OUT) / 1e6:.1f} MB): "
          f"{len(rows)} senses, {len(lemma_rows)} lemma entries.")


if __name__ == "__main__":
    main()

"""Build lexicon.db from Princeton WordNet 3.0 (one-time step, needs network
unless --wordnet-dir points at an existing 'dict' folder).

    python build_db.py                      # download WordNet and build
    python build_db.py --wordnet-dir DIR    # use local WordNet dict files
    python build_db.py --sample             # tiny hand-written DB for testing
"""
import argparse
import io
import os
import re
import sqlite3
import tarfile
import urllib.request

URL = "https://wordnetcode.princeton.edu/3.0/WNdb-3.0.tar.gz"
POS_FILES = {"n": "noun", "v": "verb", "a": "adj", "r": "adv"}
KEPT_POINTERS = {"@": "hypernym", "~": "hyponym", "&": "similar"}
OUT = os.path.join(os.path.dirname(os.path.abspath(__file__)), "lexicon.db")

SCHEMA = """
CREATE TABLE synsets (id TEXT PRIMARY KEY, pos TEXT NOT NULL,
                      definition TEXT NOT NULL, examples TEXT NOT NULL);
CREATE TABLE senses (lemma TEXT NOT NULL, synset TEXT NOT NULL, rank INTEGER NOT NULL);
CREATE TABLE members (synset TEXT NOT NULL, lemma TEXT NOT NULL, ord INTEGER NOT NULL);
CREATE TABLE relations (synset TEXT NOT NULL, kind TEXT NOT NULL, target TEXT NOT NULL);
CREATE TABLE antonyms (lemma TEXT NOT NULL, synset TEXT NOT NULL, antonym TEXT NOT NULL);
"""
INDEXES = """
CREATE INDEX senses_lemma ON senses(lemma, rank);
CREATE INDEX members_synset ON members(synset, ord);
CREATE INDEX relations_synset ON relations(synset, kind);
CREATE INDEX antonyms_key ON antonyms(synset, lemma);
"""


def clean(word):
    return re.sub(r"\(\w+\)$", "", word).replace("_", " ")


def key(offset, pos):
    return f"{offset}{'a' if pos == 's' else pos}"


def split_gloss(gloss):
    parts = [p.strip() for p in gloss.split(";")]
    definition, examples = [], []
    for p in parts:
        if p.startswith('"'):
            examples.append(p.strip('"'))
        elif not examples:
            definition.append(p)
    return "; ".join(definition), examples


def parse_data(path, synsets):
    with open(path, encoding="utf-8") as f:
        for line in f:
            if line.startswith("  "):  # license header
                continue
            head, _, gloss = line.partition("|")
            t = head.split()
            offset, ss_type = t[0], t[2]
            n = int(t[3], 16)
            words = [clean(t[4 + 2 * i]) for i in range(n)]
            i = 4 + 2 * n
            ptrs = []
            for _ in range(int(t[i])):
                ptrs.append(tuple(t[i + 1:i + 5]))
                i += 4
            definition, examples = split_gloss(gloss)
            synsets[key(offset, ss_type)] = {
                "pos": "a" if ss_type == "s" else ss_type,
                "words": words, "ptrs": ptrs,
                "definition": definition, "examples": examples,
            }


def build(dict_dir):
    synsets = {}
    for code, name in POS_FILES.items():
        parse_data(os.path.join(dict_dir, f"data.{name}"), synsets)

    if os.path.exists(OUT):
        os.remove(OUT)
    db = sqlite3.connect(OUT)
    db.executescript(SCHEMA)

    for sid, s in synsets.items():
        db.execute("INSERT INTO synsets VALUES (?,?,?,?)",
                   (sid, s["pos"], s["definition"], "\n".join(s["examples"])))
        for order, w in enumerate(s["words"]):
            db.execute("INSERT INTO members VALUES (?,?,?)", (sid, w, order))
        for symbol, off, pos, st in s["ptrs"]:
            tid = key(off, pos)
            if symbol in KEPT_POINTERS:
                db.execute("INSERT INTO relations VALUES (?,?,?)",
                           (sid, KEPT_POINTERS[symbol], tid))
            elif symbol == "!" and st != "0000" and tid in synsets:
                src, dst = int(st[:2], 16), int(st[2:], 16)
                if src and dst:
                    db.execute("INSERT INTO antonyms VALUES (?,?,?)",
                               (s["words"][src - 1], sid,
                                synsets[tid]["words"][dst - 1]))

    # Sense order (most common first) comes from the index files.
    for code, name in POS_FILES.items():
        with open(os.path.join(dict_dir, f"index.{name}"), encoding="utf-8") as f:
            for line in f:
                if line.startswith("  "):
                    continue
                t = line.split()
                lemma, p_cnt = t[0].replace("_", " "), int(t[3])
                offsets = t[6 + p_cnt:]
                for rank, off in enumerate(offsets):
                    for k in (key(off, code), key(off, "s") if code == "a" else None):
                        if k and k in synsets:
                            db.execute("INSERT INTO senses VALUES (?,?,?)",
                                       (lemma, k, rank))
                            break
    db.executescript(INDEXES)
    db.commit()
    db.close()


def build_sample():
    if os.path.exists(OUT):
        os.remove(OUT)
    db = sqlite3.connect(OUT)
    db.executescript(SCHEMA)
    data = [
