"""Sudoku engine: solving, puzzle generation and logical hints."""
import random

DIFFICULTY_CLUES = {"Easy": 40, "Medium": 32, "Hard": 27, "Expert": 24}

ROWS = [[r * 9 + c for c in range(9)] for r in range(9)]
COLS = [[r * 9 + c for r in range(9)] for c in range(9)]
BOXES = [[(br * 3 + r) * 9 + bc * 3 + c for r in range(3) for c in range(3)]
         for br in range(3) for bc in range(3)]
UNITS = [("row", i, ROWS[i]) for i in range(9)] + \
        [("column", i, COLS[i]) for i in range(9)] + \
        [("box", i, BOXES[i]) for i in range(9)]
PEERS = [set() for _ in range(81)]
for _, _, cells in UNITS:
    for a in cells:
        PEERS[a].update(b for b in cells if b != a)


def candidates(grid, i):
    """Digits that can legally go in cell i given current grid."""
    used = {grid[p] for p in PEERS[i]}
    return [d for d in range(1, 10) if d not in used]


def _search(grid, limit, randomize=False):
    """Backtracking with fewest-candidates-first. Returns list of solutions (<= limit)."""
    best, best_c = None, None
    for i in range(81):
        if grid[i] == 0:
            c = candidates(grid, i)
            if best is None or len(c) < len(best_c):
                best, best_c = i, c
                if len(c) <= 1:
                    break
    if best is None:
        return [grid[:]]
    if randomize:
        random.shuffle(best_c)
    found = []
    for d in best_c:
        grid[best] = d
        found += _search(grid, limit - len(found), randomize)
        grid[best] = 0
        if len(found) >= limit:
            break
    return found


def solve(grid):
    s = _search(list(grid), 1)
    return s[0] if s else None


def count_solutions(grid, limit=2):
    return len(_search(list(grid), limit))


def generate(difficulty="Medium"):
    """Return (puzzle, solution) with a unique solution."""
    target = DIFFICULTY_CLUES[difficulty]
    solution = _search([0] * 81, 1, randomize=True)[0]
    puzzle = solution[:]
    order = list(range(81))
    random.shuffle(order)
    clues = 81
    for i in order:
        if clues <= target:
            break
        saved, puzzle[i] = puzzle[i], 0
        if count_solutions(puzzle) != 1:
            puzzle[i] = saved
        else:
            clues -= 1
    return puzzle, solution


def find_conflicts(grid):
    """Set of cell indices that share a digit with a peer."""
    bad = set()
    for i in range(81):
        if grid[i] and any(grid[p] == grid[i] for p in PEERS[i]):
            bad.add(i)
    return bad


def name(i):
    return f"R{i // 9 + 1}C{i % 9 + 1}"


def get_hint(grid, solution):
    """Return (cell, digit, explanation) for the next helpful move, or None if solved."""
    wrong = [i for i in range(81) if grid[i] and grid[i] != solution[i]]
    if wrong:
        i = wrong[0]
        return i, 0, f"{name(i)} contains a wrong number. Clear it."
    if all(grid):
        return None
    cands = {i: candidates(grid, i) for i in range(81) if grid[i] == 0}
    # Naked single
    for i, c in cands.items():
        if len(c) == 1:
            return i, c[0], (f"Naked single: {name(i)} can only be {c[0]}; "
                             f"every other digit already appears in its row, column or box.")
    # Hidden single
    for kind, _, cells in UNITS:
        for d in range(1, 10):
            spots = [i for i in cells if i in cands and d in cands[i]]
            if len(spots) == 1 and d not in {grid[i] for i in cells}:
                i = spots[0]
                return i, d, (f"Hidden single: in this {kind}, {d} can only go in {name(i)}.")
    # Fallback: most constrained cell, reveal from solution
    i = min(cands, key=lambda k: len(cands[k]))
    return i, solution[i], (f"No simple technique applies. The solution has {solution[i]} "
                            f"in {name(i)} (candidates were {cands[i]}).")

