            for dr, dc in dirs:
                ray, rr, cc = [], r + dr, c + dc
                while 0 <= rr < 8 and 0 <= cc < 8:
                    ray.append(rr * 8 + cc)
                    rr += dr
                    cc += dc
                if ray:
                    rays.append(ray)
            out.append(rays)
    return kn, kg, rd, ro


KN_T, KG_T, RAY_D, RAY_O = _build_tables()

# Squares whose movement (from or to) removes castling rights.
CASTLE_LOSS = {60: "KQ", 63: "K", 56: "Q", 4: "kq", 7: "k", 0: "q"}


class Position:
    __slots__ = ("board", "turn", "castling", "ep", "halfmove", "fullmove")

    def __init__(self, board, turn, castling, ep, halfmove, fullmove):
        self.board = board
        self.turn = turn
        self.castling = castling
        self.ep = ep
        self.halfmove = halfmove
        self.fullmove = fullmove

    def key(self):
        return ("".join(self.board), self.turn, self.castling, self.ep)


def start_position():
    return Position(list(START), "w", "KQkq", None, 0, 1)


def attacked(b, sq, by_white):
    """Is `sq` attacked by the given side?"""
    r, c = sq >> 3, sq & 7
    pr = r + 1 if by_white else r - 1
    if 0 <= pr < 8:
        pawn = "P" if by_white else "p"
        if c > 0 and b[pr * 8 + c - 1] == pawn:
            return True
        if c < 7 and b[pr * 8 + c + 1] == pawn:
            return True
    knight = "N" if by_white else "n"
    for t in KN_T[sq]:
        if b[t] == knight:
            return True
    king = "K" if by_white else "k"
    for t in KG_T[sq]:
        if b[t] == king:
            return True
    for rays, sliders in ((RAY_D[sq], "BQ" if by_white else "bq"),
                          (RAY_O[sq], "RQ" if by_white else "rq")):
        for ray in rays:
            for t in ray:
                q = b[t]
                if q != ".":
                    if q in sliders:
                        return True
                    break
    return False


def in_check(pos):
    w = pos.turn == "w"
    ksq = pos.board.index("K" if w else "k")
    return attacked(pos.board, ksq, not w)


def pseudo_moves(pos):
    b = pos.board
    w = pos.turn == "w"
