"""Vocabulary trainer logic: storage, spaced repetition, quiz helpers. No UI code."""
import csv
import json
import os
import random
import sys
import tempfile
import unicodedata
from datetime import date, timedelta

INTERVALS = [0, 1, 2, 4, 8, 16]  # days until next review, indexed by Leitner box
MAX_BOX = len(INTERVALS) - 1

SAMPLE = [
    ("hola", "hello"), ("gracias", "thank you"), ("adiós", "goodbye"),
    ("por favor", "please"), ("agua", "water"), ("casa", "house"),
    ("libro", "book"), ("gato", "cat"), ("perro", "dog"), ("comida", "food"),
]


def data_dir():
    if sys.platform == "win32":
        base = os.environ.get("APPDATA") or os.path.expanduser("~")
    elif sys.platform == "darwin":
        base = os.path.expanduser("~/Library/Application Support")
    else:
        base = os.environ.get("XDG_DATA_HOME") or os.path.expanduser("~/.local/share")
    return os.path.join(base, "vocab-trainer")


def new_word(term, translation):
    return {"term": term.strip(), "translation": translation.strip(),
            "box": 0, "due": date.today().isoformat(), "correct": 0, "wrong": 0}


class Store:
    def __init__(self, path=None):
        self.path = path or os.path.join(data_dir(), "words.json")
        self.words = []
        self.load()

    def load(self):
        try:
            with open(self.path, encoding="utf-8") as f:
                self.words = json.load(f)
        except FileNotFoundError:
            self.words = [new_word(t, tr) for t, tr in SAMPLE]
            self.save()
        except (json.JSONDecodeError, OSError):
            # Keep the unreadable file around rather than overwriting it.
            try:
                os.replace(self.path, self.path + ".corrupt")
            except OSError:
                pass
            self.words = []

    def save(self):
        os.makedirs(os.path.dirname(self.path), exist_ok=True)
        fd, tmp = tempfile.mkstemp(dir=os.path.dirname(self.path), suffix=".tmp")
        with os.fdopen(fd, "w", encoding="utf-8") as f:
            json.dump(self.words, f, ensure_ascii=False, indent=1)
        os.replace(tmp, self.path)

    def add(self, term, translation):
        if not term.strip() or not translation.strip():
            return False
        key = term.strip().casefold()
        if any(w["term"].casefold() == key for w in self.words):
            return False
        self.words.append(new_word(term, translation))
        return True

    def remove(self, word):
        self.words.remove(word)

    def import_csv(self, path):
        """Import 'term,translation' rows. Returns number of new words added."""
        added = 0
        with open(path, newline="", encoding="utf-8-sig") as f:
            for row in csv.reader(f):
                if len(row) >= 2 and self.add(row[0], row[1]):
                    added += 1
        return added

    def export_csv(self, path):
        with open(path, "w", newline="", encoding="utf-8") as f:
            w = csv.writer(f)
            for word in self.words:
                w.writerow([word["term"], word["translation"]])


def is_due(word, today=None):
    return word["due"] <= (today or date.today()).isoformat()


def pick_session(words, n=10):
    """Due words first (lowest box first), topped up with random others."""
    due = sorted((w for w in words if is_due(w)), key=lambda w: (w["box"], random.random()))
    chosen = due[:n]
    if len(chosen) < n:
        rest = [w for w in words if w not in chosen]
        random.shuffle(rest)
        chosen += rest[:n - len(chosen)]
    random.shuffle(chosen)
    return chosen


def grade(word, correct, today=None):
    today = today or date.today()
    if correct:
        word["correct"] += 1
        word["box"] = min(word["box"] + 1, MAX_BOX)
    else:
        word["wrong"] += 1
        word["box"] = 0
    word["due"] = (today + timedelta(days=INTERVALS[word["box"]])).isoformat()


def fields(reverse):
    """(question field, answer field)."""
    return ("translation", "term") if reverse else ("term", "translation")


def choices(words, word, answer_field, k=4):
    """The correct answer plus up to k-1 distractors, shuffled."""
    correct = word[answer_field]
    others = list({w[answer_field] for w in words if w[answer_field].casefold() != correct.casefold()})
    random.shuffle(others)
    opts = others[:k - 1] + [correct]
    random.shuffle(opts)
    return opts


def _norm(s):
    s = unicodedata.normalize("NFC", s).strip().casefold()
    return " ".join(s.split())


def _strip_accents(s):
    return "".join(c for c in unicodedata.normalize("NFD", s) if unicodedata.category(c) != "Mn")


def check_typed(guess, answer):
    """Exact match (case/space-insensitive) against any ';'-separated alternative.
    Returns 'exact', 'accent' (right except for diacritics), or None."""
    g = _norm(guess)
    if not g:
        return None
    alts = [_norm(a) for a in answer.split(";") if a.strip()]
    if g in alts:
        return "exact"
    if _strip_accents(g) in [_strip_accents(a) for a in alts]:
        return "accent"
    return None

