import Cocoa
import AVFoundation

// MARK: - Pitch detection (YIN)

final class PitchDetector {
    private let size = 2048
    private let decim: Int
    private let fs: Double
    private let minTau: Int
    private let maxTau: Int
    private var acc: [Float] = []
    private var cmnd: [Float]

    init(sampleRate: Double) {
        decim = max(1, Int((sampleRate / 24000).rounded()))
        fs = sampleRate / Double(decim)
        minTau = max(2, Int(fs / 500))
        maxTau = min(Int(fs / 60), size / 2)
        cmnd = [Float](repeating: 1, count: maxTau + 2)
        acc.reserveCapacity(size * 2)
    }

    /// Feeds mono samples; returns a frequency whenever a full analysis window completes.
    func feed(_ p: UnsafePointer<Float>, count: Int) -> (ran: Bool, freq: Double?) {
        var i = 0
        while i + decim <= count {
            var s: Float = 0
            for k in 0..<decim { s += p[i + k] }
            acc.append(s / Float(decim))
            i += decim
        }
        guard acc.count >= size else { return (false, nil) }
        let f = analyze()
        acc.removeFirst(size / 2)
        return (true, f)
    }

    private func analyze() -> Double? {
        var energy: Float = 0
        for v in acc[0..<size] { energy += v * v }
        if (energy / Float(size)).squareRoot() < 0.01 { return nil }

        let w = size - maxTau
        var running: Float = 0
        acc.withUnsafeBufferPointer { x in
            for tau in 1...maxTau {
                var d: Float = 0
                for j in 0..<w {
                    let t = x[j] - x[j + tau]
                    d += t * t
                }
                running += d
                cmnd[tau] = running > 0 ? d * Float(tau) / running : 1
            }
        }

        var tau = minTau
        while tau < maxTau {
            if cmnd[tau] < 0.15 {
                while tau + 1 < maxTau && cmnd[tau + 1] < cmnd[tau] { tau += 1 }
                let a = cmnd[tau - 1], b = cmnd[tau], c = cmnd[tau + 1]
                let denom = a - 2 * b + c
                let shift = denom != 0 ? Double(0.5 * (a - c) / denom) : 0
                return fs / (Double(tau) + shift)
            }
            tau += 1
        }
        return nil
    }
}

