final class TunerView: NSView {
    private static let names = ["C", "C♯", "D", "D♯", "E", "F", "F♯", "G", "G♯", "A", "A♯", "B"]
    private var note = "–"
    private var freq: Double?
    private var cents = 0.0
    private var misses = 0

    override var isFlipped: Bool { true }

    func update(_ f: Double?) {
        guard let f = f else {
            misses += 1
            if misses > 4 && freq != nil { freq = nil; note = "–"; needsDisplay = true }
            return
        }
        misses = 0
        let midi = 69 + 12 * log2(f / 440)
        let n = Int(midi.rounded())
        let c = (midi - Double(n)) * 100
        let nameChanged = freq == nil || note != Self.label(n)
        cents = nameChanged ? c : cents + (c - cents) * 0.4
        note = Self.label(n)
        freq = f
        needsDisplay = true
    }

    private static func label(_ n: Int) -> String {
        names[((n % 12) + 12) % 12] + String(n / 12 - 1)
    }

    override func draw(_ dirtyRect: NSRect) {
        NSColor(white: 0.1, alpha: 1).setFill()
        bounds.fill()

        let inTune = freq != nil && abs(cents) < 5
        let accent: NSColor = freq == nil ? .gray : (inTune ? .systemGreen : .systemOrange)

        func text(_ s: String, size: CGFloat, weight: NSFont.Weight, color: NSColor, y: CGFloat) {
            let a: [NSAttributedString.Key: Any] = [
                .font: NSFont.systemFont(ofSize: size, weight: weight), .foregroundColor: color]
            let str = NSAttributedString(string: s, attributes: a)
            let sz = str.size()
            str.draw(at: NSPoint(x: (bounds.width - sz.width) / 2, y: y))
        }

        text(note, size: 84, weight: .semibold, color: accent, y: 30)
        text(freq.map { String(format: "%.1f Hz", $0) } ?? "Play a string",
             size: 16, weight: .regular, color: .lightGray, y: 140)

        // Meter: -50...+50 cents
        let mx = bounds.width * 0.1, mw = bounds.width * 0.8, my: CGFloat = 220
        for t in stride(from: -50, through: 50, by: 10) {
            let x = mx + mw * CGFloat(t + 50) / 100
            let h: CGFloat = t == 0 ? 36 : 18
            NSColor(white: t == 0 ? 0.8 : 0.4, alpha: 1).setStroke()
            let p = NSBezierPath()
            p.lineWidth = t == 0 ? 3 : 1.5
            p.move(to: NSPoint(x: x, y: my - h / 2))
            p.line(to: NSPoint(x: x, y: my + h / 2))
            p.stroke()
        }
        if freq != nil {
            let x = mx + mw * CGFloat(max(-50, min(50, cents)) + 50) / 100
            accent.setFill()
            NSBezierPath(roundedRect: NSRect(x: x - 4, y: my - 28, width: 8, height: 56),
                         xRadius: 4, yRadius: 4).fill()
            text(String(format: "%+.0f cents", cents), size: 14, weight: .regular,
                 color: .lightGray, y: my + 44)
        }
    }
}

