// MARK: - Audio

/// Generates clicks sample-accurately inside the render callback.
/// Parameters are plain word-sized values written from the main thread and read
/// on the audio thread; a stale read only delays a change by one buffer.
final class Clicker {
    var bpm = 120.0
    var beatsPerBar = 4
    var onBeat: ((Int) -> Void)?
    var restartRequested = true

    private let sampleRate: Double
    private var untilNext = 0.0
    private var beat = 0
    private var phase = 0.0
    private var step = 0.0
    private var env = 0.0
    private let decay: Double

    init(sampleRate: Double) {
        self.sampleRate = sampleRate
        decay = exp(-1.0 / (sampleRate * 0.012))
    }

    func render(_ frames: Int, _ out: UnsafeMutableAudioBufferListPointer) {
        guard let first = out.first, let base = first.mData?.assumingMemoryBound(to: Float.self) else { return }
        if restartRequested { restartRequested = false; untilNext = 0; beat = 0; env = 0 }
        let interval = 60.0 / max(bpm, 1) * sampleRate
        let bar = max(beatsPerBar, 1)
        for i in 0..<frames {
            if untilNext <= 0 {
                let idx = beat % bar
                step = 2 * Double.pi * (idx == 0 ? 1600 : 1000) / sampleRate
                phase = 0; env = 1
                beat = idx + 1
                untilNext += interval
                let cb = onBeat
                DispatchQueue.main.async { cb?(idx) }
            }
            untilNext -= 1
            base[i] = Float(sin(phase) * env * 0.6)
            phase += step
            env *= decay
        }
        for b in 1..<max(out.count, 1) where b < out.count {
            if let d = out[b].mData { memcpy(d, base, frames * MemoryLayout<Float>.size) }
        }
    }
}

final class AudioEngine {
    private var engine: AVAudioEngine?
    private(set) var clicker: Clicker?

    /// The engine is created lazily on first play so launch stays fast.
    func start(bpm: Double, beats: Int, onBeat: @escaping (Int) -> Void) {
        if engine == nil {
            let e = AVAudioEngine()
            let sr = e.outputNode.outputFormat(forBus: 0).sampleRate
            let c = Clicker(sampleRate: sr > 0 ? sr : 44100)
            let fmt = AVAudioFormat(standardFormatWithSampleRate: c.sampleRateValue, channels: 1)!
            let node = AVAudioSourceNode(format: fmt) { _, _, frames, abl -> OSStatus in
                c.render(Int(frames), UnsafeMutableAudioBufferListPointer(abl))
                return noErr
            }
            e.attach(node)
            e.connect(node, to: e.mainMixerNode, format: fmt)
            engine = e; clicker = c
        }
        clicker?.bpm = bpm
        clicker?.beatsPerBar = beats
        clicker?.onBeat = onBeat
        clicker?.restartRequested = true
        try? engine?.start()
    }

    /// Pausing the engine drops CPU use to zero while stopped.
    func stop() {
        clicker?.onBeat = nil
        engine?.pause()
    }
}

extension Clicker {
    var sampleRateValue: Double { Mirror(reflecting: self).children.first { $0.label == "sampleRate" }?.value as? Double ?? 44100 }
}

