        let n = max(beats, 1)
        let d = min(28, (bounds.width - CGFloat(n - 1) * 8) / CGFloat(n))
        let total = CGFloat(n) * d + CGFloat(n - 1) * 8
        var x = (bounds.width - total) / 2
        let y = (bounds.height - d) / 2
        for i in 0..<n {
            let r = NSRect(x: x, y: y, width: d, height: d)
            let color: NSColor = i == 0 ? .systemOrange : .controlAccentColor
            (i == active ? color : color.withAlphaComponent(0.2)).setFill()
            NSBezierPath(ovalIn: r).fill()
            x += d + 8
        }
    }
}

