final class Controller: NSObject {
    let audio = AudioEngine()
    var bpm = 120.0 { didSet { bpm = min(max(bpm.rounded(), 20), 300); sync() } }
    var beats = 4
    var playing = false
    var taps: [TimeInterval] = []

    let bpmLabel = NSTextField(labelWithString: "120")
    let slider = NSSlider(value: 120, minValue: 20, maxValue: 300, target: nil, action: nil)
    let playButton = NSButton(title: "Start", target: nil, action: nil)
    let beatView = BeatView()
    let numPopup = NSPopUpButton()
    let denPopup = NSPopUpButton()

    func sync() {
        bpmLabel.stringValue = String(Int(bpm))
        slider.doubleValue = bpm
        audio.clicker?.bpm = bpm
    }

    @objc func sliderChanged(_ s: NSSlider) { bpm = s.doubleValue }
    @objc func nudgeUp() { bpm += 1 }
    @objc func nudgeDown() { bpm -= 1 }

    @objc func toggle() {
        playing.toggle()
        playButton.title = playing ? "Stop" : "Start"
        if playing {
            audio.start(bpm: bpm, beats: beats) { [weak self] i in self?.beatView.active = i }
        } else {
            audio.stop()
            beatView.active = -1
        }
    }

    @objc func tap() {
        let now = ProcessInfo.processInfo.systemUptime
        if let last = taps.last, now - last > 2 { taps.removeAll() }
        taps.append(now)
        if taps.count > 8 { taps.removeFirst() }
        if taps.count >= 2 {
            bpm = 60 * Double(taps.count - 1) / (taps.last! - taps.first!)
        }
    }

    @objc func signatureChanged() {
        beats = numPopup.indexOfSelectedItem + 1
        beatView.beats = beats
        audio.clicker?.beatsPerBar = beats
        audio.clicker?.restartRequested = playing
    }

    func buildWindow() -> NSWindow {
        bpmLabel.font = .monospacedDigitSystemFont(ofSize: 72, weight: .light)
        bpmLabel.alignment = .center
        let unit = NSTextField(labelWithString: "BPM")
        unit.textColor = .secondaryLabelColor

        slider.target = self; slider.action = #selector(sliderChanged)

