const waxing = elong < 180, k = Math.cos(elong * RAD);  // k: 1 new → -1 full
// Looking up with east on the left, the waxing Moon is lit on its west (right) side
ctx.fillStyle = "#f3f0e2";
ctx.beginPath(); ctx.arc(x, y, r, -Math.PI / 2, Math.PI / 2, !waxing); ctx.fill();
// The terminator: dark ellipse for a crescent, light ellipse for a gibbous Moon
ctx.fillStyle = k > 0 ? "#2a3350" : "#f3f0e2";
ctx.beginPath(); ctx.ellipse(x, y, Math.max(0.01, Math.abs(k) * r), r, 0, 0, 7); ctx.fill();

